"use server";

import { signOut } from "@/auth";

export async function cerrarSesion() {
  await signOut({ redirectTo: "/login" });
}

"use client";

import { useEffect, useRef, useState } from "react";
import Link from "next/link";
import { Save2, Refresh2, DocumentDownload, TickCircle, CloseCircle, Warning2, ArrowRotateLeft } from "@/lib/icons";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import { RestaurarBackupDialog } from "./restaurar-backup-dialog";

const DRIVE_FOLDER_URL = "https://drive.google.com/open?id=14yBWDL6RcHztQ5hitZ71cLB4eak-O8ge";

interface Backup {
  id: string;
  nombre_archivo: string;
  tamano_bytes: string | null;
  creado_en: string;
  destino: string;
  origen: "programado" | "manual";
  solicitado_por: string | null;
  estado: "ok" | "error";
  error_detalle: string | null;
}

interface Restauracion {
  id: string;
  nombre_archivo: string;
  iniciado_en: string;
  finalizado_en: string | null;
  solicitado_por: string;
  backup_seguridad_previo: string | null;
  estado: "en_progreso" | "ok" | "error";
  error_detalle: string | null;
}

function euros(bytes: string | null): string {
  if (!bytes) return "—";
  const n = Number(bytes);
  if (!Number.isFinite(n)) return "—";
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(0)} KB`;
  return `${(n / (1024 * 1024)).toFixed(1)} MB`;
}

function formatearFecha(iso: string): string {
  return new Date(iso).toLocaleString("es-ES", { dateStyle: "medium", timeStyle: "short" });
}

function Badge({ tono, children }: { tono: "gris" | "verde" | "rojo"; children: React.ReactNode }) {
  const clases =
    tono === "verde"
      ? "bg-emerald-100 text-emerald-800 dark:bg-emerald-500/15 dark:text-emerald-400"
      : tono === "rojo"
        ? "bg-destructive/10 text-destructive"
        : "bg-muted text-muted-foreground";
  return <span className={`rounded px-1.5 py-0.5 text-[11px] font-medium ${clases}`}>{children}</span>;
}

/**
 * Panel de Admin > Backups — historial de copias de la base de datos
 * (kelatos_app + kelatos_stage), botón para pedir una de más además de la
 * diaria automática, y enlace directo a la carpeta de Google Drive donde
 * quedan guardadas. La API no puede ejecutar pg_dump/rclone por su cuenta
 * (corre en un contenedor deliberadamente aislado) — "Backup ahora" solo

 * encola la petición; un cron del VPS la recoge en menos de un minuto.
 */
export function BackupsAdminContenido() {
  const [backups, setBackups] = useState<Backup[]>([]);
  const [cargando, setCargando] = useState(false);
  const [error, setError] = useState("");
  const [solicitando, setSolicitando] = useState(false);
  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const [restauraciones, setRestauraciones] = useState<Restauracion[]>([]);
  const [restaurarObjetivo, setRestaurarObjetivo] = useState<{ archivo: string; fecha: string } | null>(null);

  async function cargar() {
    setCargando(true);
    setError("");
    try {
      const res = await fetch("/api/admin/backups");
      const data = await res.json();
      if (!data.ok) throw new Error(data.error || "Error desconocido");
      setBackups(data.backups || []);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Error desconocido");
    } finally {
      setCargando(false);
    }
  }

  async function cargarRestauraciones() {
    try {
      const res = await fetch("/api/admin/restore");
      const data = await res.json();
      if (data.ok) setRestauraciones(data.restauraciones || []);
    } catch {
      // silencioso — no es crítico para la vista principal de backups
    }
  }

  useEffect(() => {
    cargar();
    cargarRestauraciones();
    return () => { if (pollRef.current) clearInterval(pollRef.current); };
  }, []);

  async function pedirBackup() {
    setSolicitando(true);
    const totalAntes = backups.length;
    try {
      const res = await fetch("/api/admin/backups", { method: "POST" });
      const data = await res.json();
      if (!data.ok) throw new Error(data.error || "Error desconocido");
      toast.success("Backup solicitado — puede tardar hasta 1 minuto en aparecer aquí");

      // El cron del VPS revisa la solicitud cada minuto — se sondea cada
      // 5s hasta 90s para refrescar sola la lista en cuanto aparezca,
      // en vez de obligar a acordarse de pulsar "Actualizar" más tarde.
      let intentos = 0;
      pollRef.current = setInterval(async () => {
        intentos += 1;

      const r = await fetch("/api/admin/backups");
      const d = await r.json();
      if (d.ok && d.backups.length > totalAntes) {
        setBackups(d.backups);
        if (pollRef.current) clearInterval(pollRef.current);
      } else if (intentos >= 18) {
        if (pollRef.current) clearInterval(pollRef.current);
      }
    }, 5000);
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error desconocido");
  } finally {
    setSolicitando(false);
  }
}

return (
  <div className="space-y-4 p-5">
    <div className="flex items-center gap-2.5">
      <span className="flex size-9 items-center justify-center rounded-md bg-primary/10 text-primary">
        <Save2 className="size-5" />
      </span>
      <div>
        <h1 className="text-xl font-bold">Backups</h1>
        <p className="text-sm text-muted-foreground">Copia diaria automática (3:00) de la base de datos, guardada en Google Drive.</p>
      </div>
    </div>

    <div className="flex flex-wrap items-center gap-2">
      <Button className="gap-1.5" onClick={pedirBackup} disabled={solicitando}>
        <Save2 className="size-4" /> {solicitando ? "Solicitando…" : "Backup ahora"}
      </Button>
      <Button variant="outline" className="gap-1.5" nativeButton={false} render={<Link href={DRIVE_FOLDER_URL} target="_blank" rel="noreferrer" />}>
        <DocumentDownload className="size-4" /> Abrir carpeta en Drive
      </Button>
      <Button variant="ghost" size="icon" onClick={cargar} disabled={cargando} title="Actualizar">
        <Refresh2 className={cargando ? "size-4 animate-spin" : "size-4"} />
      </Button>
    </div>

    {error && (
      <div className="rounded-md border border-destructive/30 bg-destructive/10 px-4 py-3 text-sm text-destructive">
        Error al cargar: {error}
      </div>
    )}

    <div className="overflow-x-auto rounded-lg border bg-card">
      <table className="w-full text-sm">
        <thead className="bg-muted/50 text-xs text-muted-foreground">
          <tr>
            <th className="px-3 py-2 text-left font-medium">Fecha</th>

import { auth } from "@/auth";
import { esSuperadmin } from "@/lib/superadmin";
import { BackupsAdminContenido } from "./backups-admin-contenido";

export default async function BackupsAdminPage() {
  const session = await auth();
  const email = session?.user?.email?.toLowerCase() || "";
  if (!esSuperadmin(email)) {
    return (
      <div className="flex h-[60vh] items-center justify-center p-6 text-center">
        <div>
          <p className="text-lg font-semibold">No autorizado</p>
          <p className="text-sm text-muted-foreground">Esta sección solo está disponible para cuentas de administrador.</p>
        </div>
      </div>
    );
  }
  return <BackupsAdminContenido />;
}

"use client";

import { useState } from "react";
import { Warning2, Danger, Lock, ArrowRight2 } from "@/lib/icons";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";

const PALABRA_CONFIRMACION = "RESTAURAR";

/**
 * Flujo de dos pasos para restaurar un backup — acción real y destructiva
 * (sustituye la base de datos completa), así que no basta un solo clic:
 *
 *  Paso 1 — explica exactamente qué archivo se va a restaurar y qué
 *  pasará, y exige escribir literalmente "RESTAURAR" para continuar.
 *  Paso 2 — pide la clave de confirmación; solo el backend la valida
 *  (nunca se compara en el navegador).
 *
 * El backend, antes de tocar la base de datos real, siempre hace primero
 * un backup de seguridad del estado actual y restaura en una base de
 * datos aislada para verificar que todo salió bien (ver
 * restore_kelatos_gdrive.sh en el VPS) — este diálogo solo encola la
 * solicitud, igual que "Backup ahora".
 */
export function RestaurarBackupDialog({
  archivo,
  fecha,
  open,
  onOpenChange,
  onSolicitado,
}: {
  archivo: string | null;
  fecha: string | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSolicitado: () => void;
}) {
  const [paso, setPaso] = useState<1 | 2>(1);
  const [confirmacion, setConfirmacion] = useState("");
  const [clave, setClave] = useState("");
  const [enviando, setEnviando] = useState(false);

  function cerrar(o: boolean) {
    if (enviando) return;
    if (!o) {
      setPaso(1);
      setConfirmacion("");
      setClave("");
    }
    onOpenChange(o);
  }

  async function confirmar() {
    if (!archivo) return;
    if (!clave.trim()) return toast.error("Introduce la clave de confirmación");
    setEnviando(true);
    try {
      const res = await fetch("/api/admin/restore", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ nombreArchivo: archivo, clave }),
      });
      const data = await res.json();

    if (!data.ok) throw new Error(data.error || "Error desconocido");
    toast.success("Restauración solicitada — puede tardar unos minutos en completarse");
    cerrar(false);
    onSolicitado();
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error desconocido");
  } finally {
    setEnviando(false);
  }
}

return (
  <Dialog open={open} onOpenChange={cerrar}>
    <DialogContent className="max-w-md sm:max-w-md" showCloseButton={!enviando}>
      <DialogHeader>
        <DialogTitle className="flex items-center gap-2 text-destructive">
          <Danger className="size-5" /> Restaurar backup
        </DialogTitle>
      </DialogHeader>

      {paso === 1 ? (
        <div className="space-y-4">
          <div className="rounded-md border border-destructive/30 bg-destructive/10 p-3 text-sm">
            <p className="mb-2 flex items-center gap-1.5 font-semibold text-destructive">
              <Warning2 className="size-4" /> Esto sobrescribirá TODOS los datos actuales
            </p>
            <ul className="ml-5 list-disc space-y-1 text-muted-foreground">
              <li>
                Se restaurará <strong className="text-foreground">{archivo}</strong>
                {fecha && <> (del {fecha})</>}.
              </li>
              <li>Todo lo creado o cambiado después de esa fecha se perderá en la base de datos real.</li>
              <li>Antes de tocar nada, el sistema hace automáticamente un backup de seguridad del estado actual.</li>
              <li>La restauración se verifica en una copia aislada antes de aplicarse — si algo falla, la base de datos real no se toca.</li>
              <li>El proceso tarda unos minutos; los usuarios pueden notar una breve interrupción durante el cambio final.</li>
            </ul>
          </div>
          <div className="space-y-1.5">
            <Label htmlFor="confirmacionTexto">
              Escribe <strong>{PALABRA_CONFIRMACION}</strong> para continuar
            </Label>
            <Input
              id="confirmacionTexto"
              value={confirmacion}

