  const vals: string[] = [];
  for (const c of base) {
    const v = valorColumna(c, col);
    if (!vistos.has(v)) {
      vistos.add(v);
      vals.push(v);
    }
  }
  vals.sort((a, b) => a.localeCompare(b, "es", { numeric: true }));
