];
const operacionDe = (concepto: string) => OPERACIONES.find(([re]) => re.test(concepto.trim())) || null;

const DIAS = ["domingo", "lunes", "martes", "miércoles", "jueves", "viernes", "sábado"];
const MESES = ["enero", "febrero", "marzo", "abril", "mayo", "junio", "julio", "agosto", "septiembre", "octubre", "noviembre", "diciembre"];
function fechaLarga(iso: string): string {

  const d = new Date(`${iso.slice(0, 10)}T12:00:00Z`);
  return `${DIAS[d.getUTCDay()]} ${d.getUTCDate()} de ${MESES[d.getUTCMonth()]} de ${d.getUTCFullYear()}`;
}
const r2 = (n: number) => Math.round(n * 100) / 100;
const celdaCsv = (v: unknown) => `"${String(v ?? "").replace(/"/g, '""')}"`;

export default function DiarioPage() {
  const [{ desde, hasta }, setRango] = useState(rangoAnioActual);
  const [borradores, setBorradores] = useState(false);
  const [pagina, setPagina] = useState(1);
  const [porPagina, setPorPagina] = useState(50);
  const [asientos, setAsientos] = useState<AsientoDiario[]>([]);
  const [totales, setTotales] = useState({ asientos: 0, debe: 0, haber: 0 });
  const [cargando, setCargando] = useState(true);
  const [exportando, setExportando] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [detalleId, setDetalleId] = useState<number | null>(null);

  useEffect(() => setPagina(1), [desde, hasta, borradores, porPagina]);

  const cargar = useCallback(async () => {
    setCargando(true);
    setError(null);
    try {
      const d = await apiC<{ asientos: AsientoDiario[]; totales: { asientos: number; debe: number; haber: number } }>("libro-diario", {
        query: { desde, hasta, borradores, limit: porPagina, offset: (pagina - 1) * porPagina },
      });
      setAsientos(d.asientos);
      setTotales(d.totales);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Error");
    } finally {
      setCargando(false);
    }
  }, [desde, hasta, borradores, pagina, porPagina]);
  useEffect(() => {
    cargar();
  }, [cargar]);

  const totalPaginas = Math.max(1, Math.ceil(totales.asientos / porPagina));

  // Exporta TODO el periodo (no solo la página) con una línea por apunte, listo para Excel (separador «;», coma decimal).
  async function exportarCsv() {
    setExportando(true);
    try {
      const todos: AsientoDiario[] = [];
      for (let offset = 0; ; offset += 300) {
        const d = await apiC<{ asientos: AsientoDiario[] }>("libro-diario", { query: { desde, hasta, borradores, limit: 300, offset } });
        todos.push(...d.asientos);
        if (d.asientos.length < 300) break;

    }
    if (!todos.length) return toast.error("No hay asientos que exportar en este periodo");
    const cab = ["Asiento", "Fecha", "Estado", "Concepto del asiento", "Cuenta", "Nombre de la cuenta", "Debe", "Haber"];
    const filas = todos.flatMap((a) => a.lineas.map((l) => [a.numero || `#${a.id}`, a.fecha, a.estado, a.concepto, l.subcuenta_codigo || l.cuenta_codigo, l.subcuenta_nombre || l.cuenta_nombre, l.debe ? String(l.debe).replace(".", ",") : "", l.haber ? String(l.haber).replace(".", ",") : ""]));
    descargarCsv("﻿" + [cab, ...filas].map((f) => f.map(celdaCsv).join(";")).join("\r\n"), `libro-diario-${desde}_a_${hasta}.csv`);
    toast.success(`${todos.length} asiento(s) exportados (${filas.length} apuntes)`);
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error al exportar");
  } finally {
    setExportando(false);
  }
}

return (
  <div className="space-y-3 p-6">
    <Cabecera
      icono={<Book1 className="size-4.5" />}
      titulo="Libro Diario"
      descripcion="Todos los asientos en orden cronológico, con sus apuntes al Debe y al Haber"
      acciones={
        <>
          <Button variant="outline" size="sm" className="h-8 gap-1.5" disabled={exportando || totales.asientos === 0} onClick={exportarCsv} title="Descarga todo el periodo, un apunte por línea">
            <DocumentDownload className="size-4" /> {exportando ? "Exportando…" : "Exportar CSV"}
          </Button>
          <Button variant="outline" size="icon" className="size-8" onClick={() => cargar()} title="Actualizar">
            <Refresh2 className={`size-4 ${cargando ? "animate-spin" : ""}`} />
          </Button>
        </>
      }
    />
    <InfoVista>Lista los asientos ya contabilizados por orden cronológico, exactamente como se registraron. Ejemplo: en la fecha de una venta aparece el asiento con su cargo a Caja y su abono a Ventas e IVA, uno detrás de otro con el resto del día. Las cuentas que están en el Haber van sangradas, como en un libro diario clásico.</InfoVista>
    <div className="flex flex-wrap items-center gap-3">

"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { apiC, eur, fechaCorta, hoyISO, num } from "@/lib/contabilidad";
import { Kpi } from "../_ui";

interface RetiradaTransito {
  id: number | string;
  fecha_retirada: string;
  importe: number;
  motivo: string | null;
  banco_id: number | null;
  banco: string | null;
  ingresado: number;
  pendiente: number;
  modo: "transito" | "ya_contabilizado" | "sin_asiento";
  estado: "pendiente" | "parcial" | "ingresada";
  asiento_estado: string | null;
  sugeridos?: number[];
}
interface MovimientoBanco {
  id: number | string;
  banco_id: number;
  banco: string;
  fecha: string;
  importe: number;
  concepto: string;
  clase_sugerida: string | null;
  libre: number;
}
interface IngresoConfirmado {
  id: number | string;
  efectivo_id: number | string;
  importe: number;
  fecha_ingreso: string;
  banco: string;
  movimiento_id: number | string | null;
  solo_conciliacion: boolean;
  asiento_id: number | string | null;
  asiento_estado: string | null;
}
interface DatosTransito {
  depositos: IngresoConfirmado[];
  retiradas: RetiradaTransito[];
  movimientos: MovimientoBanco[];
  bancos: { id: number; nombre: string }[];
  resumen: { pendiente_total: number; pendiente_conciliar_directos: number; saldo_5709_contabilizado: number; saldo_5709_en_borrador: number };
}

const redondear = (n: number) => Math.round(n * 100) / 100;

/**
 * Efectivo en tránsito (cuenta 5709): lo retirado de la caja para ingresarlo en el banco, hasta que se confirma el ingreso. Cada confirmación puede ser
 * parcial o agrupada (varias retiradas en un mismo ingreso) y se vincula con el movimiento del extracto cuando lo hay.
 */
export function EfectivoTransito({ soloLectura, onCambio }: { soloLectura: boolean; onCambio: () => void }) {

const [datos, setDatos] = useState<DatosTransito | null>(null);
const [error, setError] = useState<string | null>(null);
const [dialogo, setDialogo] = useState<number | string | null>(null);
const [deshaciendo, setDeshaciendo] = useState<string | null>(null);

const cargar = useCallback(async () => {
  try {
    setDatos(await apiC<DatosTransito>("efectivo/transito"));
    setError(null);
  } catch (e) {
    setError(e instanceof Error ? e.message : "Error");
  }
}, []);
useEffect(() => {
  cargar();
}, [cargar]);

if (error) return <p className="text-sm text-red-600">{error}</p>;
if (!datos) return null;
const pendientes = datos.retiradas.filter((r) => r.pendiente > 0);
if (!pendientes.length && !datos.depositos.length && datos.resumen.saldo_5709_contabilizado === 0 && datos.resumen.saldo_5709_en_borrador === 0) return null;

async function deshacer(d: IngresoConfirmado) {
  if (!window.confirm(`¿Deshacer el ingreso de ${num(d.importe)} € de EF-${String(d.efectivo_id)}? La retirada volverá a salir pendiente y se elimina su asiento en borrador.`)) return;
  setDeshaciendo(String(d.id));
  try {
    await apiC("efectivo/transito/deshacer", { metodo: "POST", cuerpo: { deposito_id: Number(d.id) } });
    toast.success("Ingreso deshecho: la retirada vuelve a estar pendiente");
    await cargar();
    onCambio();
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error");
  } finally {
    setDeshaciendo(null);
  }
}

return (
  <div className="space-y-2">
    <div className="grid grid-cols-2 gap-2 sm:max-w-3xl sm:grid-cols-4">
      <Kpi titulo="Efectivo en tránsito pendiente de ingresar" valor={eur(datos.resumen.pendiente_total)} color={datos.resumen.pendiente_total ? "text-amber-600 dark:text-amber-400" : ""} />
      <Kpi titulo="Saldo 5709 contabilizado" valor={eur(datos.resumen.saldo_5709_contabilizado)} color="" />
      <Kpi titulo="Saldo 5709 en borrador" valor={eur(datos.resumen.saldo_5709_en_borrador)} color="" />
      <Kpi titulo="Ya contabilizados, por conciliar" valor={eur(datos.resumen.pendiente_conciliar_directos)} color="" />
    </div>

                      {d.solo_conciliacion ? "Solo conciliación (ya contabilizado)" : d.asiento_id ? `#${String(d.asiento_id)} · ${(d.asiento_estado || "").toLowerCase()}` : "sin asiento"}
                    </TableCell>
                    <TableCell>
                      {!soloLectura &&
                        (borrador ? (
                          <Button size="sm" variant="ghost" className="h-7 text-destructive" disabled={deshaciendo === String(d.id)} onClick={() => deshacer(d)}>
                            Deshacer
                          </Button>
                        ) : (
                          <span className="text-xs text-muted-foreground">Corregir con contra-asiento</span>
                        ))}
                    </TableCell>
                  </TableRow>
                );
              })}
            </TableBody>
          </Table>
        </div>
      )}

      {dialogo !== null && (
        <ConfirmarIngresoDialog
          datos={datos}
          inicial={dialogo}
          onClose={() => setDialogo(null)}
          onHecho={async () => {
            setDialogo(null);
            await cargar();
            onCambio();
          }}
        />
      )}
    </div>
  );
}

function ConfirmarIngresoDialog({ datos, inicial, onClose, onHecho }: { datos: DatosTransito; inicial: number | string; onClose: () => void; onHecho: () => Promise<void> }) {
  const pendientes = useMemo(() => datos.retiradas.filter((r) => r.pendiente > 0 && r.modo !== "sin_asiento"), [datos.retiradas]);
  const [elegidas, setElegidas] = useState<Record<string, string>>(() => {
    const r = pendientes.find((x) => String(x.id) === String(inicial));
    return r ? { [String(r.id)]: String(r.pendiente) } : {};
  });
  const [movimientoId, setMovimientoId] = useState("");
  const [bancoId, setBancoId] = useState("");
  const [fecha, setFecha] = useState(hoyISO());
  const [nota, setNota] = useState("");
  const [enviando, setEnviando] = useState(false);

  const mov = datos.movimientos.find((m) => String(m.id) === movimientoId) || null;
  const total = redondear(Object.values(elegidas).reduce((s, v) => s + (Number(v) || 0), 0));

const diferencia = mov ? redondear(mov.libre - total) : null;

function elegirMovimiento(id: string) {
  setMovimientoId(id);
  const m = datos.movimientos.find((x) => String(x.id) === id);
  if (m) {
    setFecha(m.fecha);
    setBancoId(String(m.banco_id));
  }
}

function alternar(r: RetiradaTransito) {
  setElegidas((prev) => {
    const k = String(r.id);
    const sig = { ...prev };
    if (k in sig) delete sig[k];
    else sig[k] = String(r.pendiente);
    return sig;
  });
}

async function confirmar() {
  const partes = Object.entries(elegidas).map(([id, imp]) => ({ efectivo_id: Number(id), importe: Number(imp) }));
  if (!partes.length) return toast.error("Elige al menos una retirada");
  if (partes.some((p) => !(p.importe > 0))) return toast.error("Cada importe debe ser mayor que 0");
  if (!movimientoId && !bancoId) return toast.error("Elige el movimiento del extracto o, si no lo hay, el banco");
  if (!fecha) return toast.error("Indica la fecha real del ingreso");
  setEnviando(true);
  try {
    const r = await apiC<{ asientos: number[]; errores: string[]; movimiento_conciliado: boolean; diferencia_pendiente_en_movimiento: number | null }>("efectivo/transito/confirmar", {
      metodo: "POST",
      cuerpo: { fecha, banco_id: bancoId ? Number(bancoId) : undefined, movimiento_id: movimientoId ? Number(movimientoId) : undefined, partes, nota: nota.trim() || undefined },
    });
    if (r.errores?.length) toast.warning(`Ingreso confirmado, pero un asiento no se pudo generar: ${r.errores[0]}`);
    else toast.success(r.asientos.length ? `Ingreso confirmado: ${r.asientos.length} asiento(s) en borrador (572 / 5709)` : "Ingreso conciliado (ya estaba contabilizado)");
    if (r.diferencia_pendiente_en_movimiento && Number(r.diferencia_pendiente_en_movimiento) > 0) toast.info(`Quedan ${eur(Number(r.diferencia_pendiente_en_movimiento))} del movimiento sin repartir`);
    await onHecho();
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error");
  } finally {
    setEnviando(false);
  }
}

return (

            Total a confirmar: {num(total)} €
            {mov && diferencia !== null && (diferencia < 0 ? ` · supera en ${num(-diferencia)} € lo libre del movimiento (${num(mov.libre)} €)` : diferencia > 0 ? ` · quedarán ${num(diferencia)} € del movimiento sin repartir` : " · coincide con el movimiento")}
          </p>
        </div>

        <DialogFooter>
          <Button variant="outline" disabled={enviando} onClick={onClose}>
            Cancelar
          </Button>
          <Button disabled={enviando} onClick={confirmar}>
            {enviando ? "Confirmando…" : "Confirmar ingreso"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

