    ...(detalle.fianzaCobrada > 0 ? [{ descripcion: "Fianza", cantidad: 1, precio: detalle.fianzaCobrada }] : []),
    // Informativas a 0 € — el envío/recogida ya se cobró (o fue gratis) una
