/** Cuota deducible / no deducible que corresponde al estado del IVA (la parcial conserva la parte deducible que se indique). */
function repartoIva(estado: EstadoIvaFactura, cuota: number, deducible: number): { cuotaIvaDeducible: number; ivaNoDeducible: number } {
  const r = (n: number) => Math.round(n * 100) / 100;
  if (estado === "deducible") return { cuotaIvaDeducible: cuota, ivaNoDeducible: 0 };
  if (estado === "no_deducible") return { cuotaIvaDeducible: 0, ivaNoDeducible: cuota };
  if (estado === "parcial") return { cuotaIvaDeducible: deducible, ivaNoDeducible: Math.max(0, r(cuota - deducible)) };
  return { cuotaIvaDeducible: 0, ivaNoDeducible: 0 };
}

/** Lo que falta para dar por buena la factura según su tipo de operación y el estado del IVA (el servidor aplica las mismas reglas:
    si falta algo, la factura se guarda igualmente pero queda «pendiente de revisión»). */
function faltantesFiscales(d: Formulario): string[] {
  const f: string[] = [];
  if (d.tipoOperacion === "intracomunitaria") {
    const nif = d.nifIvaProveedor.replace(/[\s.-]/g, "").toUpperCase();
    if (!nif) f.push("el NIF-IVA comunitario del proveedor");

    else if (!/^[A-Z]{2}[A-Z0-9]{2,12}$/.test(nif) || nif.startsWith("ES")) f.push("un NIF-IVA comunitario válido (código de otro país de la UE, p. ej. DE123456789)");
    if (d.cuotaIvaSoportado > 0) f.push(`revisar: la factura cobra ${d.cuotaIvaSoportado.toFixed(2)} € de IVA y una compra intracomunitaria no debería llevarlo (se autorrepercute); pide una factura sin IVA al proveedor`);
  }
  if (d.tipoOperacion === "importacion") {
    if ((d.estadoIva === "deducible" || d.estadoIva === "parcial") && !d.documentoAduanero.trim()) f.push("el documento aduanero (DUA) o justificante de importación que acredite el IVA");
  }
  if (d.moneda.trim() && d.moneda.trim().toUpperCase() !== "EUR" && !(d.tipoCambio && d.tipoCambio > 0)) f.push("el tipo de cambio para convertir la factura a euros");
  if (d.estadoIva === "pendiente_justificar") f.push("justificar el IVA (estado «pendiente de justificar»)");
  return f;
}

function leerBase64(archivo: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const r = new FileReader();
    r.onerror = () => reject(new Error(`No se pudo leer "${archivo.name}"`));
    r.onload = () => resolve(String(r.result).split(",")[1] || "");
    r.readAsDataURL(archivo);
  });
}

/** Cada sección se ve como un panel propio (cabecera con icono + cuerpo con
    fondo de tarjeta) en vez de un simple título — con 20+ campos en un solo
    diálogo, la separación visual es lo que evita que se lea como una pared
    de inputs. La de Importes lleva además un acento verde: es el bloque que
    de verdad hay que revisar antes de registrar. */
function Seccion({
  titulo, icono: Icono, acento, className, children,
}: {
  titulo: string;
  icono: React.ElementType;
  acento?: boolean;
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <div className={cn("overflow-hidden rounded-lg border", acento && "border-emerald-200 dark:border-emerald-900", className)}>
      <div className={cn(
        "flex items-center gap-2 border-b px-4 py-2.5",
        acento ? "border-emerald-200 bg-emerald-50 dark:border-emerald-900 dark:bg-emerald-950/40" : "border-border bg-muted/40"
      )}>

    cuadra con el total en una factura a nombre de Affirma (deducible). «Parcialmente deducible» y «No deducible» dependen del uso del gasto
    y no se pueden saber leyendo el PDF: nunca se deducen. */
function deducirEstadoIva(e: FacturaOcrExtraido): { estado: EstadoIvaFactura; motivo: string } | null {
  // Solo frenan la deducción las dudas de la IA sobre lo que decide el IVA (importes, tipo, moneda, tipo de documento, receptor): una duda sobre
  // el nº de factura, la serie, el nombre del proveedor o la descripción no cambia si el IVA es deducible (esas se siguen avisando aparte).
  const DUDAS_QUE_FRENAN = ["baseImponible", "tipoIva", "cuotaIvaSoportado", "importeTotal", "moneda", "tipoDocumento", "receptor"];
  if (e.advertencias.some((x) => DUDAS_QUE_FRENAN.includes(x)) || e.receptorCoincide !== true) return null;
  const { baseImponible: base, cuotaIvaSoportado: cuota, importeTotal: total, tipoIva } = e;
  if (base === null || total === null) return null;
  if ((cuota === 0 || (cuota === null && tipoIva === 0)) && Math.abs(base - total) <= 0.5) return { estado: "sin_cuota", motivo: "la factura no lleva IVA" };
  if (cuota !== null && cuota > 0 && Math.abs(base + cuota - total) <= 0.5) return { estado: "deducible", motivo: "lleva IVA, la base más el IVA cuadra con el total y está a nombre de Affirma" };
  return null;
}

/** Por qué NO se pudo marcar el IVA como deducible al leer el PDF (se enseña junto al estado para que se entienda que no «falta» ningún documento). */
function motivoSinDeducirIva(e: FacturaOcrExtraido): string {
  const NOMBRES: Record<string, string> = { baseImponible: "la base imponible", tipoIva: "el tipo de IVA", cuotaIvaSoportado: "la cuota de IVA", importeTotal: "el importe total", moneda: "la moneda", tipoDocumento: "el tipo de documento", receptor: "el destinatario" };
  const dudas = e.advertencias.filter((x) => NOMBRES[x]).map((x) => NOMBRES[x]);
  if (dudas.length) return `la IA no está segura de ${dudas.join(", ")}`;
  if (e.receptorCoincide !== true) return "no se reconoce a Affirma como destinatario de la factura";

  if (e.baseImponible === null || e.importeTotal === null) return "no se pudo leer la base imponible o el total";
  const cuota = e.cuotaIvaSoportado ?? 0;
  if (Math.abs(e.baseImponible + cuota - e.importeTotal) > 0.5) return `la base (${e.baseImponible.toFixed(2)} €) más el IVA (${cuota.toFixed(2)} €) no cuadra con el total (${e.importeTotal.toFixed(2)} €)`;
  return "la factura tiene un caso que no se puede decidir solo leyendo el PDF";
}

