  if (!datos.proveedorId && !textoParaCategoria && !hayStockParaCategoria && !categoriaIA) return;
  const ctrl = new AbortController();
  const t = setTimeout(() => {
    fetch("/api/facturas-recibidas/sugerir-categoria", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ proveedorId: datos.proveedorId || undefined, texto: textoParaCategoria, hayStock: hayStockParaCategoria, facturaId: facturaExistente?.id, categoriaIA: categoriaIA || undefined }),
      signal: ctrl.signal,
    })
      .then((r) => r.json())
      .then((d) => {
        if (!d?.ok || !d.categoria || !(d.categoria in ETIQUETA_CATEGORIA) || categoriaManualRef.current) return;
        setDatos((p) => (p.categoria ? p : { ...p, categoria: d.categoria as CategoriaFactura }));
        setCategoriaNota(d.motivo || null);
        setCategoriaDiscrepa(d.coinciden === false);
      })
      .catch(() => {});
  }, 600);
  return () => { clearTimeout(t); ctrl.abort(); };
}, [open, facturaExistente, datos.proveedorId, textoParaCategoria, hayStockParaCategoria, categoriaIA]);

// Cancela también si el componente se desmonta de verdad (no solo se cierra el diálogo).
useEffect(() => () => { ocrAbortRef.current?.abort(); }, []);

/** Líneas listas para guardar: con el importe en euros (convertido con el tipo de cambio si la factura no está en euros). */
function lineasParaGuardar() {
  const conCambio = datos.moneda.trim() && datos.moneda.trim().toUpperCase() !== "EUR";
  return lineas
    .filter((l) => l.descripcion.trim())
    .map((l) => ({

      descripcion: l.descripcion.trim(), cantidad: l.cantidad, precioUnitario: l.precioUnitario || undefined, importe: l.importe || undefined,
      importeEur: conCambio ? (datos.tipoCambio && datos.tipoCambio > 0 ? Math.round((l.importe / datos.tipoCambio) * 100) / 100 : undefined) : l.importe || undefined,
      codigoProveedor: l.codigoProveedor.trim() || undefined, idPedidoProveedor: l.idPedidoProveedor.trim() || undefined, referenciaPieza: l.referenciaPieza.trim() || undefined,
    }));
}

function cargarProveedores() {
  fetch("/api/proveedores")
    .then((r) => r.json())
    .then((d) => { if (d.ok) setProveedores(d.proveedores); })
    .catch(() => {});
}
useEffect(() => {
  if (open) cargarProveedores();
}, [open]);

function set<K extends keyof Formulario>(campo: K, valor: Formulario[K]) {
  // En una factura nueva, el vencimiento es la fecha de la factura mientras nadie lo cambie a mano.
  const sigueVencimiento = campo === "fechaExpedicion" && !esEdicion && !vencimientoManual;
  setDatos((prev) => ({ ...prev, [campo]: valor, ...(sigueVencimiento ? { fechaVencimiento: valor as string } : {}) }));
}

/** Con moneda distinta de EUR: pasa a euros la base y el importe total originales con el tipo de cambio (unidades de moneda por 1 €). */
function recalcularEuros(d: Formulario): Formulario {
  if (!d.moneda.trim() || d.moneda.trim().toUpperCase() === "EUR" || !(d.tipoCambio && d.tipoCambio > 0)) return d;
  const r2 = (n: number) => Math.round(n * 100) / 100;
  const base = r2(d.baseMonedaOriginal / d.tipoCambio);
  const totalOrig = d.totalMonedaOriginal || d.baseMonedaOriginal;
  // En compras que se autorrepercuten el IVA no figura en la factura: el total son los mismos euros que la base.
  const autorrepercutida = d.tipoOperacion === "intracomunitaria" || d.tipoOperacion === "servicio_extracomunitario";
  const total = autorrepercutida ? base : r2(totalOrig / d.tipoCambio);
  const n = { ...d, baseImponible: base, importeTotal: total, cuotaIvaSoportado: autorrepercutida ? 0 : Math.max(0, r2(total - base)) };

  return { ...n, ...repartoIva(n.estadoIva, n.cuotaIvaSoportado, n.cuotaIvaDeducible) };
}

function setOriginal(campo: "baseMonedaOriginal" | "totalMonedaOriginal" | "tipoCambio", valor: number | null) {
  setDatos((prev) => recalcularEuros({ ...prev, [campo]: valor } as Formulario));
}

/** Consulta el tipo de cambio del BCE (el que usa el conversor del Banco de España) para la moneda y la fecha de la factura y convierte a euros. */
async function consultarTipoCambio(moneda: string, fecha: string) {
  const m = moneda.trim().toUpperCase();
  if (!m || m === "EUR") return;
  if (!fecha) return toast.error("Indica la fecha de expedición para consultar el tipo de cambio");
  setConsultandoCambio(true);
  try {
    const res = await fetch(`/api/facturas-recibidas/tipo-cambio?moneda=${encodeURIComponent(m)}&fecha=${encodeURIComponent(fecha)}`);
    const d = await res.json();
    if (!d.ok) throw new Error(d.error || "No se pudo consultar el tipo de cambio");
    setInfoCambio({ fechaTipo: d.cambio.fechaTipo, fuente: d.cambio.fuente });
    setDatos((prev) => recalcularEuros({ ...prev, tipoCambio: d.cambio.tipo }));
    toast.success(`Tipo de cambio ${m}: ${d.cambio.tipo} por euro (BCE, ${d.cambio.fechaTipo.split("-").reverse().join("/")})`);
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "No se pudo consultar el tipo de cambio — introdúcelo a mano");
  } finally {
    setConsultandoCambio(false);
  }
}

/** Cambia datos del IVA y recalcula la cuota deducible / no deducible según el estado del IVA. */
function aplicarIva(cambios: Partial<Formulario>) {
  setDatos((prev) => {
    const n = { ...prev, ...cambios };
    return { ...n, ...repartoIva(n.estadoIva, n.cuotaIvaSoportado, n.cuotaIvaDeducible) };
  });
}

/** Al cambiar el tipo de operación se propone el estado de IVA habitual (se puede cambiar después). */
function cambiarTipoOperacion(tipo: TipoOperacionFactura) {
  if (tipo === "intracomunitaria" || tipo === "servicio_extracomunitario") {

    aplicarIva({ tipoOperacion: tipo, estadoIva: "sin_cuota", tipoIva: 0, cuotaIvaSoportado: 0, importeTotal: datos.baseImponible });
    setDatos((prev) => recalcularEuros(prev));
  }
  else if (tipo === "importacion") aplicarIva({ tipoOperacion: tipo, estadoIva: "pendiente_justificar" });
  else aplicarIva({ tipoOperacion: tipo });
}

/** Cambia el CIF de la ficha del proveedor por el que trae la factura (pide confirmación; es un dato maestro). */
async function usarCifDeLaFactura(cif: string) {
  const prov = proveedores.find((p) => p.proveedorId === datos.proveedorId);
  if (!prov) return;
  if (!window.confirm(`Se cambiará el CIF de la ficha de «${prov.nombre}» de ${prov.dniCif || "(vacío)"} a ${cif}. ¿Continuar?`)) return;
  try {
    const res = await fetch(`/api/proveedores/${encodeURIComponent(prov.proveedorId)}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ dniCif: cif }) });
    const d = await res.json();
    if (!d.ok) throw new Error(d.error || "Error desconocido");
    setProveedores((ps) => ps.map((p) => (p.proveedorId === prov.proveedorId ? { ...p, dniCif: cif } : p)));
    toast.success(`CIF de «${prov.nombre}» actualizado a ${cif}`);
  } catch (e) {
    toast.error(`No se pudo actualizar la ficha: ${e instanceof Error ? e.message : "error desconocido"}`);
  }
}

/** Pone en la ficha del proveedor la razón social que trae la factura (el registro contable usa el nombre registrado para el CIF, no el comercial). */
async function usarRazonSocialDeLaFactura(nombre: string) {
  const prov = proveedores.find((p) => p.proveedorId === datos.proveedorId);
  if (!prov) return;
  if (!window.confirm(`Se cambiará el nombre de la ficha de «${prov.nombre}» a «${nombre}» (razón social de la factura). ¿Continuar?`)) return;
  try {
    const res = await fetch(`/api/proveedores/${encodeURIComponent(prov.proveedorId)}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ nombre }) });
    const d = await res.json();
    if (!d.ok) throw new Error(d.error || "Error desconocido");

    setProveedores((ps) => ps.map((p) => (p.proveedorId === prov.proveedorId ? { ...p, nombre } : p)));
    toast.success(`Ficha actualizada: ${nombre}`);
  } catch (e) {
    toast.error(`No se pudo actualizar la ficha: ${e instanceof Error ? e.message : "error desconocido"}`);
  }
}

function cambiarEstadoIva(estado: EstadoIvaFactura) {
  setIvaDeducidoDelPdf(null);
  setIvaSinDeducirMotivo(null);
  if (estado === "sin_cuota") {
    // «Sin cuota» pone IVA 0 y total = base; se guardan los importes leídos para devolverlos si la persona se arrepiente.
    if (datos.estadoIva !== "sin_cuota" && datos.cuotaIvaSoportado > 0) ivaAntesDeSinCuota.current = { tipoIva: datos.tipoIva, cuotaIvaSoportado: datos.cuotaIvaSoportado, importeTotal: datos.importeTotal };
    aplicarIva({ estadoIva: estado, tipoIva: 0, cuotaIvaSoportado: 0, importeTotal: datos.baseImponible });
  } else if (datos.estadoIva === "sin_cuota" && ivaAntesDeSinCuota.current) {
    aplicarIva({ estadoIva: estado, ...ivaAntesDeSinCuota.current });
    ivaAntesDeSinCuota.current = null;
  } else aplicarIva({ estadoIva: estado });
}

async function guardar() {
  if (!datos.proveedorId) return toast.error("Selecciona el proveedor");
  if (!datos.numeroFacturaProveedor.trim()) return toast.error("El número de factura del proveedor es obligatorio");
  if (!datos.tipoDocumento) return toast.error("El tipo de documento es obligatorio");
  if (!datos.fechaExpedicion) return toast.error("La fecha de expedición es obligatoria");
  if (!datos.baseImponible) return toast.error("La base imponible es obligatoria");
  if (!datos.importeTotal) return toast.error("El importe total es obligatorio");
  if (!esEdicion) {
    // Se revisan todas las piezas nuevas de una vez para avisar de todos los problemas juntos.
    const problemas: string[] = [];
    for (const a of articulosStock.filter((x) => x.aplicar && x.cantidad > 0 && !x.referencia.trim())) {
      const motivo = motivoNombrePiezaInvalido(a.nombre, { numeroFactura: datos.numeroFacturaProveedor, idPedido: a.idPedidoProveedor });

    if (motivo) problemas.push(`«${a.nombre}»: ${motivo} (escribe el nombre real del producto o desmárcala)`);
    else if (!a.categoria) problemas.push(`«${a.nombre}»: falta la categoría`);
  }
  if (problemas.length) return toast.error(`Revisa las piezas nuevas de Stock antes de registrar:\n- ${problemas.join("\n- ")}`, { style: { whiteSpace: "pre-line" } });
}
if (["deducible", "parcial", "no_deducible"].includes(datos.estadoIva) && !(datos.cuotaIvaSoportado > 0)) {
  return toast.error("Indica la cuota de IVA soportado (si la factura no tiene cuota de IVA acreditada, elige «Sin cuota de IVA acreditada»)");
}
if (datos.estadoIva === "parcial" && !(datos.cuotaIvaDeducible > 0 && datos.cuotaIvaDeducible < datos.cuotaIvaSoportado)) {
  return toast.error("En un IVA parcialmente deducible, la parte deducible debe ser mayor que 0 y menor que la cuota soportada");
}
if (!esEdicion && resumenOcr?.extraido.receptorCoincide === false) {
  return toast.error("No se puede registrar: la factura no muestra los datos de Affirma (ni el CIF ni el nombre). Sube la factura a nombre de la empresa.");
}
if (resumenOcr && resumenOcr.extraido.advertencias.length > 0 && !advertenciasVistas) {
  return toast.error("La IA marcó datos que no está segura de haber leído bien — revísalos y marca la casilla del aviso antes de registrar");
}

setEnviando(true);
try {
  const payload = {
    proveedorId: datos.proveedorId, numeroFacturaProveedor: datos.numeroFacturaProveedor.trim(), serieProveedor: datos.serieProveedor.trim(),
    fechaExpedicion: datos.fechaExpedicion, fechaOperacion: datos.fechaOperacion || undefined, fechaRecepcion: datos.fechaRecepcion || undefined, fechaContabilizacion: datos.fechaContabilizacion || null,
    pagoMedio: datos.pagoMedio || null,
    pagoBancoId: datos.pagoMedio === "transferencia" && datos.pagoBancoId ? Number(datos.pagoBancoId) : null,
    pagoMedioPagoId: ["tarjeta_debito", "tarjeta_credito", "paypal"].includes(datos.pagoMedio) && datos.pagoMedioPagoId ? Number(datos.pagoMedioPagoId) : null,

  lecturaOcr: resumenOcr
    ? { extraido: resumenOcr.extraido, proveedorEncontrado: resumenOcr.proveedorEncontrado, proveedorCreado: resumenOcr.proveedorCreado, ivaMotivo: ivaDeducidoDelPdf || ivaSinDeducirMotivo || null, ivaDeducidoSolo: !!ivaDeducidoDelPdf, leidoEn: new Date().toISOString() }
    : undefined,
  // Solo al CREAR — reaplicar en una edición duplicaría el stock ya
  // sumado la primera vez.
  // Cada artículo de la factura se registra por separado (en una edición solo si se cargaron las existentes).
  lineas: !esEdicion || lineasCargadas ? lineasParaGuardar() : undefined,
  articulosStock: !esEdicion
    ? articulosStock
        .filter((a) => a.aplicar && a.cantidad > 0)
        .map((a) =>
          a.referencia.trim()
            ? { referencia: a.referencia.trim(), cantidad: a.cantidad }
            : {
                nombre: a.nombre,
                cantidad: a.cantidad,
                nuevaPieza: {
                  nombre: a.nombre, categoria: a.categoria, costeInterno: a.costeInterno, precioCliente: a.precioCliente, manoObra: 0,
                  nombreInternoProveedor: a.nombre, codigoProveedor: a.codigoProveedor.trim(), idPedidoProveedor: a.idPedidoProveedor.trim(),
                },
              }
        )
    : undefined,
};
const url = esEdicion ? `/api/facturas-recibidas/${facturaExistente!.id}` : "/api/facturas-recibidas";
const enviar = async (confirmarDuplicado: boolean) => {
  const r = await fetch(url, {
    method: esEdicion ? "PATCH" : "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(confirmarDuplicado ? { ...payload, confirmarDuplicado: true } : payload),
  });
  return r.json();
};
let data = await enviar(false);
// Mismo proveedor y número que otra factura ya registrada: se pide confirmación expresa antes de duplicarla (y de sumar su stock otra vez).
if (!data.ok && typeof data.error === "string" && data.error.startsWith("DUPLICADO:")) {

      if (!window.confirm(`${data.error.replace(/^DUPLICADO:\s*/, "")}\n\n¿Registrarla igualmente?`)) {
        setEnviando(false);
        return;
      }
      data = await enviar(true);
    }
    if (!data.ok) throw new Error(data.error || "Error desconocido");
    if (data.factura.posibleDuplicado && !data.factura.duplicadoConfirmado) toast.warning(`Aviso: ya existe otra factura del mismo proveedor con el número "${datos.numeroFacturaProveedor}"`);

    if (!esEdicion && archivoPendiente) {
      try {
        await subirArchivoA(data.factura.id, archivoPendiente);
        toast.success(`Factura registrada (${data.factura.numeroRecepcion}) con el archivo adjunto`);
      } catch (e) {
        toast.warning(`Factura registrada (${data.factura.numeroRecepcion}), pero el archivo no se pudo subir: ${e instanceof Error ? e.message : "error desconocido"}. Ábrela de nuevo para reintentarlo.`);
      }
    } else {
      toast.success(esEdicion ? "Factura actualizada" : `Factura registrada (${data.factura.numeroRecepcion})`);
    }
    onOpenChange(false);
    onGuardado();
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error desconocido");
  } finally {
    setEnviando(false);
  }
}

async function subirArchivoA(id: number, archivo: File): Promise<string> {
  const base64 = await leerBase64(archivo);
  const res = await fetch(`/api/facturas-recibidas/${id}/archivo`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ base64, mimeType: archivo.type || "application/octet-stream", nombre: archivo.name }),
  });
  const data = await res.json();
  if (!data.ok) throw new Error(data.error || "Error desconocido");
  return data.factura.driveFileId as string;
}

async function manejarArchivoSeleccionado(archivo: File | undefined) {
  if (!archivo) return;
  if (!esPdf(archivo)) {
    toast.error(MENSAJE_SOLO_PDF);
    if (inputArchivo.current) inputArchivo.current.value = "";
    return;
  }
  if (archivo.size > 8 * 1024 * 1024) {
    toast.error("El archivo no puede superar 8 MB");

    if (inputArchivo.current) inputArchivo.current.value = "";
    return;
  }
  // Sin id todavía (factura nueva) — se sube automáticamente al registrar.
  if (!esEdicion) {
    setArchivoPendiente(archivo);
    return;
  }
  setSubiendoArchivo(true);
  try {
    const nuevoId = await subirArchivoA(facturaExistente!.id, archivo);
    setDriveFileId(nuevoId);
    toast.success("Archivo adjuntado");
    onGuardado();
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error desconocido");
  } finally {
    setSubiendoArchivo(false);
    if (inputArchivo.current) inputArchivo.current.value = "";
  }
}

async function leerConIA(archivo: File | undefined) {
  if (!archivo) return;
  if (!esPdf(archivo)) {
    toast.error(MENSAJE_SOLO_PDF);
    if (inputOcr.current) inputOcr.current.value = "";
    return;
  }
  if (archivo.size > 8 * 1024 * 1024) {
    toast.error("El archivo no puede superar 8 MB");
    if (inputOcr.current) inputOcr.current.value = "";
    return;
  }

  // El mismo archivo que se lee queda también adjunto — no tiene sentido
  // pedirle al usuario que lo seleccione dos veces (una para leer, otra
  // para adjuntar). En alta se deja "en espera" como con "Adjuntar
  // archivo"; en edición se sube a Drive ya mismo.
  if (!esEdicion) {
    setArchivoPendiente(archivo);
  } else {
    try {
      const nuevoId = await subirArchivoA(facturaExistente!.id, archivo);
      setDriveFileId(nuevoId);
    } catch (e) {
      toast.error(`No se pudo adjuntar el archivo: ${e instanceof Error ? e.message : "error desconocido"}`);
    }
  }

  setLeyendoOcr(true);
  const controller = new AbortController();
  ocrAbortRef.current = controller;
  try {
    const base64 = await leerBase64(archivo);
    const res = await fetch("/api/facturas-recibidas/ocr", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ base64, mimeType: archivo.type || "application/octet-stream" }),
      signal: controller.signal,
    });
    const envio = await res.json();

if (!envio.ok || !envio.jobId) throw new Error(envio.error || "No se pudo iniciar la lectura");
// La lectura corre en segundo plano (la IA puede tardar un minuto): se consulta cada 1,5 s, hasta 4 minutos.
let data: { extraido: FacturaOcrExtraido | null; proveedorIdSugerido?: string | null; proveedorCreado?: boolean; articulosEmparejados?: Parameters<typeof articulosEmparejadosAEditables>[0] } | null = null;
const inicioLectura = Date.now();
while (Date.now() - inicioLectura < 240_000) {
  await new Promise((r) => setTimeout(r, 1500));
  if (controller.signal.aborted) return;
  const rr = await fetch(`/api/facturas-recibidas/ocr/${encodeURIComponent(envio.jobId)}`, { signal: controller.signal });
  const d = await rr.json();
  if (!d.ok) throw new Error(d.error || "No se pudo consultar la lectura");
  if (d.estado === "error") throw new Error(d.error || "No se pudo leer la factura");
  if (d.estado === "listo") { data = d; break; }
}
if (!data) throw new Error("La lectura está tardando demasiado. Inténtalo de nuevo o rellena la factura a mano.");
const e = data.extraido;
if (!e) {
  toast.warning("No se pudo leer ningún dato de la factura — rellénala a mano");
  setResumenOcr(null);
  return;
}
setResumenOcr({ extraido: e, proveedorEncontrado: !!data.proveedorIdSugerido, proveedorCreado: !!data.proveedorCreado });
setAdvertenciasVistas(false);
// Solo se pisan campos que la IA de verdad leyó — un valor no
// encontrado (null) no debe borrar algo que el usuario ya escribió.
if (data.proveedorIdSugerido) set("proveedorId", data.proveedorIdSugerido);
// Un proveedor recién creado por la lectura aún no está en la lista cargada: se recarga para que el desplegable muestre su nombre, no su identificador interno.
if (data.proveedorCreado) cargarProveedores();
if (e.numeroFacturaProveedor) set("numeroFacturaProveedor", e.numeroFacturaProveedor);
// Bug real reportado, 2026-10-07: la IA sí lee la serie (se ve en el
// resumen, "Serie: ...") pero nunca se copiaba al campo real del

// formulario — el número de factura quedaba guardado sin su serie.
if (e.serieProveedor) set("serieProveedor", e.serieProveedor);
if (e.tipoDocumento) set("tipoDocumento", e.tipoDocumento);
if (e.tipoDocumento === "otro") {
  // La IA no reconoce una factura: se anota qué es el documento y se avisa, en vez de tratarlo como factura completa.
  if (e.documentoDetectado) set("descripcion", `Documento: ${e.documentoDetectado}`);
  toast.warning(`La IA cree que este documento no es una factura${e.documentoDetectado ? ` (${e.documentoDetectado})` : ""}. Revisa el tipo de documento antes de registrarlo.`, { duration: 9000 });
}
if (e.fechaExpedicion) set("fechaExpedicion", e.fechaExpedicion);
const otraMoneda = !!e.moneda && e.moneda.trim().toUpperCase() !== "EUR";
if (otraMoneda) {
  // Factura en otra moneda: los importes leídos son los ORIGINALES; los euros se calculan con el tipo de cambio del BCE.
  setDatos((prev) => ({ ...prev, moneda: e.moneda.trim().toUpperCase(), tipoCambio: null, baseMonedaOriginal: e.baseImponible ?? e.importeTotal ?? 0, totalMonedaOriginal: e.importeTotal ?? e.baseImponible ?? 0, baseImponible: 0, importeTotal: 0, cuotaIvaSoportado: 0 }));
} else {
  if (e.baseImponible !== null) set("baseImponible", e.baseImponible);
  if (e.tipoIva !== null) set("tipoIva", e.tipoIva);
  if (e.cuotaIvaSoportado !== null) aplicarIva({ cuotaIvaSoportado: e.cuotaIvaSoportado });
  if (e.importeTotal !== null) set("importeTotal", e.importeTotal);
  if (e.moneda) set("moneda", e.moneda);
}
if (e.descripcion) set("descripcion", e.descripcion);
// El estado del IVA se deduce del PDF solo en compra nacional y si la persona no había elegido otro todavía.
setIvaDeducidoDelPdf(null);
setIvaSinDeducirMotivo(null);
// Proveedor de otro país de la UE (por el prefijo de su NIF-IVA o por su dirección): compra intracomunitaria, sin IVA, con NIF-IVA comprobado en VIES.
setAvisoIntra(null);
const ue = datos.tipoOperacion === "nacional" ? detectarCompraIntracomunitaria(e.proveedorDniCif, e.proveedorPais) : null;

if (ue) {
  const cuotaLeida = e.cuotaIvaSoportado ?? 0;
  const conIva = cuotaLeida > 0;
  if (conIva) aplicarIva({ tipoOperacion: "intracomunitaria", nifIvaProveedor: ue.nifIva, estadoIva: "pendiente_justificar" });
  else aplicarIva({ tipoOperacion: "intracomunitaria", nifIvaProveedor: ue.nifIva, estadoIva: "sin_cuota", tipoIva: 0, cuotaIvaSoportado: 0 });
  setAvisoIntra({
    texto: conIva
      ? `Proveedor de ${ue.nombrePais} (${ue.nifIva || "sin NIF-IVA"}): marcada como compra intracomunitaria. Pero la factura cobra IVA (${cuotaLeida.toFixed(2)} €), y en una compra intracomunitaria con NIF-IVA válido no corresponde: pide al proveedor una factura sin IVA (o rectificada) antes de contabilizarla.`
      : `Proveedor de ${ue.nombrePais} (${ue.nifIva || "sin NIF-IVA"}): marcada como compra intracomunitaria; la factura no cobra IVA, como corresponde.`,
    conIva,
  });
}
// Proveedor de FUERA de la UE (p. ej. EE. UU.): servicio con IVA autorrepercutido. Si en realidad es mercancía con DUA, se cambia a «Importación».
const fuera = !ue && datos.tipoOperacion === "nacional" && e.tipoDocumento !== "aduanero" ? detectarProveedorFueraUE(e.proveedorPais, e.proveedorDniCif, e.moneda) : null;
if (fuera) {
  aplicarIva({ tipoOperacion: "servicio_extracomunitario", estadoIva: "sin_cuota", tipoIva: 0, cuotaIvaSoportado: 0 });
  setAvisoIntra({
    texto: `Proveedor de fuera de la UE${fuera.pais ? ` (${fuera.pais})` : ""}: marcada como servicio de un proveedor de fuera de la UE. La factura no lleva IVA español y se autorrepercute el 21 %. Si es una compra de mercancía con DUA, cámbiala a «Importación».`,
    conIva: false,
  });
}
if (otraMoneda) void consultarTipoCambio(e.moneda, e.fechaExpedicion || datos.fechaExpedicion);
const iva = datos.tipoOperacion === "nacional" && datos.estadoIva === "pendiente_justificar" && !ue && !fuera ? deducirEstadoIva(e) : null;
if (iva) {
  if (iva.estado === "sin_cuota") aplicarIva({ estadoIva: "sin_cuota", tipoIva: 0, cuotaIvaSoportado: 0 });

      else aplicarIva({ estadoIva: iva.estado });
      setIvaDeducidoDelPdf(`${ESTADOS_IVA.find((x) => x.id === iva.estado)?.nombre ?? iva.estado}: ${iva.motivo}`);
    } else if (datos.tipoOperacion === "nacional" && datos.estadoIva === "pendiente_justificar" && !ue && !fuera) {
      setIvaSinDeducirMotivo(motivoSinDeducirIva(e));
    }
    setOrigenAutomatico(true);
    setCategoriaIA(e.categoriaIA || null);
    setArticulosStock(articulosEmparejadosAEditables(data.articulosEmparejados || []));
    setLineas(articulosALineas(data.articulosEmparejados || []));

    if (e.advertencias.length > 0) {
      toast.warning(`La IA no está segura de ${e.advertencias.length} dato(s) — revísalos en el resumen antes de registrar`);
    } else if (data.proveedorCreado) {
      toast.success(`Datos rellenados — proveedor "${e.proveedorNombre}" registrado automáticamente (no estaba dado de alta)`);
    } else if (e.proveedorNombre && !data.proveedorIdSugerido) {
      toast.warning(`Datos rellenados — el proveedor leído ("${e.proveedorNombre}") no coincide con ninguno dado de alta. Búscalo o créalo.`);
    } else {
      toast.success("Datos rellenados con IA — revísalos antes de registrar");
    }
  } catch (e) {
    // Cancelada a propósito al cerrar el diálogo — nada que avisar, y como
    // el fetch rechaza antes de llegar a los set(...) de arriba, no llega a
    // tocar el formulario.
    if (e instanceof DOMException && e.name === "AbortError") return;
    toast.error(e instanceof Error ? e.message : "No se pudo leer la factura");
  } finally {
    if (ocrAbortRef.current === controller) {
      ocrAbortRef.current = null;
      setLeyendoOcr(false);
    }
    if (inputOcr.current) inputOcr.current.value = "";
  }
}

async function quitarEnlace(enlaceId: number) {
  if (!facturaExistente) return;
  setQuitandoEnlace(enlaceId);
  try {
    const res = await fetch(`/api/facturas-recibidas/${facturaExistente.id}/enlaces/${enlaceId}`, { method: "DELETE" });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "Error desconocido");

    setEnlaces(data.factura.enlaces);
    set("pedidoId", data.factura.pedidoId || "");
    set("stockPedidoId", data.factura.stockPedidoId ? String(data.factura.stockPedidoId) : "");
    toast.success("Enlace quitado");
    onGuardado();
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error desconocido");
  } finally {
    setQuitandoEnlace(null);
  }
}

