{!cargando && tabla.length === 0 && (
  <TableRow>
    <TableCell colSpan={9} className="py-8 text-center text-muted-foreground">
      {hayFiltros ? "Ninguna notificación coincide con los filtros" : "Todavía no hay notificaciones registradas"}
    </TableCell>
