/** Marcas habituales del taller, ofrecidas como sugerencia al editar un proveedor aunque aún no las use ninguno. */
const MARCAS_HABITUALES = ["HP", "Dell", "Lenovo", "Acer", "ASUS", "MSI", "Apple", "Microsoft", "Samsung", "Dyson", "Thermomix", "Cecotec"];
const SIN_MARCA = "Sin marca asignada";
import { ProveedorFormDialog } from "./proveedor-form-dialog";
import { toast } from "sonner";

export default function ProveedoresPage() {
  const [proveedores, setProveedores] = useState<Proveedor[]>([]);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [busqueda, setBusqueda] = useState("");
  const [formAbierto, setFormAbierto] = useState(false);
  const [editando, setEditando] = useState<Proveedor | null>(null);
  const [vista, setVista] = useState<"tabla" | "marcas">("tabla");
  const [marcaFiltro, setMarcaFiltro] = useState<string | null>(null);

  async function cargar() {
    setCargando(true);
    setError(null);
    try {
      const res = await fetch("/api/proveedores?todos=true");
      const data = await res.json();
      if (!data.ok) throw new Error(data.error || "Error desconocido");
      setProveedores(data.proveedores as Proveedor[]);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Error desconocido");
    } finally {
      setCargando(false);
    }
  }

  useEffect(() => {
    cargar();
  }, []);

  /** Marcas en uso (de más a menos proveedores) para los filtros, y las sugerencias del formulario. */
  const marcasEnUso = useMemo(() => {
    const cuenta = new Map<string, { nombre: string; n: number }>();
    for (const p of proveedores) {
      for (const m of p.marcas) {

      const k = m.toLowerCase();
      const previa = cuenta.get(k);
      cuenta.set(k, { nombre: previa?.nombre ?? m, n: (previa?.n ?? 0) + 1 });
    }
  }
  return [...cuenta.values()].sort((a, b) => b.n - a.n || a.nombre.localeCompare(b.nombre, "es"));
}, [proveedores]);

const marcasSugeridas = useMemo(() => {
  const vistas = new Set<string>();
  const lista: string[] = [];
  for (const m of [...marcasEnUso.map((x) => x.nombre), ...MARCAS_HABITUALES]) {
    if (!vistas.has(m.toLowerCase())) { vistas.add(m.toLowerCase()); lista.push(m); }
  }
  return lista;
}, [marcasEnUso]);

const filtrados = useMemo(() => {
  const q = busqueda.trim().toLowerCase();
  return proveedores.filter((p) => {
    if (marcaFiltro) {
      const tiene = marcaFiltro === SIN_MARCA ? p.marcas.length === 0 : p.marcas.some((m) => m.toLowerCase() === marcaFiltro.toLowerCase());
      if (!tiene) return false;
    }
    if (!q) return true;
    return [p.nombre, p.dniCif, p.telefono, p.email, p.codigoInterno, p.marcas.join(" ")].some((v) => v.toLowerCase().includes(q));
  });
}, [proveedores, busqueda, marcaFiltro]);

/** Vista "Por marcas": cada marca con sus proveedores (un proveedor sale en todas las marcas que atiende). */
const grupos = useMemo(() => {
  const mapa = new Map<string, { marca: string; proveedores: Proveedor[] }>();
  for (const p of filtrados) {
    const marcas = p.marcas.length ? p.marcas : [SIN_MARCA];
    for (const m of marcas) {
      const k = m.toLowerCase();
      const g = mapa.get(k) ?? { marca: m, proveedores: [] };
      g.proveedores.push(p);
      mapa.set(k, g);
    }
  }
  return [...mapa.values()].sort((a, b) => {
    if (a.marca === SIN_MARCA) return 1;
    if (b.marca === SIN_MARCA) return -1;
    return a.marca.localeCompare(b.marca, "es");
  });
}, [filtrados]);

const haySinMarca = proveedores.some((p) => p.marcas.length === 0);

async function mostrarEnListas(p: Proveedor) {
  try {
    const res = await fetch(`/api/proveedores/${p.proveedorId}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },

      body: JSON.stringify({ notas: "Registrado a mano (antes creado automáticamente)" }),
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "Error desconocido");
    toast.success("Ahora sale en las listas de pedidos");
    cargar();
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error desconocido");
  }
}

async function alternarActivo(p: Proveedor) {
  try {
    const res = await fetch(`/api/proveedores/${p.proveedorId}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ activo: !p.activo }),
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "Error desconocido");
    toast.success(p.activo ? "Proveedor desactivado" : "Proveedor activado");
    cargar();
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error desconocido");
  }
}

return (
  <div className="p-6 space-y-3">
    <div className="flex flex-wrap items-center justify-between gap-3">
      <div className="flex items-center gap-2.5">
        <span className="flex size-9 shrink-0 items-center justify-center rounded-full bg-linear-to-br from-orange-500 to-amber-600 text-white">
          <Truck className="size-4.5" />
        </span>
        <div>
          <h1 className="text-lg font-semibold">Proveedores</h1>
          <p className="text-sm text-muted-foreground">AliExpress, eBay, Amazon y demás proveedores de piezas — datos fiscales para Facturas Recibidas</p>
        </div>
      </div>
      <div className="flex items-center gap-2">
        <Button variant="outline" size="icon" className="size-8" onClick={cargar} title="Actualizar">
          <Refresh2 className={`size-4 ${cargando ? "animate-spin" : ""}`} />
        </Button>
        <Button size="sm" className="gap-1.5" onClick={() => { setEditando(null); setFormAbierto(true); }}>
          <Add className="size-4" /> Nuevo proveedor
        </Button>
      </div>
    </div>

    <div className="flex flex-wrap items-center gap-3">
      <div className="relative w-full max-w-sm">

                        {p.marcas.map((m) => <span key={m} className="rounded-full bg-muted px-2 py-0.5 text-xs">{m}</span>)}
                      </div>
                    ) : <span className="text-muted-foreground">—</span>}
                  </TableCell>
                  <TableCell className="text-sm">{p.dniCif || <span className="text-muted-foreground">—</span>}</TableCell>
                  <TableCell className="text-sm">{p.codigoInterno || <span className="text-muted-foreground">—</span>}</TableCell>
                  <TableCell className="text-sm">{p.telefono || <span className="text-muted-foreground">—</span>}</TableCell>
                  <TableCell className="text-sm">{p.email || <span className="text-muted-foreground">—</span>}</TableCell>
                  <TableCell>
                    <span className={`inline-flex rounded-md px-2 py-0.5 text-xs font-medium ${p.activo ? "bg-green-500/10 text-green-600 dark:text-green-400" : "bg-muted text-muted-foreground"}`}>
                      {p.activo ? "Activo" : "Desactivado"}
                    </span>
                  </TableCell>
                  <TableCell className="text-right">
                    <Button size="sm" variant="ghost" className="h-7 gap-1" onClick={() => { setEditando(p); setFormAbierto(true); }}>
                      <Edit2 className="size-3.5" /> Editar
                    </Button>
                    {p.automatico && (
                      <Button size="sm" variant="ghost" className="h-7" title="Dejarlo en las listas de pedidos" onClick={() => mostrarEnListas(p)}>
                        Mostrar en pedidos
                      </Button>
                    )}
                    <Button size="sm" variant="ghost" className="h-7" onClick={() => alternarActivo(p)}>
                      {p.activo ? "Desactivar" : "Activar"}
                    </Button>
                  </TableCell>
                </TableRow>
              ))}
          </TableBody>
        </Table>
      </div>

      <ProveedorFormDialog proveedorExistente={editando} marcasSugeridas={marcasSugeridas} open={formAbierto} onOpenChange={setFormAbierto} onGuardado={cargar} />
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { Truck } from "@/lib/icons";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import { Proveedor, ProveedorFormData, normalizarMarcas } from "@/lib/proveedores";
import { esEmailValido } from "@/lib/validacion";

function vacio(): ProveedorFormData {
  return { nombre: "", dniCif: "", nifIva: "", direccionFiscal: "", pais: "", telefono: "", email: "", codigoInterno: "", notas: "", marcas: "" };
}

function desdeExistente(p: Proveedor): ProveedorFormData {
  return {
    nombre: p.nombre, dniCif: p.dniCif, nifIva: p.nifIva, direccionFiscal: p.direccionFiscal, pais: p.pais,
    telefono: p.telefono, email: p.email, codigoInterno: p.codigoInterno, notas: p.notas, marcas: p.marcas.join(", "),
  };
}

export function ProveedorFormDialog({
  proveedorExistente,
  open,
  onOpenChange,
  onGuardado,
  marcasSugeridas = [],
}: {
  /** Marcas que ya usan otros proveedores y las habituales, para añadirlas con un clic. */
  marcasSugeridas?: string[];
  proveedorExistente: Proveedor | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onGuardado: (proveedor: Proveedor) => void;
}) {
  const [datos, setDatos] = useState<ProveedorFormData>(() => (proveedorExistente ? desdeExistente(proveedorExistente) : vacio()));
  const [enviando, setEnviando] = useState(false);
  const esEdicion = proveedorExistente !== null;

  useEffect(() => {
    if (open) setDatos(proveedorExistente ? desdeExistente(proveedorExistente) : vacio());
  }, [open, proveedorExistente]);

  function actualizar<K extends keyof ProveedorFormData>(campo: K, valor: string) {
    setDatos((prev) => ({ ...prev, [campo]: valor }));
  }

  const marcasActuales = normalizarMarcas(datos.marcas);

  function alternarMarca(marca: string) {
    const existe = marcasActuales.some((m) => m.toLowerCase() === marca.toLowerCase());

  const nuevas = existe ? marcasActuales.filter((m) => m.toLowerCase() !== marca.toLowerCase()) : [...marcasActuales, marca];
  setDatos((prev) => ({ ...prev, marcas: nuevas.join(", ") }));
}

async function guardar() {
  if (!datos.nombre.trim()) return toast.error("El nombre es obligatorio");
  if (datos.email && !esEmailValido(datos.email)) return toast.error("El email no es válido");

  setEnviando(true);
  try {
    const url = esEdicion ? `/api/proveedores/${proveedorExistente!.proveedorId}` : "/api/proveedores";
    const res = await fetch(url, {
      method: esEdicion ? "PATCH" : "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(datos),
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "Error desconocido");
    toast.success(esEdicion ? "Proveedor actualizado" : "Proveedor creado");
    onOpenChange(false);
    onGuardado(data.proveedor);
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error desconocido");
  } finally {
    setEnviando(false);
  }
}

return (
  <Dialog
    open={open}
    onOpenChange={(o) => {
      if (enviando) return;
      if (!o) setDatos(proveedorExistente ? desdeExistente(proveedorExistente) : vacio());
      onOpenChange(o);
    }}
  >
    <DialogContent className="max-w-lg sm:max-w-lg" showCloseButton={!enviando}>
      <DialogHeader>
        <DialogTitle className="flex items-center gap-2">
          <Truck className="size-5" /> {esEdicion ? "Editar proveedor" : "Nuevo proveedor"}
        </DialogTitle>
      </DialogHeader>

      <div className="space-y-3">
        <div className="grid gap-3 sm:grid-cols-2">
          <div className="space-y-1.5 sm:col-span-2">
            <Label htmlFor="pvNombre">Nombre / Razón social *</Label>
            <Input id="pvNombre" value={datos.nombre} onChange={(e) => actualizar("nombre", e.target.value)} />
          </div>
          <div className="space-y-1.5">
            <Label htmlFor="pvDniCif">DNI / CIF</Label>

            {marcasSugeridas.length > 0 && (
              <div className="flex flex-wrap gap-1.5 pt-0.5">
                {marcasSugeridas.map((m) => {
                  const activa = marcasActuales.some((x) => x.toLowerCase() === m.toLowerCase());
                  return (
                    <button
                      key={m}
                      type="button"
                      onClick={() => alternarMarca(m)}
                      className={`rounded-full border px-2 py-0.5 text-xs transition-colors ${activa ? "border-primary bg-primary/10 font-medium text-primary" : "text-muted-foreground hover:bg-muted"}`}
                    >
                      {m}
                    </button>
                  );
                })}
              </div>
            )}
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="pvNotas">Notas</Label>
            <Textarea id="pvNotas" rows={2} value={datos.notas} onChange={(e) => actualizar("notas", e.target.value)} />
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)} disabled={enviando}>
            Cancelar
          </Button>
          <Button onClick={guardar} disabled={enviando}>
            {enviando ? "Guardando..." : esEdicion ? "Guardar cambios" : "Crear proveedor"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

