    setRecogidas(data.recogidas as Recogida[]);
  } catch (e) {
    setError(e instanceof Error ? e.message : "Error desconocido");
  } finally {
    setCargando(false);
  }
}

const [sincronizando, setSincronizando] = useState(false);

async function actualizar() {
  setSincronizando(true);
