  if (!resguardo) return;
  setDetalle(null);
  setMensajeAbiertoId(null);
  setSoloEstaReparacion(false);
  setError(null);
  setNuevaObservacion("");
  cargarDetalle();
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [resguardo]);

async function enviarObservacion() {
  if (!resguardo || !nuevaObservacion.trim()) return;
  setEnviandoObservacion(true);
  try {
    const res = await fetch(`/api/reparaciones/${resguardo}/observaciones`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ texto: nuevaObservacion }),
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "Error desconocido");
    setNuevaObservacion("");
    cargarDetalle();
    toast.success("Observación añadida");
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error desconocido");
  } finally {
    setEnviandoObservacion(false);
  }
}

// Reproduce enviarAPuntoLimpio(): si el equipo se recibió por mensajería
// hay que poder facturar la recogida, así que pasa por el mismo modal
// completo que "Entregado en Local" (tipoEntrega RECICLAJE) — el caso
// recibido en LOCAL se resuelve con la confirmación rápida de un clic,
// sin pedir motivo aquí. El motivo (reparable/reciclaje interno/etc.) se

// define después, desde la vista "Punto Limpio" — no al momento de enviar.
async function enviarPuntoLimpio() {
  if (!resguardo) return;
  if (detalle && (detalle.tipoRecepcion || "LOCAL") === "ENVIO") {
    setPuntoLimpioAbierto(true);
    return;
  }
  const ok = await confirmar("¿Confirma que desea enviar este equipo a punto limpio (reciclaje)?");
  if (!ok) return;
  try {
    const res = await fetch(`/api/reparaciones/${resguardo}/salidas`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ accion: "punto_limpio" }),
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "Error desconocido");
    toast.success(`Equipo enviado a punto limpio (${data.diasTotales} días)`);
    actualizarTodo();
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error desconocido");
  }
}

