/** Filtro de texto en el encabezado de una columna. */
function FiltroCabeceraTexto({ label, valor, onCambiar, placeholder }: { label: string; valor: string; onCambiar: (v: string) => void; placeholder?: string }) {
  return (
    <span className="inline-flex items-center gap-1" onClick={(e) => e.stopPropagation()}>
      <Popover>
        <PopoverTrigger render={<button type="button" className="inline-flex" />}>
          <BotonFiltroCabecera activo={!!valor.trim()} titulo={`Filtrar por ${label.toLowerCase()}`} />

  opciones: string[] | OpcionFiltro[];
  seleccionados: string[];
  onCambiar: (valores: string[]) => void;
}) {
  const normalizadas: OpcionFiltro[] = opciones.map((op) => (typeof op === "string" ? { value: op, label: op } : op));

  function toggle(valor: string) {
    if (seleccionados.includes(valor)) {
      onCambiar(seleccionados.filter((v) => v !== valor));
    } else {
      onCambiar([...seleccionados, valor]);
    }
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger className={buttonVariants({ variant: "outline", size: "sm", className: "gap-1.5" })}>
        <Filter className="size-3.5" />
        {label}
        {seleccionados.length > 0 && (
          <Badge variant="default" className="ml-1 h-5 px-1.5">
            {seleccionados.length}
          </Badge>
        )}
        <ArrowDown2 className="size-3" />
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start" className="max-h-72 w-56 overflow-y-auto p-1">
        {normalizadas.length === 0 && (
          <p className="px-2 py-1.5 text-sm text-muted-foreground">Sin opciones</p>
        )}
        {normalizadas.map((op) => (
          <label
            key={op.value}
            className="flex cursor-pointer items-center gap-2 rounded-sm px-2 py-1.5 text-sm hover:bg-accent"
          >
            <Checkbox checked={seleccionados.includes(op.value)} onCheckedChange={() => toggle(op.value)} />
            {op.label}
          </label>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/**
 * useSearchParams() exige un límite <Suspense> alrededor (si no, Next
 * falla el build de esta página) — se aísla aquí en vez de en el
 * componente principal, que ya tiene bastante estado propio.
 */
function AbrirNuevaPorQuery({ onAbrir }: { onAbrir: () => void }) {
  const router = useRouter();
  const searchParams = useSearchParams();

  useEffect(() => {
    if (searchParams.get("nueva") === "1") {
      onAbrir();
      router.replace("/reparaciones");
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [searchParams]);

  return null;
}

/** Reproduce abrirReparacionDesdeFacturas() del original — Facturas de

    Clientes enlaza aquí con ?resguardo=X para abrir el detalle directamente. */
function AbrirDetallePorQuery({ onAbrir }: { onAbrir: (resguardo: string, accion: string | null) => void }) {
  const router = useRouter();
  const searchParams = useSearchParams();

  useEffect(() => {
    const resguardo = searchParams.get("resguardo");
    if (resguardo) {
      // «accion» la manda el asistente de voz: abre además el formulario correspondiente dentro del detalle.
      const accion = searchParams.get("accion");
      onAbrir(resguardo, accion === "presupuesto" || accion === "pedido" || accion === "finalizar" ? accion : null);
      router.replace("/reparaciones");
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [searchParams]);

  return null;
}

