if (!data.ok) throw new Error(data.error || "Error desconocido");
toast.success(esConfirmar ? `Recepción ${reparacionPendiente!.resguardo} confirmada — ${data.nuevoEstado}` : `Reparación ${data.resguardo} registrada`);
