          notas: "",
          // Base SIN IVA: el backend, el PDF y el correo del presupuesto suman el 21 % una sola vez (con totalConIva se cobraba el IVA dos veces).
          manoObra: Math.round(calculoCintas.totalSinIva * 100) / 100,
          diasEntrega: 1,
          tipoPieza: "no",
          piezas: [],
        }),
      }).catch(() => {});
    }

    if (!datos.esCintas && datos.revisionPagada === "corresponde" && !datos.noTieneEmail && datos.clienteEmail.trim()) {
      setMetodoPagoRevisionPrecarga(datos.metodoPagoRevision);
