      fetch(`/api/reparaciones/${resguardoFinal}`)
        .then((r) => r.json())
        .then((d) => { if (d.ok) setDetalleParaRevision(d.detalle as ReparacionDetalle); })
        .catch(() => {});
    }
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error desconocido");
  } finally {
    setGuardando(false);
  }
}

