async function enviarTicket() {
  if (!resultado) return;
  if (!emailParaEnviar) return toast.error("No hay ningún correo de destino disponible");
  const ok = await confirmar(`¿Enviar el ticket ${resultado.numeroTicket} a ${emailParaEnviar}?`);
