"use client";

/**
 * Barras horizontales de una sola serie (magnitud). Sin leyenda: el título
 * de la tarjeta nombra la serie. Cada barra lleva su valor visible al lado
 * — es la "relief rule" que exige el verde de dinero, por debajo de 3:1
 * sobre la superficie clara.
 *
 * Marcas: pista recesiva, extremo de dato redondeado 4px anclado a la
 * base (izquierda), separación entre barras > 2px vía space-y.
 */

export interface FilaBarra {
  clave: string;
  etiqueta: string;
  valor: number;
  /** Texto mostrado a la derecha; si se omite, se usa el valor. */
  valorTexto?: string;
  /** Anotación secundaria opcional (p. ej. desglose R/V). */
  nota?: string;
  /** Resalta la fila (mes en curso). */
  destacada?: boolean;
}

export function Barras({
  filas,
  color,
  anchoEtiqueta = "w-20",
  anchoValor = "w-20",
  maxAltura = "max-h-72",
  vacio = "Sin datos",
  medallas = false,
}: {
  filas: FilaBarra[];
  /** 'count' (azul) o 'money' (verde) — el tono codifica qué mide la barra. */
  color: "count" | "money";
  anchoEtiqueta?: string;
  anchoValor?: string;
  maxAltura?: string;
  vacio?: string;
  medallas?: boolean;
}) {
  if (!filas.length) {
    return <p className="py-8 text-center text-sm text-muted-foreground">{vacio}</p>;
  }

  const max = Math.max(...filas.map((f) => f.valor), 1);
  const tono = color === "money" ? "var(--chart-money)" : "var(--chart-count)";

  return (
    <div className={`${maxAltura} space-y-1.5 overflow-y-auto pr-1`}>
      {filas.map((f, i) => {
        const pct = Math.max(1, Math.round((f.valor / max) * 100));
        return (
          <div key={f.clave} className="flex items-center gap-2 text-xs">
            {medallas && (
              <span className="w-5 shrink-0 text-center text-[0.7rem] text-muted-foreground">
                {i === 0 ? "🥇" : i === 1 ? "🥈" : i === 2 ? "🥉" : `${i + 1}.`}
              </span>
            )}
            <span
              className={`${anchoEtiqueta} shrink-0 truncate text-right ${f.destacada ? "font-semibold text-foreground" : "text-muted-foreground"}`}
              title={f.etiqueta}
            >
              {f.etiqueta}
            </span>

"use client";

import { Bar, BarChart, CartesianGrid, XAxis } from "recharts";
import {
  ChartConfig,
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
} from "@/components/ui/chart";
import { FilaBarra } from "./barras";

const chartConfig: ChartConfig = {
  valor: { label: "Ganancia neta", color: "var(--chart-money)" },
};

/**
 * Reemplaza las barras horizontales de "Ganancia neta por mes" por un
 * gráfico shadcn/Recharts real — mismo dato (barrasMes), mismo color de
 * marca (--chart-money), pero con eje temporal y tooltip nativos en vez
 * de una lista de barras horizontales.
 */
export function GananciaMensualChart({ filas }: { filas: FilaBarra[] }) {
  if (!filas.length) {
    return <p className="py-8 text-center text-sm text-muted-foreground">Sin datos históricos</p>;
  }

  // `filas` llega en orden "más reciente primero" (pensado para la lista de
  // barras horizontales); un eje de tiempo se lee de izquierda a derecha.
  const datos = [...filas].reverse();

  return (
    <ChartContainer config={chartConfig} className="aspect-auto h-56 w-full">
      <BarChart data={datos} margin={{ left: 4, right: 4, top: 8 }}>
        <CartesianGrid vertical={false} strokeDasharray="3 3" />
        <XAxis dataKey="etiqueta" tickLine={false} axisLine={false} tickMargin={8} fontSize={11} />
        <ChartTooltip
          cursor={false}
          content={
            <ChartTooltipContent
              hideLabel
              formatter={(_value, _name, item) => (item.payload as FilaBarra).valorTexto}
            />
          }
        />
        <Bar dataKey="valor" fill="var(--color-valor)" radius={[4, 4, 0, 0]} />
      </BarChart>
    </ChartContainer>
  );
}

