    if (!data.ok) throw new Error(data.error || "Error desconocido");
    toast.success(esEdicion ? "Entrada actualizada" : "Entrada creada");
    onOpenChange(false);
    onGuardado();
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error desconocido");
  } finally {
    setEnviando(false);
  }
}

