useEffect(() => {
  if (!open || !esEdicion || !piezaExistente) return;
  setCargandoHistorial(true);
  fetch(`/api/stock-piezas/${encodeURIComponent(piezaExistente.referencia)}/historial`)
    .then((r) => r.json())
    .then((data) => { if (data.ok) setHistorial(data.historial); })
    .finally(() => setCargandoHistorial(false));
}, [open, esEdicion, piezaExistente]);

function cargarEnlacesYPedidos(referencia: string) {
  setCargandoEnlaces(true);
  Promise.all([
    fetch(`/api/stock-piezas/${encodeURIComponent(referencia)}/enlaces`).then((r) => r.json()),
    fetch(`/api/stock-piezas/${encodeURIComponent(referencia)}/pedidos`).then((r) => r.json()),
  ])
    .then(([datosEnlaces, datosPedidos]) => {
      // Postgres devuelve NUMERIC como string ("42.92") — sin pasar por
      // el mapper, `costo` quedaba como string en un campo tipado
      // `number | null`, y e.costo.toFixed(2) explotaba en cuanto una
      // pieza tenía algún enlace de compra con costo cargado, tirando
      // abajo toda la página. Bug real reportado, 2026-09-18.
      if (datosEnlaces.ok) setEnlaces((datosEnlaces.enlaces as Parameters<typeof mapearEnlaceCompra>[0][]).map(mapearEnlaceCompra));
      if (datosPedidos.ok) setPedidos((datosPedidos.pedidos as Parameters<typeof mapearPedidoStock>[0][]).map(mapearPedidoStock));
    })
    .finally(() => setCargandoEnlaces(false));
}

useEffect(() => {
  if (!open || !esEdicion || !piezaExistente) return;
  cargarEnlacesYPedidos(piezaExistente.referencia);
}, [open, esEdicion, piezaExistente]);

function actualizar<K extends keyof DatosStockPiezaForm>(campo: K, valor: DatosStockPiezaForm[K]) {
  setDatos((prev) => ({ ...prev, [campo]: valor }));
}

// La misma pieza puede llamarse distinto según el proveedor — se guardan
// en la propia fila (no es una tabla aparte como "Enlaces de compra"),
// así que solo se tocan en local y se mandan juntas al Guardar/Crear.
// Petición del usuario, 2026-10-12.
// Cada nombre alternativo lleva su propio código de proveedor (cada proveedor usa su código): las dos listas van siempre
// en el mismo orden y miden lo mismo. Petición del usuario, 2026-10-27.
const codigosAlt = alinearCodigos(datos.nombresInternoProveedorAlt, datos.codigosInternoProveedorAlt);

function agregarNombreAlt() {
  const n = nuevoNombreAlt.trim();
  const c = nuevoCodigoAlt.trim();
  if (!n) return;
  if (datos.nombresInternoProveedorAlt.some((x) => x.toLowerCase() === n.toLowerCase())) {
    setNuevoNombreAlt("");
    setNuevoCodigoAlt("");
    return;
  }
  setDatos((d) => ({
    ...d,
    nombresInternoProveedorAlt: [...d.nombresInternoProveedorAlt, n],
    codigosInternoProveedorAlt: [...alinearCodigos(d.nombresInternoProveedorAlt, d.codigosInternoProveedorAlt), c],
  }));
  setNuevoNombreAlt("");
  setNuevoCodigoAlt("");
}

function quitarNombreAlt(indice: number) {
  setDatos((d) => ({
    ...d,
    nombresInternoProveedorAlt: d.nombresInternoProveedorAlt.filter((_, i) => i !== indice),
    codigosInternoProveedorAlt: alinearCodigos(d.nombresInternoProveedorAlt, d.codigosInternoProveedorAlt).filter((_, i) => i !== indice),
  }));
}

/** Cambia el código de un nombre alternativo ya añadido. */
function cambiarCodigoAlt(indice: number, codigo: string) {
  setDatos((d) => ({
    ...d,
    codigosInternoProveedorAlt: alinearCodigos(d.nombresInternoProveedorAlt, d.codigosInternoProveedorAlt).map((c, i) => (i === indice ? codigo : c)),
  }));
}

async function guardar() {
  if (!datos.referencia.trim()) return toast.error("La referencia es obligatoria");
  // Mismas reglas que el servidor, pero diciendo exactamente qué falla (antes solo salía «entre 3 y 60 caracteres»).
  if (!esEdicion) {
    const ref = datos.referencia.trim();

    if (ref.length < 3) return toast.error(`La referencia es demasiado corta (${ref.length}): mínimo 3 caracteres.`);
    if (ref.length > 60) return toast.error(`La referencia es demasiado larga (${ref.length}): máximo 60 caracteres. Usa un código corto y pon el nombre completo en «Nombre comercial».`);
    if (/\s/.test(ref)) return toast.error("La referencia no puede llevar espacios: usa guiones, p. ej. TM-001.");
    if (!/^[A-Za-z0-9]/.test(ref)) return toast.error("La referencia debe empezar por una letra o un número.");
    const raro = ref.match(/[^A-Za-z0-9._\/-]/);
    if (raro) return toast.error(`La referencia lleva un carácter no permitido («${raro[0]}»): solo letras, números, punto, guion o barra.`);
  }
  if (!datos.nombre.trim() && !datos.nombreInternoProveedor.trim()) {
    return toast.error("Pon al menos el nombre comercial o el nombre interno de proveedor");
  }

  setEnviando(true);
  try {
    const url = esEdicion ? `/api/stock-piezas/${encodeURIComponent(piezaExistente!.referencia)}` : "/api/stock-piezas";
    const res = await fetch(url, {
      method: esEdicion ? "PATCH" : "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ ...datos, referencia: datos.referencia.trim().toUpperCase(), origenResguardo }),
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "Error desconocido");
    toast.success(esEdicion ? "Pieza actualizada" : "Pieza creada");
    onOpenChange(false);
    onGuardado();
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error desconocido");
  } finally {
    setEnviando(false);
  }
}

async function agregarEnlace() {
  if (!piezaExistente) return;
  if (!nuevoEnlace.trim()) return toast.error("El enlace de compra es obligatorio");
  setAgregandoEnlace(true);
  try {
    const res = await fetch(`/api/stock-piezas/${encodeURIComponent(piezaExistente.referencia)}/enlaces`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },

      body: JSON.stringify({ proveedor: nuevoProveedor, costo: nuevoCosto ? Number(nuevoCosto) : null, enlace: nuevoEnlace }),
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "Error desconocido");
    toast.success("Enlace agregado");
    setNuevoProveedor("");
    setNuevoCosto("");
    setNuevoEnlace("");
    cargarEnlacesYPedidos(piezaExistente.referencia);
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error desconocido");
  } finally {
    setAgregandoEnlace(false);
  }
}

async function eliminarEnlace(id: number) {
  if (!piezaExistente) return;
  try {
    const res = await fetch(`/api/stock-piezas/enlaces/${id}`, { method: "DELETE" });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "Error desconocido");
    setEnlaces((prev) => prev.filter((e) => e.id !== id));
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error desconocido");
  }
}

async function confirmarPedido() {
  if (!piezaExistente || !pedirEnlace) return;
  const cantidad = Number.parseInt(pedidoCantidad, 10);
  if (!Number.isFinite(cantidad) || cantidad <= 0) return toast.error("La cantidad debe ser mayor que 0");
  setRegistrandoPedido(true);
  try {
    const res = await fetch(`/api/stock-piezas/${encodeURIComponent(piezaExistente.referencia)}/pedidos`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ enlaceId: pedirEnlace.id, cantidad, fechaEstimadaLlegada: pedidoFecha || null }),
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "Error desconocido");
    toast.success("Pedido registrado");
    setPedirEnlace(null);
    setPedidoCantidad("1");
    setPedidoFecha("");
    cargarEnlacesYPedidos(piezaExistente.referencia);
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error desconocido");
  } finally {
    setRegistrandoPedido(false);
  }
}

async function marcarRecibido(id: number) {
