  ...BANCOS_RETIRADOS.flatMap((b) => [
    { clave: `tarjeta:${b}`, metodo: "tarjeta" as const, banco: b, label: `Tarjeta bancaria · ${b}` },
    { clave: `transferencia:${b}`, metodo: "transferencia" as const, banco: b, label: `Transferencia bancaria · ${b}` },
  ]).filter((f) => (segunSistemaDesglosadoDia[f.clave] || 0) !== 0 || importesDia.some((i) => i.metodo === f.clave)),
];

// Todos los tipos, siempre — una fila en 0 € es información tan válida
// como una con movimiento. Petición del usuario, 2026-10-12: "que
// salgan todos los tipos de pago... si no se cobró nada que salga 0".
const filas = filasBase.reduce<{ fila: FilaDesgloseTpv; sistema: number; confirmado: number; totalAcumulado: number }[]>(
  (acc, fila) => {
    const sistema = segunSistemaDesglosadoDia[fila.clave] || 0;
    const v = valorDeclarado(fila.clave);
    const previo = acc.length ? acc[acc.length - 1].totalAcumulado : 0;
    const totalAcumulado = Math.round((previo + v.importe) * 100) / 100;
    return [...acc, { fila, sistema, confirmado: v.importe, totalAcumulado }];
  },
  []
);
const confirmadoTotal = filas.length ? filas[filas.length - 1].totalAcumulado : 0;
const diferencia = Math.round((vendido - confirmadoTotal) * 100) / 100;

{filasVisibles.map(({ fila, sistema, confirmado, totalAcumulado }) => {
  const dirty = esDirty(fila.clave);
  const v = valorDeclarado(fila.clave);
  return (
    <TableRow key={fila.clave}>
      <TableCell className="whitespace-nowrap text-sm font-medium">{fila.label}</TableCell>
      <TableCell className="whitespace-nowrap text-right text-sm tabular-nums">
        {sistema !== 0 ? (
          <button type="button" className="underline-offset-2 hover:underline" title="Ver los cobros de este tipo" onClick={() => setFilaListado(fila)}>
            {euros(sistema)}
          </button>
        ) : (
          euros(sistema)
        )}
      </TableCell>
      <TableCell>
        <div className="flex flex-wrap items-center gap-1.5">
          <DecimalInput
            className="h-8 w-24"
            placeholder="0,00"
            value={confirmado}
            onChange={(n) => setDeclarado((prev) => ({ ...prev, [fila.clave]: { importe: n, notas: v.notas } }))}
          />
          <Input
            className="h-8 min-w-32 flex-1"
            placeholder="Nota (opcional)"
            maxLength={500}
            value={v.notas}
            onChange={(e) => setDeclarado((prev) => ({ ...prev, [fila.clave]: { importe: v.importe, notas: e.target.value } }))}
          />
          <Button
            size="sm"
            variant={dirty ? "default" : "outline"}
            className="h-8 shrink-0"
            disabled={guardando === fila.clave || !dirty}
            onClick={() => guardarDeclaracion(fila.clave)}
          >
            {guardando === fila.clave ? "Guardando…" : "Guardar"}
          </Button>

              title="Eliminar foto"
              disabled={eliminandoFoto === f.id}
              onClick={() => eliminarFoto(f)}
            >
              <CloseCircle className="size-4" />
            </button>
          </div>
        ))}
        <Button size="sm" variant="outline" className="h-8 gap-1.5 text-xs" disabled={subiendoFoto} onClick={() => inputFotoRef.current?.click()}>
          <Gallery className="size-3.5" /> {subiendoFoto ? "Subiendo…" : "Añadir foto"}
        </Button>
        <input ref={inputFotoRef} type="file" accept="image/*" multiple className="hidden" onChange={onSeleccionarFotos} />
      </div>

      <ListadoMovimientosDialog
        fila={filaListado}
        movimientos={filaListado ? movimientosDia.filter((m) => m.metodo === filaListado.metodo && m.banco === filaListado.banco) : []}
        onOpenChange={(o) => !o && setFilaListado(null)}
      />
    </div>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { CardPos, Refresh2, MoneyRecive, Bank } from "@/lib/icons";
import { METODOS_TPV, MovimientoTpv, TpvFotoApi, TpvImporteApi, diaMadrid } from "@/lib/tpv";
import { CalendarioTpv } from "./calendario-tpv";
import { DiaDetalleVista } from "./dia-detalle-vista";

function euros(n: number): string {
  return (n || 0).toLocaleString("es-ES", { style: "currency", currency: "EUR" });
}

/** "AAAA-MM" del mes mostrado — para filtrar qué días entran en las
    tarjetas KPI de arriba, igual mes que el calendario de abajo. */
function clavesMes(mes: Date): string {
  return `${mes.getFullYear()}-${String(mes.getMonth() + 1).padStart(2, "0")}`;
}

/**
 * TPV (antes separado de "Tarjetas", fusionados de vuelta en una sola
 * vista — petición del usuario, 2026-10-12: "son lo mismo, me equivoqué").
 * Calendario mensual primero (mismo patrón que Recogidas): cada día
 * muestra un resumen, y al entrar se sustituye el calendario por el
 * desglose completo de ese día (vista normal, no modal — petición del
 * usuario, 2026-10-12) con el total confirmado acumulado — ver
 * dia-detalle-vista.tsx.
 */
export default function TpvPage() {
  const [segunSistema, setSegunSistema] = useState<Record<string, Record<string, number>>>({});
  const [segunSistemaDesglosado, setSegunSistemaDesglosado] = useState<Record<string, Record<string, number>>>({});
  const [movimientos, setMovimientos] = useState<MovimientoTpv[]>([]);
  const [importes, setImportes] = useState<TpvImporteApi[]>([]);
  const [fotos, setFotos] = useState<TpvFotoApi[]>([]);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [mesActual, setMesActual] = useState(() => {
    const n = new Date();
    return new Date(n.getFullYear(), n.getMonth(), 1);
  });
  const [diaSeleccionado, setDiaSeleccionado] = useState<string | null>(null);

  async function cargar() {
    setCargando(true);
    setError(null);
    try {
      const res = await fetch("/api/tpv");

    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "Error desconocido");
    setSegunSistema(data.segunSistema);
    setSegunSistemaDesglosado(data.segunSistemaDesglosado);
    setMovimientos(data.movimientos as MovimientoTpv[]);
    setImportes(data.importes as TpvImporteApi[]);
    setFotos(data.fotos as TpvFotoApi[]);
  } catch (e) {
    setError(e instanceof Error ? e.message : "Error desconocido");
  } finally {
    setCargando(false);
  }
}

useEffect(() => {
  cargar();
}, []);

const resumenMes = useMemo(() => {
  const prefijo = clavesMes(mesActual);
  let vendido = 0;
  for (const [dia, metodos] of Object.entries(segunSistema)) {
    if (!dia.startsWith(prefijo)) continue;
    for (const m of METODOS_TPV) vendido += metodos[m.value] || 0;
  }
  let confirmado = 0;
  for (const i of importes) {
    if (!i.fecha.startsWith(prefijo)) continue;
    confirmado += Number(i.importe_declarado) || 0;
  }
  vendido = Math.round(vendido * 100) / 100;
  confirmado = Math.round(confirmado * 100) / 100;
  return { vendido, confirmado, diferencia: Math.round((vendido - confirmado) * 100) / 100 };
}, [segunSistema, importes, mesActual]);

if (diaSeleccionado) {
  return (
    <div className="p-6">
      <DiaDetalleVista
        dia={diaSeleccionado}
        segunSistemaDia={segunSistema[diaSeleccionado] || {}}
        segunSistemaDesglosadoDia={segunSistemaDesglosado[diaSeleccionado] || {}}
        movimientosDia={movimientos.filter((m) => diaMadrid(m.fecha) === diaSeleccionado)}
        importesDia={importes.filter((i) => i.fecha === diaSeleccionado)}
        fotosDia={fotos.filter((f) => f.fecha === diaSeleccionado)}
        onVolver={() => setDiaSeleccionado(null)}
        onCambiado={cargar}
      />
    </div>
  );
}

return (
  <div className="p-6">
    <div className="mb-4 flex items-center justify-between">
      <div>
        <h1 className="flex items-center gap-2 text-lg font-semibold">
          <CardPos className="size-5 text-purple-600" /> Facturación del día
        </h1>

