    onOpenChange(false);
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error desconocido");
  } finally {
    setEnviando(false);
  }
}

async function cancelarVenta() {
  if (!venta) return;
  const ok = await confirmar("¿Cancelar esta venta?");
  if (!ok) return;
  setEnviando(true);
  try {
    const res = await fetch(`/api/ventas/${venta.ventaId}/cancelar`, { method: "POST" });
