export default function CampanaDetallePage() {
  const params = useParams<{ id: string }>();
  const confirmar = useConfirm();

  const [campaign, setCampaign] = useState<Campaign | null>(null);
  const [runId, setRunId] = useState<number | null>(null);
  const [run, setRun] = useState<AgentRun | null>(null);
  const [steps, setSteps] = useState<AgentStep[]>([]);
  const [eventos, setEventos] = useState<AgentEvent[]>([]);
  const [budget, setBudget] = useState<CampaignBudget | null>(null);
  const [cargando, setCargando] = useState(true);
  const [enviando, setEnviando] = useState(false);
  const [aprobados, setAprobados] = useState(0);

  const cargar = useCallback(async () => {
    try {
      const c = await fetch(`/api/agentes/campanas/${params.id}`).then((r) => r.json());
      if (c.ok) {
        setCampaign(c.campaign as Campaign);
        setRunId(c.runId ?? null);
      }
      const ev = await fetch(`/api/agentes/campanas/${params.id}/events`).then((r) => r.json());
      if (ev.ok) setEventos(ev.events as AgentEvent[]);
      const bg = await fetch(`/api/agentes/campanas/${params.id}/budget`).then((r) => r.json());
      if (bg.ok) {
        setBudget({
          maxCostUsd: Number(bg.maxCostUsd ?? 0),
          costUsd: Number(bg.costUsd ?? 0),

        remainingUsd: Number(bg.remainingUsd ?? 0),
        byResource: Array.isArray(bg.byResource) ? bg.byResource : [],
      });
    }
    if (c.ok && c.runId) {
      const [rr, ll] = await Promise.all([
        fetch(`/api/agentes/runs/${c.runId}`).then((r) => r.json()),
        fetch(`/api/agentes/runs/${c.runId}/leads`).then((r) => r.json()),
      ]);
      if (rr.ok) {
        // el proxy /api/agentes/runs/:id ya devuelve run/steps mapeados
        setRun(rr.run as AgentRun);
        setSteps(rr.steps as AgentStep[]);
      }
      if (ll.ok) {
        setAprobados((ll.leads as { message_status?: string }[]).filter((x) => x.message_status === "approved").length);
      }
    }
  } catch {
    // silencioso
  } finally {
    setCargando(false);
  }
}, [params.id]);

useEffect(() => {
  cargar();
  const t = setInterval(cargar, 5000);
  return () => clearInterval(t);
}, [cargar]);

async function lanzar() {
  setEnviando(true);
  try {
    const res = await fetch(`/api/agentes/campanas/${params.id}/launch`, { method: "POST" });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "Error");
    toast.success("Campaña lanzada");
    cargar();
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error");
  } finally {
    setEnviando(false);
  }
}

async function dispatch() {
  const ok = await confirmar("¿Enviar los borradores aprobados?", { titulo: "Enviar" });
  if (!ok) return;
  setEnviando(true);
  try {
    const res = await fetch(`/api/agentes/campanas/${params.id}/dispatch`, { method: "POST" });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "Error");
    toast.success(
      data.configured
        ? `Enviados: ${data.dispatched}${data.failed ? `, fallidos: ${data.failed}` : ""}`
