import { NextResponse } from "next/server";
import { COOKIE_EQUIPO_LOCAL } from "@/lib/acceso-local";

export const dynamic = "force-dynamic";

const BASE_URL = process.env.KELATOS_API_BASE_URL;
const TOKEN = process.env.KELATOS_API_TOKEN;

function pagina(titulo: string, texto: string, status = 200) {
  const html = `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${titulo}</title></head>` +
    `<body style="font-family:system-ui,sans-serif;display:flex;min-height:100vh;align-items:center;justify-content:center;background:#f4f4f5;margin:0">` +
    `<div style="max-width:28rem;background:#fff;border:1px solid #e4e4e7;border-radius:12px;padding:24px;text-align:center"><h1 style="font-size:1.1rem;margin:0 0 8px">${titulo}</h1>` +
    `<p style="margin:0;color:#52525b;font-size:.9rem">${texto}</p></div></body></html>`;
  return new NextResponse(html, { status, headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" } });
}

/**
 * Alta de un equipo del local. Un administrador genera un enlace de un solo uso (pantalla «Equipos del local»); al abrirlo en el navegador
 * del PC del local, este queda reconocido con una cookie y la cuenta restringida (src/lib/acceso-local.ts) funciona desde él aunque cambie
 * la IP. Ruta pública (sin sesión, excluida del proxy): la protege el código de un solo uso.
 */
export async function GET(req: Request) {
  const codigo = new URL(req.url).searchParams.get("codigo") || "";
  if (!codigo || !/^[0-9a-f]{20,80}$/.test(codigo)) return pagina("Enlace no válido", "El enlace no es correcto. Pide uno nuevo a un administrador.", 400);
  if (!BASE_URL || !TOKEN) return pagina("No disponible", "Inténtalo de nuevo en unos minutos.", 503);
  try {
    const res = await fetch(`${BASE_URL}/v1/seguridad/acceso-local/equipos/alta`, {
      method: "POST",
      headers: { Authorization: `Bearer ${TOKEN}`, "Content-Type": "application/json" },
      body: JSON.stringify({ codigo, ua: req.headers.get("user-agent") || "" }),
      cache: "no-store",
      signal: AbortSignal.timeout(6000),
    });

    const data = (await res.json().catch(() => ({}))) as { ok?: boolean; token?: string; nombre?: string; error?: string };
    if (!data.ok || !data.token) return pagina("Enlace no válido", data.error || "El enlace ya se usó o caducó. Pide uno nuevo a un administrador.", res.status === 410 ? 410 : 400);
    const resp = pagina("Equipo autorizado", `Este navegador ya está reconocido como equipo del local (${data.nombre ?? "equipo"}). Ya puedes cerrar esta pestaña y usar el dashboard.`);
    resp.cookies.set(COOKIE_EQUIPO_LOCAL, data.token, { httpOnly: true, secure: true, sameSite: "lax", path: "/", maxAge: 60 * 60 * 24 * 400 });
    return resp;
  } catch {
    return pagina("No disponible", "No se pudo completar el alta ahora mismo. Inténtalo de nuevo.", 502);
  }
}

import { NextResponse } from "next/server";
import { auth } from "@/auth";
import { esSuperadmin } from "@/lib/superadmin";
import { origenPropio } from "@/lib/publico-seguridad";
import { kelatosApiGet, kelatosApiPost } from "@/lib/kelatos-api";

export const dynamic = "force-dynamic";

/** Solo administradores: equipos del local autorizados para la cuenta restringida (ver src/lib/acceso-local.ts). */
async function exigirAdmin() {
  const session = await auth();
  const email = session?.user?.email?.toLowerCase();
  if (!email || !(session?.user?.role === "admin" || esSuperadmin(email))) return null;
  return email;
}

export async function GET() {
  if (!(await exigirAdmin())) return NextResponse.json({ ok: false, error: "No autorizado" }, { status: 403 });
  try {
    const data = await kelatosApiGet<{ ok: boolean; equipos: unknown[]; altasPendientes: unknown[] }>("/v1/seguridad/acceso-local/equipos");
    return NextResponse.json({ ok: true, equipos: data.equipos, altasPendientes: data.altasPendientes });
  } catch (error) {
    return NextResponse.json({ ok: false, error: error instanceof Error ? error.message : "Error" }, { status: 502 });
  }
}

export async function POST(req: Request) {
  const email = await exigirAdmin();
  if (!email) return NextResponse.json({ ok: false, error: "No autorizado" }, { status: 403 });
  if (!origenPropio(req)) return NextResponse.json({ ok: false, error: "Solicitud no permitida" }, { status: 403 });
  const body = (await req.json().catch(() => ({}))) as { accion?: string; nombre?: string; id?: number | string; minutos?: number };
  try {
    if (body.accion === "alta") {
      const r = await kelatosApiPost<{ ok: boolean; codigo: string; caduca_en: string }>("/v1/seguridad/acceso-local/altas", {
        nombre: body.nombre, minutos: body.minutos ?? 60, creadoPor: email,
      });
      // El enlace se construye con el dominio desde el que el administrador está usando el dashboard (así lleva el www correcto).
      const origen = new URL(req.url).origin;
      return NextResponse.json({ ok: true, url: `${origen}/api/acceso-local/alta?codigo=${r.codigo}`, caduca_en: r.caduca_en });
    }

    if (["revocar", "aprobar", "rechazar"].includes(String(body.accion)) && /^\d{1,15}$/.test(String(body.id))) {
      await kelatosApiPost(`/v1/seguridad/acceso-local/equipos/${body.id}/${body.accion}`, { nombre: body.nombre });
      return NextResponse.json({ ok: true });
    }
    return NextResponse.json({ ok: false, error: "Acción no válida" }, { status: 400 });
  } catch (error) {
    return NextResponse.json({ ok: false, error: error instanceof Error ? error.message : "Error" }, { status: 502 });
  }
}

import { NextResponse } from "next/server";

export const dynamic = "force-dynamic";

const BASE_URL = process.env.KELATOS_API_BASE_URL;
const TOKEN = process.env.KELATOS_API_TOKEN;

/**
 * Latido del local. Un script en los PCs del local llama aquí cada pocos minutos con un token secreto (cabecera X-Latido-Token); el
 * servidor anota la IP desde la que llega la llamada y, durante unos minutos, la cuenta restringida (ver src/lib/acceso-local.ts)
 * se admite desde esa IP. Así no importa que el proveedor de internet del local cambie la IP.
 *
 * La IP se lee igual que en src/lib/acceso-local.ts (primer valor de X-Forwarded-For), para que las dos comparen lo mismo.
 * Ruta pública (sin sesión, excluida del proxy): la protege el token.
 */
export async function POST(req: Request) {
  const token = req.headers.get("x-latido-token") || "";
  const xff = req.headers.get("x-forwarded-for");
  const ip = xff ? xff.split(",")[0].trim() : req.headers.get("x-real-ip")?.trim() || "";
  if (!token || !ip) return NextResponse.json({ ok: false, error: "Faltan datos" }, { status: 400 });
  if (!BASE_URL || !TOKEN) return NextResponse.json({ ok: false, error: "No disponible" }, { status: 503 });
  try {
    const res = await fetch(`${BASE_URL}/v1/seguridad/acceso-local/latido`, {
      method: "POST",
      headers: { Authorization: `Bearer ${TOKEN}`, "Content-Type": "application/json" },
      body: JSON.stringify({ ip, token }),
      cache: "no-store",
      signal: AbortSignal.timeout(5000),
    });
    const data = (await res.json().catch(() => ({}))) as { ok?: boolean };
    return NextResponse.json({ ok: !!data.ok, ip: data.ok ? ip : undefined }, { status: res.status === 401 ? 401 : data.ok ? 200 : 502 });
  } catch {
    return NextResponse.json({ ok: false, error: "No se pudo registrar" }, { status: 502 });
  }
}

import { NextResponse } from "next/server";
import { auth } from "@/auth";
import { COOKIE_EQUIPO_LOCAL, ipDelClienteDe } from "@/lib/acceso-local";

export const dynamic = "force-dynamic";

const BASE_URL = process.env.KELATOS_API_BASE_URL;
const TOKEN = process.env.KELATOS_API_TOKEN;

async function api(path: string, cuerpo?: unknown): Promise<{ status: number; data: Record<string, unknown> }> {
  const res = await fetch(`${BASE_URL}${path}`, {
    method: cuerpo === undefined ? "GET" : "POST",
    headers: { Authorization: `Bearer ${TOKEN}`, ...(cuerpo === undefined ? {} : { "Content-Type": "application/json" }) },
    body: cuerpo === undefined ? undefined : JSON.stringify(cuerpo),
    cache: "no-store",
    signal: AbortSignal.timeout(5000),
  });
  return { status: res.status, data: (await res.json().catch(() => ({}))) as Record<string, unknown> };
}

/**
 * Solicitud de equipo. Cuando la cuenta restringida (hoy soporte@kelatos.com) se usa desde un navegador, esta ruta le da una marca
 * «pendiente» si no tiene ninguna, o anota su uso si ya la tiene. Un administrador aprueba o rechaza la marca desde «Equipos del local».
 * Hasta que se apruebe, ese navegador solo entra si el modo no es «bloquear» (ver src/lib/acceso-local.ts). Cualquier otra cuenta recibe
 * `aplica: false` y no se toca nada.
 */
export async function POST(req: Request) {
  const session = await auth();
  const email = session?.user?.email?.toLowerCase();
  if (!email) return NextResponse.json({ ok: false, error: "No autenticado" }, { status: 401 });
  if (!BASE_URL || !TOKEN) return NextResponse.json({ ok: false, error: "No disponible" }, { status: 503 });
  try {
    const cfg = await api("/v1/seguridad/acceso-local/config");
    if (!cfg.data.ok || String(cfg.data.cuenta || "").toLowerCase() !== email) return NextResponse.json({ ok: true, aplica: false });

    const cookieActual = (req.headers.get("cookie") || "").split(";").map((c) => c.trim()).find((c) => c.startsWith(`${COOKIE_EQUIPO_LOCAL}=`))?.slice(COOKIE_EQUIPO_LOCAL.length + 1);
    const r = await api("/v1/seguridad/acceso-local/equipos/solicitud", {

      email, ip: ipDelClienteDe(req), ua: req.headers.get("user-agent") || "", token: cookieActual,
    });
    if (!r.data.ok) return NextResponse.json({ ok: false, error: String(r.data.error || "No se pudo registrar") }, { status: r.status === 429 ? 429 : 502 });
    const resp = NextResponse.json({ ok: true, aplica: true, estado: r.data.estado });
    if (typeof r.data.token === "string") {
      resp.cookies.set(COOKIE_EQUIPO_LOCAL, r.data.token, { httpOnly: true, secure: true, sameSite: "lax", path: "/", maxAge: 60 * 60 * 24 * 400 });
    }
    return resp;
  } catch {
    return NextResponse.json({ ok: false, error: "No se pudo registrar" }, { status: 502 });
  }
}

