 * de tabla" del panel de Admin — reutiliza GET /v1/:table/:id, igual que
 * la lista. Ver route.ts (carpeta padre) para el resto del contexto.
 */
export async function GET(
  _req: Request,
  { params }: { params: Promise<{ table: string; id: string }> }
) {
