import { NextResponse } from "next/server";
import { kelatosApiGet, kelatosApiPost } from "@/lib/kelatos-api";
import { BUZON_REDACTAR_EMAIL, type Buzon } from "@/lib/mails";
import { accesoMails, buzonesPropios } from "@/lib/mails-auth";

/** Envía o responde un correo por SMTP con un buzón guardado. Superadmin, o
    una cuenta accesoCompleto pero SOLO con su propio buzón (petición del
    usuario, 2026-09-30: lo único vedado es ver/usar buzones ajenos) — el
    buzonId que mande el cliente se descarta si no es el suyo, nunca se
    confía en lo que llegue del navegador. */
export async function POST(req: Request) {
  const a = await accesoMails();
  if (!a.ok) return NextResponse.json({ ok: false, error: "Tu sesión no tiene acceso a Gestión MAILS. Cierra sesión y vuelve a entrar; si sigue igual, avisa a un administrador." }, { status: 403 });
  if (!a.superadmin) {
    const propios = await buzonesPropios(a);
    const b0 = (await req.clone().json().catch(() => ({}))) as Record<string, unknown>;
    if (!propios || !propios.includes(Number(b0.buzonId))) {
      // Mensaje concreto (antes solo «No autorizado»): qué buzón se intentó usar y cuál le corresponde a esta cuenta.
      return NextResponse.json({ ok: false, error: `No puedes enviar desde ese buzón (nº ${String(b0.buzonId ?? "?")}). A tu cuenta (${a.email}) le corresponde el buzón de ${a.buzonEmail}.` }, { status: 403 });
    }
  }
  try {
    const b = (await req.json()) as Record<string, unknown>;
    // Un correo nuevo solo puede salir desde Soporte (petición del usuario, 2026-11-04); responder usa el buzón del mensaje original.
    if (!b.respondeA) {
      const lista = await kelatosApiGet<{ ok: boolean; buzones: Buzon[] }>("/v1/mails/buzones");
      const elegido = lista.buzones.find((x) => x.id === Number(b.buzonId));
      if (!elegido || elegido.email.toLowerCase() !== BUZON_REDACTAR_EMAIL) {
        return NextResponse.json({ ok: false, error: `Los correos nuevos solo se envían desde ${BUZON_REDACTAR_EMAIL}` }, { status: 403 });
      }
    }
    // Solo los campos que el backend espera; el usuario sale de la sesión, nunca del cuerpo.

    const data = await kelatosApiPost<{ ok: boolean; id: number | null; aceptados: string[]; rechazados: string[]; aviso: string | null }>(
      "/v1/mails/mensajes/enviar",
      {
        buzonId: b.buzonId,
        para: b.para,
        cc: b.cc,
        asunto: b.asunto,
        texto: b.texto,
        respondeA: b.respondeA,
        adjuntos: b.adjuntos,
        forzar: b.forzar === true,
        usuario: a.email,
      }
    );
    return NextResponse.json({ ok: true, id: data.id, aceptados: data.aceptados, rechazados: data.rechazados, aviso: data.aviso });
  } catch (error) {
    return NextResponse.json({ ok: false, error: error instanceof Error ? error.message : "Error desconocido" }, { status: 502 });
  }
}

import { NextResponse } from "next/server";
import { kelatosApiGet } from "@/lib/kelatos-api";
import { accesoMails, buzonesEnviadosVisibles, buzonesPropios } from "@/lib/mails-auth";
import { CONTADORES_VACIOS, type ContadoresMensajes, type MensajeLista } from "@/lib/mails";

const PARAMETROS = ["vista", "buzon", "sinLeer", "agrupar", "q", "cliente", "lead", "email", "desde", "hasta", "limit", "offset"];

/** Lista paginada de mensajes (sin cuerpo) + contadores. Filtra el servidor.
    Una cuenta accesoCompleto nunca puede pedir "todos los buzones" ni el
    buzón de otra cuenta: el parámetro `buzon` que mande el cliente se
    ignora y se fuerza al suyo propio (petición del usuario, 2026-09-30). */
export async function GET(req: Request) {
  const a = await accesoMails();
  if (!a.ok) return a.respuesta;
  try {
    const propios = await buzonesPropios(a);
    if (propios && propios.length === 0) {
      return NextResponse.json({ ok: true, total: 0, contadores: CONTADORES_VACIOS, mensajes: [] });
    }
    const p = new URL(req.url).searchParams;
    const params: Record<string, string> = {};
    for (const k of PARAMETROS) {
      const v = p.get(k);
      if (v) params[k] = v;
    }
    if (propios) {
      params.buzon = String(propios[0]);
      const extra = await buzonesEnviadosVisibles(a);
      if (extra.length) params.tambien = extra.join(",");
    }
    const data = await kelatosApiGet<{ ok: boolean; total: number; contadores: ContadoresMensajes; mensajes: MensajeLista[] }>("/v1/mails/mensajes", params);
    return NextResponse.json(data);
  } catch (error) {
    return NextResponse.json({ ok: false, error: error instanceof Error ? error.message : "Error desconocido" }, { status: 502 });
  }
}

import { NextResponse } from "next/server";
import { kelatosApiGet } from "@/lib/kelatos-api";
import { accesoMails, buzonesEnviadosVisibles, buzonesPropios, esVisibleExtra } from "@/lib/mails-auth";
import type { MensajeHilo } from "@/lib/mails";

/** Todos los mensajes de la conversación de un mensaje (con su cuerpo). No marca nada como leído. */
export async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const a = await accesoMails();
  if (!a.ok) return a.respuesta;
  try {
    const { id } = await params;
    const data = await kelatosApiGet<{ ok: boolean; mensajes: MensajeHilo[] }>(`/v1/mails/mensajes/${encodeURIComponent(id)}/hilo`);
    // Recorte por buzón propio, mismo criterio que /mensajes/[id] (2026-09-30).
    const propios = await buzonesPropios(a);
    const extra = propios ? await buzonesEnviadosVisibles(a) : [];
    const mensajes = propios
      ? data.mensajes.filter((m) => propios.includes(m.buzon_id) || (extra.includes(m.buzon_id) && esVisibleExtra(m)))
      : data.mensajes;
    return NextResponse.json({ ok: true, mensajes });
  } catch (error) {
    return NextResponse.json({ ok: false, error: error instanceof Error ? error.message : "Error desconocido" }, { status: 502 });
  }
}

import { NextResponse } from "next/server";
import { kelatosApiGet, kelatosApiPost } from "@/lib/kelatos-api";
import { accesoMails, buzonesEnviadosVisibles, buzonesPropios, esVisibleExtra } from "@/lib/mails-auth";
import type { MensajeDetalle } from "@/lib/mails";

/** Mensaje completo (con cuerpo). Al abrirlo se marca como leído en el app:
    solo aquí, nunca en el servidor de correo. */
export async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const a = await accesoMails();
  if (!a.ok) return a.respuesta;
  try {
    const { id } = await params;
    const data = await kelatosApiGet<{ ok: boolean; mensaje: MensajeDetalle }>(`/v1/mails/mensajes/${encodeURIComponent(id)}`);
    // Una cuenta accesoCompleto no puede abrir un mensaje de un buzón que no
    // es el suyo, aunque conozca o adivine el id (2026-09-30).
    const propios = await buzonesPropios(a);
    const extra = propios ? await buzonesEnviadosVisibles(a) : [];
    const m = data.mensaje as unknown as { buzon_id: number; direccion?: string; enviado_por?: string | null };
    if (propios && !propios.includes(m.buzon_id) && !(extra.includes(m.buzon_id) && esVisibleExtra(m))) {
      return NextResponse.json({ ok: false, error: "No autorizado" }, { status: 403 });
    }
    if (!data.mensaje.leido) {
      kelatosApiPost(`/v1/mails/mensajes/${encodeURIComponent(id)}/leido`, {}).catch(() => {});
    }
    return NextResponse.json({ ok: true, mensaje: data.mensaje });
  } catch (error) {
    return NextResponse.json({ ok: false, error: error instanceof Error ? error.message : "Error desconocido" }, { status: 502 });
  }
}

