import { NextResponse } from "next/server";
import { kelatosApiGet } from "@/lib/kelatos-api";
import { CATEGORIAS, CategoriaNotificacion, RespuestaNotificaciones, TIPOS_CONOCIDOS, tiposDeCategoria, tiposQueCoinciden } from "@/lib/notificaciones";

/**
 * Registro de notificaciones para el "Centro de notificaciones". El filtrado,
 * los KPI y la paginación los hace el backend (una sola consulta): el
 * navegador recibe una página (por defecto 100 filas) y los totales, no todo
 * el registro. `categoria` se traduce aquí a la lista de tipos que contiene.
 */
export async function GET(req: Request) {
  try {
    const p = new URL(req.url).searchParams;
    const params: Record<string, string | number | undefined> = {
      dias: p.get("dias") || "180",
      desde: p.get("desde") || undefined,
      hasta: p.get("hasta") || undefined,
      canal: p.get("canal") || undefined,
      tipo: p.get("tipo") || undefined,
      estado: p.get("estado") || undefined,
      limit: p.get("limit") || "100",
      offset: p.get("offset") || "0",
    };
    const q = p.get("q")?.trim();
    if (q) {
      params.q = q;
      const t = tiposQueCoinciden(q);
      if (t.length) params.tiposQ = t.join(",");
    }
    const categoria = p.get("categoria") as CategoriaNotificacion | null;
    if (categoria && categoria in CATEGORIAS) {
      if (categoria === "otros") params.tiposNo = TIPOS_CONOCIDOS.join(",");
      else params.tipos = tiposDeCategoria(categoria).join(",");
    }
    const data = await kelatosApiGet<RespuestaNotificaciones>("/v1/lecturas/centro-notificaciones", params);
    return NextResponse.json(data);
  } catch (error) {
    const message = error instanceof Error ? error.message : "Error desconocido";
    return NextResponse.json({ ok: false, error: message }, { status: 502 });
  }
}

import crypto from "node:crypto";
import { NextResponse } from "next/server";
import { auth } from "@/auth";
import { kelatosApiPost } from "@/lib/kelatos-api";

/**
 * Proxy de POST /v1/pedidos/cambiar-estado-masivo (cambiarEstadoPedido /
 * marcarPiezaEnTransito / _ejecutarRecepcionPedidos del original) — cambia
 * el estado de uno o varios pedidos a la vez (p.ej. "En Tránsito" o
 * "Recibido"); cuando el nuevo estado es "Recibido" y ya no quedan pedidos
 * pendientes para una reparación, el backend la pasa automáticamente a
 * "Pieza Entregada" (misma regla que el original).
 */
export async function POST(req: Request) {
  const session = await auth();
  const usuario = session?.user?.email;
  if (!usuario) return NextResponse.json({ ok: false, error: "No autenticado" }, { status: 401 });

  const body = (await req.json()) as { pedidos: string[]; estado: string; recibidoPor?: string };
  if (!Array.isArray(body.pedidos) || body.pedidos.length === 0) {
    return NextResponse.json({ ok: false, error: "Selecciona al menos un pedido" }, { status: 400 });
  }
  if (!body.estado?.trim()) {
    return NextResponse.json({ ok: false, error: "Falta el estado" }, { status: 400 });
  }

  try {
    const resultado = await kelatosApiPost<{
      ok: boolean;
      pedidos: Record<string, unknown>[];
      reparaciones: Record<string, unknown>[];
    }>("/v1/pedidos/cambiar-estado-masivo", {
      requestId: crypto.randomUUID(),
      usuario,
      estado: body.estado,
      pedidos: body.pedidos,
      ...(body.recibidoPor ? { datos: { recibidoPor: body.recibidoPor } } : {}),
    });
    return NextResponse.json({ ok: true, pedidos: resultado.pedidos, reparaciones: resultado.reparaciones });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Error desconocido";
    return NextResponse.json({ ok: false, error: message }, { status: 502 });
  }
}

