import { NextResponse } from "next/server";
import { auth } from "@/auth";
import { kelatosApiGet, kelatosApiPost } from "@/lib/kelatos-api";
import { puedeVerProspeccion } from "@/lib/prospeccion";

// Proxy único hacia /v1/prospeccion/* del API (solo administradores). Rutas permitidas, por lista cerrada.
const PERMITIDAS = [/^config$/, /^resumen$/, /^envios$/, /^envios\/\d+$/, /^envios\/\d+\/(aprobar|omitir|enviar)$/, /^generar$/, /^busqueda-diaria$/, /^busqueda-diaria\/ejecutar$/, /^clientes$/, /^respuestas$/, /^bandeja$/, /^clientes\/sincronizar$/, /^leads$/, /^leads\/(sectores|estado|buscar|importar|descartar)$/];

async function resolver(req: Request, params: Promise<{ ruta: string[] }>, metodo: "GET" | "POST" | "PUT" | "PATCH") {
  const session = await auth();
  if (!puedeVerProspeccion(session?.user)) return NextResponse.json({ ok: false, error: "Sin acceso a Prospección" }, { status: 403 });
  const ruta = (await params).ruta.join("/");
  if (!PERMITIDAS.some((r) => r.test(ruta))) return NextResponse.json({ ok: false, error: "Ruta no válida" }, { status: 404 });
  try {
    if (metodo === "GET") {
      const q = new URL(req.url).search;
      return NextResponse.json(await kelatosApiGet<object>(`/v1/prospeccion/${ruta}${q}`));
    }
    const cuerpo = (await req.json().catch(() => ({}))) as Record<string, unknown>;
    return NextResponse.json(await kelatosApiPost<object>(`/v1/prospeccion/${ruta}`, { ...cuerpo, usuario: session?.user?.email }, metodo));
  } catch (error) {
    return NextResponse.json({ ok: false, error: error instanceof Error ? error.message : "Error desconocido" }, { status: 400 });
  }
}

type Ctx = { params: Promise<{ ruta: string[] }> };
export const GET = (req: Request, c: Ctx) => resolver(req, c.params, "GET");
export const POST = (req: Request, c: Ctx) => resolver(req, c.params, "POST");
export const PUT = (req: Request, c: Ctx) => resolver(req, c.params, "PUT");
export const PATCH = (req: Request, c: Ctx) => resolver(req, c.params, "PATCH");

import { NextResponse } from "next/server";
import { auth } from "@/auth";
import { kelatosApiGet, kelatosApiPost } from "@/lib/kelatos-api";
import { mapearProveedor, generarProveedorId, normalizarMarcas, type ProveedorFormData } from "@/lib/proveedores";

// Reexportado para no romper los imports existentes ("@/app/api/proveedores/route")
// en compras/page.tsx, ventas/detalle-venta-dialog.tsx, presupuesto-*-dialog.tsx,
// reportar-problema-pieza-dialog.tsx y registrar-pedido-dialog.tsx — el tipo
// nuevo es un superconjunto del que usaban (proveedorId/nombre/activo siguen
// ahí, con más campos encima), así que es compatible sin tocarlos.
export type { Proveedor } from "@/lib/proveedores";

interface FilaProveedorSql {
  proveedor_id: string;
  nombre: string | null;
  dni_cif: string | null;
  nif_iva?: string | null;
  direccion_fiscal: string | null;
  pais: string | null;
  telefono: string | null;
  email: string | null;
  codigo_interno: string | null;
  notas: string | null;
  marcas: string | null;
  activo: boolean | null;
}

interface RespuestaProveedores {
  ok: boolean;
  rows: FilaProveedorSql[];
}

/** Proxy de GET /v1/proveedores. Por defecto solo activos (selector de
    "Proveedor" en piezas a pedir); ?todos=true los trae todos (pantalla de
    Proveedores, que también necesita ver/editar los desactivados). */
export async function GET(req: Request) {
  try {
    const todos = new URL(req.url).searchParams.get("todos") === "true";
    const data = await kelatosApiGet<RespuestaProveedores>("/v1/proveedores", { limit: 500, order: "nombre" });
    const proveedores = data.rows.filter((r) => todos || r.activo !== false).map(mapearProveedor);
    return NextResponse.json({ ok: true, proveedores });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Error desconocido";
    return NextResponse.json({ ok: false, error: message }, { status: 502 });
  }
}

export async function POST(req: Request) {
  const session = await auth();
  if (!session?.user?.email) return NextResponse.json({ ok: false, error: "No autenticado" }, { status: 401 });

  const datos = (await req.json()) as ProveedorFormData;

  if (!datos.nombre?.trim()) return NextResponse.json({ ok: false, error: "El nombre es obligatorio" }, { status: 400 });

  try {
    const resultado = await kelatosApiPost<{ ok: boolean; row: FilaProveedorSql }>("/v1/proveedores", {
      proveedor_id: generarProveedorId(datos.nombre),
      nombre: datos.nombre.trim(),
      dni_cif: datos.dniCif?.trim() || null,
      nif_iva: datos.nifIva?.trim().toUpperCase() || null,
      direccion_fiscal: datos.direccionFiscal?.trim() || null,
      pais: datos.pais?.trim() || null,
      telefono: datos.telefono?.trim() || null,
      email: datos.email?.trim() || null,
      codigo_interno: datos.codigoInterno?.trim() || null,
      notas: datos.notas?.trim() || null,
      marcas: normalizarMarcas(datos.marcas).join(", "),
      activo: true,
    });
    return NextResponse.json({ ok: true, proveedor: mapearProveedor(resultado.row) });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Error desconocido";
    return NextResponse.json({ ok: false, error: message }, { status: 502 });
  }
}

