import { NextResponse } from "next/server";
import { auth } from "@/auth";
import { kelatosApiGet, kelatosApiPost } from "@/lib/kelatos-api";
import { mapearReparacionDetalle } from "@/lib/reparacion-detalle";
import { esSuperadmin } from "@/lib/superadmin";

interface ListaGenerica<T> {
  ok: boolean;
  rows: T[];
}

interface FilaPresupuesto {
  presupuesto_id: string;
  [key: string]: unknown;
}

interface FilaPieza {
  presupuesto_id: string;
  [key: string]: unknown;
}

export async function GET(
  _req: Request,
  { params }: { params: Promise<{ resguardo: string }> }
) {
  const { resguardo } = await params;
  try {
    const [reparacion, presupuestos, pedidos, historial, proveedores] = await Promise.all([
      kelatosApiGet<{ ok: boolean; row: Record<string, unknown> }>(`/v1/reparaciones/${resguardo}`),
      kelatosApiGet<ListaGenerica<FilaPresupuesto>>("/v1/presupuestos", {
        resguardo,
        limit: 1000,
        order: "version",
        direction: "asc",
      }),
      kelatosApiGet<ListaGenerica<Record<string, unknown>>>("/v1/pedidos", {
        resguardo,
        limit: 1000,
        order: "pedido_id",
        direction: "asc",
      }),
      kelatosApiGet<ListaGenerica<Record<string, unknown>>>("/v1/historial", {
        resguardo,
        limit: 1000,
        order: "fecha_hora",
        direction: "desc",
      }),
      // Catálogo pequeño (10 filas) de plataformas/marcas — se usa solo
      // para mostrar el nombre en la tarjeta de Pedidos (antes solo se
      // veía el código de pedido, sin identificar Amazon/AliExpress/etc.).
      kelatosApiGet<ListaGenerica<{ proveedor_id: string; nombre: string }>>("/v1/proveedores", {
        limit: 1000,
      }),
    ]);

    const proveedoresPorId: Record<string, string> = {};
    for (const p of proveedores.rows) {
      if (p.proveedor_id) proveedoresPorId[p.proveedor_id] = p.nombre || "";
    }

    const piezasPorPresupuesto: Record<string, FilaPieza[]> = {};
    await Promise.all(
      presupuestos.rows.map(async (p) => {
        const piezas = await kelatosApiGet<ListaGenerica<FilaPieza>>("/v1/piezas_presupuesto", {
          presupuesto_id: p.presupuesto_id,

          limit: 1000,
          order: "pieza_id",
          direction: "asc",
        });
        piezasPorPresupuesto[p.presupuesto_id] = piezas.rows;
      })
    );

    const detalle = mapearReparacionDetalle(
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      reparacion.row as any,
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      presupuestos.rows as any,
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      piezasPorPresupuesto as any,
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      pedidos.rows as any,
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      historial.rows as any,
      proveedoresPorId
    );

    return NextResponse.json({ ok: true, detalle });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Error desconocido";
    return NextResponse.json({ ok: false, error: message }, { status: 502 });
  }
}

/**
 * Borrado real desde el dashboard — reemplaza el borrado manual que antes
 * se hacía en Sheets. Restringido al superadmin: la ruta de Node ya exige
 * el mismo email en el cuerpo, pero se comprueba también aquí porque el
 * token de la API es compartido por todo el panel, no por usuario.
 */
export async function DELETE(
  req: Request,
  { params }: { params: Promise<{ resguardo: string }> }
) {
  const session = await auth();
  const email = session?.user?.email?.toLowerCase() || "";
  if (!esSuperadmin(email)) return NextResponse.json({ ok: false, error: "No autorizado" }, { status: 403 });

  const { resguardo } = await params;
  const body = (await req.json().catch(() => ({}))) as { motivo?: string };
  const motivo = typeof body.motivo === "string" ? body.motivo.trim() : "";
  if (!motivo) return NextResponse.json({ ok: false, error: "El motivo es obligatorio" }, { status: 400 });

  try {
    const data = await kelatosApiPost<{ ok: boolean; eliminado: boolean; tieneFacturaReal: boolean }>(
      `/v1/reparaciones/${encodeURIComponent(resguardo)}`,
      { usuario: email, motivo },
      "DELETE"
    );

    return NextResponse.json({ ok: true, eliminado: data.eliminado, tieneFacturaReal: data.tieneFacturaReal });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Error desconocido";
    return NextResponse.json({ ok: false, error: message }, { status: 502 });
  }
}

import crypto from "node:crypto";
import { NextResponse } from "next/server";
import { auth } from "@/auth";
import { kelatosApiPost } from "@/lib/kelatos-api";
import { DatosMarcarEntregado } from "@/lib/reparacion-finalizar";

interface RespuestaSalidas {
  ok: boolean;
  reparacion: Record<string, unknown>;
  diasTotales: number;
}

export async function POST(
  req: Request,
  { params }: { params: Promise<{ resguardo: string }> }
) {
  const session = await auth();
  const usuario = session?.user?.email;
  if (!usuario) return NextResponse.json({ ok: false, error: "No autenticado" }, { status: 401 });

  const { resguardo } = await params;
  const body = (await req.json()) as
    | DatosMarcarEntregado
    | { accion: "punto_limpio"; motivo?: string; motivoDetalle?: string; destino?: string }
    | { accion: "cliente_se_lleva"; observaciones: string };

  // Segunda acción del mismo endpoint del backend (enviarAPuntoLimpio del
  // original). El envío desde Reparaciones no manda motivo (se define
  // después, desde la vista "Punto Limpio", que sí lo envía al editar).
  if ("accion" in body && body.accion === "punto_limpio") {
    try {
      const resultado = await kelatosApiPost<RespuestaSalidas>(
        `/v1/reparaciones/${encodeURIComponent(resguardo)}/salidas`,
        {
          requestId: crypto.randomUUID(),
          usuario,
          accion: "punto_limpio",
          datos: {
            motivo: body.motivo || "",
            motivoDetalle: (body.motivoDetalle || "").trim(),
            destino: body.destino || "",
          },
        }
      );
      return NextResponse.json({ ok: true, reparacion: resultado.reparacion, diasTotales: resultado.diasTotales });
    } catch (error) {
      const message = error instanceof Error ? error.message : "Error desconocido";
      return NextResponse.json({ ok: false, error: message }, { status: 502 });
    }
  }

  // Reproduce guardarClienteSeLoLlevo()/apiClienteSeLoLlevo() — solo se
  // reenvía "observaciones" (la fecha del picker no se persiste, ni
  // siquiera en el original: kelatosApiEjecutarSalidaSql solo usa now()).
  if ("accion" in body && body.accion === "cliente_se_lleva") {
    try {

      const resultado = await kelatosApiPost<RespuestaSalidas>(
        `/v1/reparaciones/${encodeURIComponent(resguardo)}/salidas`,
        { requestId: crypto.randomUUID(), usuario, accion: "cliente_se_lleva", datos: { observaciones: body.observaciones.trim() } }
      );
      return NextResponse.json({ ok: true, reparacion: resultado.reparacion, diasTotales: resultado.diasTotales });
    } catch (error) {
      const message = error instanceof Error ? error.message : "Error desconocido";
      return NextResponse.json({ ok: false, error: message }, { status: 502 });
    }
  }

  const datos = body as DatosMarcarEntregado;
  if (!datos.fechaRecogida) {
    return NextResponse.json({ ok: false, error: "La fecha de recogida es obligatoria" }, { status: 400 });
  }

  try {
    const resultado = await kelatosApiPost<RespuestaSalidas>(
      `/v1/reparaciones/${encodeURIComponent(resguardo)}/salidas`,
      {
        requestId: crypto.randomUUID(),
        usuario,
        accion: "marcar_entregado",
        datos: {
          fechaRecogida: datos.fechaRecogida,
          tipoEntrega: datos.tipoEntrega,
          numeroFactura: datos.numeroFactura.trim() || undefined,
          resena: datos.resena,
          observaciones: datos.observaciones.trim(),
        },
