import { NextResponse, type NextRequest } from "next/server";
import { obtenerTodasLasFacturas } from "@/lib/obtener-facturas";
import { calcularDesglose } from "@/lib/reporte-facturas";
import { fechaMadrid } from "@/lib/reportes";

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const fechaDesde = searchParams.get("fechaDesde") || "";
  const fechaHasta = searchParams.get("fechaHasta") || "";
  if (!fechaDesde || !fechaHasta) {
    return NextResponse.json({ ok: false, error: "fechaDesde y fechaHasta son obligatorios" }, { status: 400 });
  }

  try {
    // Ventas ya viene incluida en obtenerTodasLasFacturas() desde la
    // migración 075 (antes se pedía y expandía aparte solo aquí, porque
    // "Facturas de Clientes" no las mostraba todavía).
    const todas = await obtenerTodasLasFacturas();

    // f.fecha es timestamptz (ISO en UTC) para reparación/revisión/etc. —
    // truncar con slice(0,10) se queda con el día UTC, no el de Madrid, y
    // una factura generada pasada la medianoche española (p.ej. 00:21 del
    // día 15 == 22:21 UTC del día 14) quedaba fuera del rango o contada en
    // el día equivocado (mismo bug real que en Facturas de Clientes).
    const enRango = todas.filter((f) => {
      if (!f.fecha) return false;
      const dia = fechaMadrid(f.fecha);
      return !!dia && dia >= fechaDesde && dia <= fechaHasta;
    });
    enRango.sort((a, b) => (a.fecha! < b.fecha! ? -1 : a.fecha! > b.fecha! ? 1 : 0));

    const facturas = enRango.map(calcularDesglose);

    return NextResponse.json({ ok: true, fechaDesde, fechaHasta, facturas });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Error desconocido";
    return NextResponse.json({ ok: false, error: message }, { status: 502 });
  }
}

import { NextResponse } from "next/server";
import { kelatosApiGet } from "@/lib/kelatos-api";
import {
  construirDatosReportes,
  construirAlertas,
  FilaReparacionReporte,
  FilaPresupuestoReporte,
  FilaVentaReporte,
  FilaItemVentaReporte,
} from "@/lib/reportes";

interface RespuestaReparaciones {
  ok: boolean;
  resultados: FilaReparacionReporte[];
  total: number;
}

interface RespuestaGenerica<T> {
  ok: boolean;
  rows: T[];
  count: number;
}

interface RespuestaVentas {
  ok: boolean;
  ventas: FilaVentaReporte[];
  itemsPorVenta: Record<string, FilaItemVentaReporte[]>;
}

// El CRUD genérico tope a 1000 filas por llamada; hoy hay ~2200
// presupuestos, así que se pagina hasta agotar.
const PAGINA = 1000;

async function todosLosPresupuestos(): Promise<FilaPresupuestoReporte[]> {
  const filas: FilaPresupuestoReporte[] = [];
  for (let offset = 0; ; offset += PAGINA) {
    const pagina = await kelatosApiGet<RespuestaGenerica<FilaPresupuestoReporte>>("/v1/presupuestos", {
      limit: PAGINA,
      offset,
    });
    filas.push(...pagina.rows);
    if (pagina.rows.length < PAGINA) break;
    // Cortafuegos: nunca más de 20 páginas (20.000 filas).
    if (offset / PAGINA >= 19) break;
  }
  return filas;
}

export async function GET(req: Request) {
  const { searchParams } = new URL(req.url);
  const umbralDias = Math.max(1, Math.min(365, parseInt(searchParams.get("umbral") || "14", 10) || 14));

  try {
    const [reparaciones, presupuestos, ventas] = await Promise.all([
      // Sin el filtro "finalizadas" el endpoint devuelve TODAS las
      // reparaciones (activas + cerradas), que es lo que necesitan los
      // reportes; porPagina=0 desactiva el límite.
      kelatosApiGet<RespuestaReparaciones>("/v1/lecturas/reparaciones", { porPagina: 0 }),
      todosLosPresupuestos(),
      kelatosApiGet<RespuestaVentas>("/v1/lecturas/ventas", { limit: 5000 }),
    ]);

    const datos = construirDatosReportes(
      reparaciones.resultados,
      presupuestos,
      ventas.ventas,
      ventas.itemsPorVenta || {}
    );
    const alertas = construirAlertas(reparaciones.resultados, presupuestos, umbralDias);

    return NextResponse.json({ ok: true, datos, alertas });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Error desconocido";
    return NextResponse.json({ ok: false, error: message }, { status: 502 });
  }
}

import { NextResponse } from "next/server";
import { auth } from "@/auth";
import { kelatosApiGet } from "@/lib/kelatos-api";
import { esSuperadmin } from "@/lib/superadmin";
import type { ReporteValoraciones } from "@/lib/resenas";

const PARAMETROS = ["q", "atendido", "limit", "offset"];

/** Valoraciones recibidas por el formulario público — solo administradores. */
export async function GET(req: Request) {
  const session = await auth();
  const email = session?.user?.email?.toLowerCase() || "";
  if (!email || (session?.user?.role !== "admin" && !esSuperadmin(email))) {
    return NextResponse.json({ ok: false, error: "No autorizado" }, { status: 403 });
  }
  try {
    const p = new URL(req.url).searchParams;
    const params: Record<string, string> = {};
    for (const k of PARAMETROS) {
      const v = p.get(k);
      if (v) params[k] = v;
    }
    const data = await kelatosApiGet<ReporteValoraciones>("/v1/encuestas-formularios", params);
    return NextResponse.json(data);
  } catch (error) {
    return NextResponse.json({ ok: false, error: error instanceof Error ? error.message : "Error desconocido" }, { status: 502 });
  }
}

import { NextResponse } from "next/server";
import { auth } from "@/auth";
import { kelatosApiPost } from "@/lib/kelatos-api";
import { esSuperadmin } from "@/lib/superadmin";

/** Marca una valoración como atendida (o la reabre). Solo administradores. */
export async function PATCH(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const session = await auth();
  const email = session?.user?.email?.toLowerCase() || "";
  if (!email || (session?.user?.role !== "admin" && !esSuperadmin(email))) {
    return NextResponse.json({ ok: false, error: "No autorizado" }, { status: 403 });
  }
  try {
    const { id } = await params;
    const b = (await req.json()) as { atendido?: unknown; nota?: unknown };
    await kelatosApiPost(`/v1/encuestas-formularios/${encodeURIComponent(id)}`, { atendido: b.atendido, nota: b.nota, usuario: email }, "PATCH");
    return NextResponse.json({ ok: true });
  } catch (error) {
    return NextResponse.json({ ok: false, error: error instanceof Error ? error.message : "Error desconocido" }, { status: 502 });
  }
}

