function formatValorAuditoria(valor: string | null): string {
  if (!valor) return "Ninguno";
  const d = new Date(valor);
  if (!Number.isNaN(d.getTime()) && /^\d{4}-\d{2}-\d{2}T/.test(valor)) return fechaHoraLarga(valor);
  return valor;
}

/** Modal de detalle de un fichaje — inspirado en la vista de hr.attendance
    de Odoo que enseñó el usuario (bloque "Datos legales España RDL 8/2019"
    con tipo/IP/firma + resumen de entrada-salida). No reproducimos el
    chatter/mensajería de Odoo ni "Horas extras" (no tenemos un calendario

    de jornada esperada con el que calcularlas todavía) — solo lo que
    puede respaldarse con datos reales de asistencia.fichajes. Editable
    únicamente si el fichaje no está firmado, igual que ya impone
    actualizarFichajeAdmin en el backend. */
export function DetalleFichajeDialog({
  fichajeId,
  onClose,
  onActualizado,
}: {
  fichajeId: number | null;
  onClose: () => void;
  onActualizado: () => void;
}) {
  const confirmar = useConfirm();
  const [fichaje, setFichaje] = useState<FichajeDetalle | null>(null);
  const [eventos, setEventos] = useState<AuditoriaEvento[]>([]);
  const [cargando, setCargando] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [editando, setEditando] = useState(false);
  const [guardando, setGuardando] = useState(false);
  const [eliminando, setEliminando] = useState(false);
  const [campos, setCampos] = useState({ check_in: "", check_out: "", tipo_fichaje: "", observaciones: "" });

  useEffect(() => {
    if (!fichajeId) { setFichaje(null); setEventos([]); setEditando(false); setError(null); return; }
    setCargando(true);
    setError(null);

    // Antes iban en un solo Promise.all: si la petición de auditoría
    // fallaba (aunque fuera un hipo de red pasajero, nada que ver con el
    // fichaje en sí), el modal entero se quedaba vacío aunque el fichaje
    // sí existiera y hubiera cargado bien. Se desacoplan para que cada
    // una actualice su propio estado de forma independiente.
    fetch(`/api/asistencia/admin/fichajes/${fichajeId}`)
      .then((r) => r.json())
      .then((dFichaje) => {
        if (dFichaje.ok) setFichaje(dFichaje.fichaje);
        else { setError(dFichaje.error || "No se pudo cargar el fichaje"); toast.error(dFichaje.error || "No se pudo cargar el fichaje"); }
      })
      .catch((e) => {
        const msg = e instanceof Error ? e.message : "Error de red al cargar el fichaje";
        setError(msg);
        toast.error(msg);
      })
      .finally(() => setCargando(false));

    fetch(`/api/asistencia/admin/auditoria?fichajeId=${fichajeId}`)
      .then((r) => r.json())

    .then((dAuditoria) => { if (dAuditoria.ok) setEventos(dAuditoria.eventos); })
    .catch(() => {
      // El historial es un extra — si falla, el fichaje sigue siendo
      // usable, solo se queda sin este panel (ver HistorialFichaje: ya
      // muestra "Sin actividad registrada" cuando eventos está vacío).
    });
}, [fichajeId]);

function iniciarEdicion() {
  if (!fichaje) return;
  setCampos({
    check_in: isoAInputLocal(fichaje.check_in),
    check_out: isoAInputLocal(fichaje.check_out),
    tipo_fichaje: fichaje.tipo_fichaje,
    observaciones: fichaje.observaciones || "",
  });
  setEditando(true);
}

async function guardar() {
  if (!fichaje) return;
  setGuardando(true);
  try {
    const cambios = {
      check_in: campos.check_in ? new Date(campos.check_in).toISOString() : null,
      check_out: campos.check_out ? new Date(campos.check_out).toISOString() : null,
      tipo_fichaje: campos.tipo_fichaje,
      observaciones: campos.observaciones,
    };
    const res = await fetch(`/api/asistencia/admin/fichajes/${fichaje.id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(cambios),
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "Error desconocido");
    setFichaje((prev) => (prev ? { ...prev, ...data.fichaje } : data.fichaje));
    setEditando(false);
    toast.success("Fichaje actualizado");
    fetch(`/api/asistencia/admin/auditoria?fichajeId=${fichaje.id}`).then((r) => r.json()).then((d) => { if (d.ok) setEventos(d.eventos); });
    onActualizado();
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error desconocido");
  } finally {
    setGuardando(false);
  }
}

async function eliminar() {
  if (!fichaje) return;
  const ok = await confirmar(
    fichaje.firmado
      ? `¿Eliminar este fichaje FIRMADO de ${fichaje.empleado_nombre}? Es un dato legal (RDL 8/2019) con firma del empleado — no se puede deshacer desde aquí.`

      : `¿Eliminar este fichaje de ${fichaje.empleado_nombre}? Esta acción no se puede deshacer desde aquí.`,
    { titulo: "Eliminar fichaje", detalle: `${fechaHoraLarga(fichaje.check_in)} → ${fechaHoraLarga(fichaje.check_out)} · ${fichaje.tipo_fichaje}` }
  );
  if (!ok) return;
  setEliminando(true);
  try {
    const res = await fetch(`/api/asistencia/admin/fichajes/${fichaje.id}`, { method: "DELETE" });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "Error desconocido");
    toast.success("Fichaje eliminado");
    onActualizado();
    onClose();
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error desconocido");
  } finally {
    setEliminando(false);
  }
}

