    toast.success(`Fichaje #${dataCrear.fichaje.id} creado y solicitud aprobada`);
    onAprobado();
    onClose();
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error desconocido");
  } finally {
    setGuardando(false);
  }
}

