                <TableCell className="text-sm">{fecha(v.fecha_inicio)}</TableCell>
                <TableCell className="text-sm">{fecha(v.fecha_fin)}</TableCell>
                <TableCell className="text-sm">{v.dias_totales}</TableCell>
