];

export interface CanalVista { origen: Origen; titulo: string; descripcion: string }

/** Vista de leads de UN canal (WhatsApp, llamadas o web): cada canal tiene la suya para que no se mezclen. */
export function LeadsCanal(props: CanalVista) {
  // useSearchParams (para abrir un lead concreto desde un enlace) exige un Suspense.
  return (
    <Suspense fallback={<Skeleton className="h-96 w-full" />}>
