}

/** Tarjetas de radio (punto + etiqueta, borde y fondo primary/5 al elegir) — mismo patrón que las tarjetas de plan de la referencia, sobre RadioGroup de shadcn en vez de un botón suelto. */
function CampoOpciones<T extends string>({
  value,
  onChange,
  opciones,
}: {
  value: T | "";
  onChange: (valor: T) => void;
  opciones: readonly T[];
}) {
  return (
    <RadioGroup value={value} onValueChange={(v) => onChange(v as T)} className="flex gap-2">
      {opciones.map((op) => (
        <label
          key={op}
          className={cn(
            "flex flex-1 cursor-pointer items-center justify-center gap-2 rounded-lg border px-3 py-3 text-sm font-medium transition-colors hover:bg-muted/40",
            "has-data-checked:border-primary has-data-checked:bg-primary/5 has-data-checked:text-primary has-data-checked:hover:bg-primary/5"
          )}
        >
          <RadioGroupItem value={op} />
          {op}
        </label>
      ))}
    </RadioGroup>
  );
}

export default function FormularioClientePage() {
  // El código de acceso viaja hasta el envío final (no se descarta tras
  // la pantalla de entrada): /api/formulario-cliente lo consume de forma
  // atómica justo antes de crear la reparación, así el código deja de

// servir en el mismo momento en que se usa — no depende de una
// rotación posterior que podía fallar en silencio y dejar el mismo
// código válido para envíos ilimitados (bug real reportado: 3
// formularios distintos registrados con el mismo código).
const [accesoConcedido, setAccesoConcedido] = useState(false);
const [codigoAcceso, setCodigoAcceso] = useState("");

const [paso, setPaso] = useState(1);
const [datos, setDatos] = useState<DatosFormularioCliente>(datosVacios());
const [errores, setErrores] = useState<Record<string, string>>({});
const [enviando, setEnviando] = useState(false);
// Bloqueo inmediato contra doble clic: el estado `enviando` tarda en reflejarse y dos clics seguidos
// entraban antes de que el botón se desactivara.
const enviandoRef = useRef(false);
const [resultado, setResultado] = useState<{ resguardo: string } | null>(null);
const [errorEnvio, setErrorEnvio] = useState("");
// El código de acceso puede caducar/usarse mientras el cliente rellena
// los 8 pasos (puede llevar varios minutos) — sin esto, el único camino
// era perder todo lo rellenado y volver a empezar desde la pantalla de
// código. Petición del usuario, 2026-10-07: dejar escribir uno nuevo
// aquí mismo y reintentar el mismo envío, sin tocar los datos ya
// completados. El backend solo rechaza esto con 409 (código inválido);
// cualquier otro fallo (red, campos, etc.) no activa este bloque.
const [codigoInvalido, setCodigoInvalido] = useState(false);
const [nuevoCodigo, setNuevoCodigo] = useState("");
const [buscandoCliente, setBuscandoCliente] = useState(false);
const [clienteEncontrado, setClienteEncontrado] = useState(false);
const dniBuscadoRef = useRef("");
// Aviso de campos faltantes — modal en vez de toast, petición del
// usuario, 2026-09-18: en móvil un toast arriba se pierde/es incómodo;
// un modal pequeño con la lista es más claro y no depende de dónde
// esté mirando el cliente en la pantalla.
const [faltantesAbierto, setFaltantesAbierto] = useState(false);
const [faltantes, setFaltantes] = useState<string[]>([]);

// Autoguardado en cada cambio, sin que el cliente tenga que darle a

// nada — se detiene tras enviar con éxito (ya no hace falta el borrador).
useEffect(() => {
  if (!accesoConcedido || resultado) return;
  guardarBorrador({ codigo: codigoAcceso, paso, datos, guardadoEn: Date.now() });
}, [accesoConcedido, resultado, codigoAcceso, paso, datos]);

// Escáner de códigos de barras en el paso «Equipo»: rellena marca y modelo con los datos del código escaneado.
const { aviso: avisoEscaneo } = useEscanerEquipo({
  activo: accesoConcedido && !resultado && paso === 3,
  codigoAcceso,
  onDatos: (d) =>
    setDatos((prev) => {
      const marca = d.marca || prev.marca;
      let modelo = d.modelo || d.nombre || "";
      if (!d.modelo && marca && modelo.toLowerCase().startsWith(marca.toLowerCase())) modelo = modelo.slice(marca.length).trim();
      return { ...prev, marca, modelo: modelo.slice(0, 80), tipoProducto: prev.tipoProducto || tipoDesdeFicha(d.categoria, d.nombre) || "" };
    }),
  onRestaurar: (campo, valor) => {
    if (campo === "marca" || campo === "modelo" || campo === "serie") setDatos((prev) => ({ ...prev, [campo]: valor }));
  },
});

if (!accesoConcedido) {
  return (
    <PantallaCodigoAcceso
      onAcceso={(codigo) => {
        // Mismo código que el del borrador guardado -> es el mismo
        // cliente retomando donde lo dejó. Código distinto (o sin
        // borrador) -> formulario en blanco, para no heredar los datos
        // de otro cliente en un dispositivo compartido.
        const borrador = leerBorrador();
        if (borrador && borrador.codigo === codigo) {
          setDatos(borrador.datos);
          setPaso(borrador.paso);
        }
        setCodigoAcceso(codigo);
        setAccesoConcedido(true);
      }}
    />
  );
}

function actualizar<K extends keyof DatosFormularioCliente>(campo: K, valor: DatosFormularioCliente[K]) {
  setDatos((prev) => ({ ...prev, [campo]: valor }));
}

/**
 * Reproduce apiBuscarClientePorDniPublico() (Apps Script): autocompleta
 * nombre/teléfono/email/dirección con los datos ya registrados de este
 * mismo cliente, si el DNI/CIF ya coincide con uno guardado. Coincidencia

 * exacta — no es un buscador de terceros.
 */
async function buscarClientePorDni(dni: string) {
  const dniLimpio = dni.trim();
  if (dniLimpio.length < 5 || dniLimpio === dniBuscadoRef.current) return;
  dniBuscadoRef.current = dniLimpio;
  setBuscandoCliente(true);
  setClienteEncontrado(false);
  try {
    const res = await fetch(`/api/formulario-cliente/buscar-cliente?dni=${encodeURIComponent(dniLimpio)}`);
    const data = await res.json();
    if (data.ok && data.cliente) {
      const c = data.cliente as { nombre: string; telefono: string; email: string; direccion: string; cp: string; localidad: string; provincia: string };
      // c.telefono viene guardado como "{prefijo} {número}" (ver
      // /api/formulario-cliente route.ts) — solo se separa el prefijo si
      // coincide con uno de los soportados, para no volver a prependerlo
      // sobre el número guardado en el siguiente envío.
      let telPrefijo = datos.telPrefijo;
      let telefonoLocal = datos.telefono;
      if (c.telefono) {
        const partes = c.telefono.trim().split(/\s+/);
        if (partes.length > 1 && PREFIJOS_TELEFONO_VALIDOS.includes(partes[0])) {
          telPrefijo = partes[0];
          telefonoLocal = partes.slice(1).join("").replace(/[^\d]/g, "");
        } else {
          telefonoLocal = c.telefono.replace(/[^\d]/g, "");
        }
        telefonoLocal = normalizarNumeroLocal(telPrefijo, telefonoLocal);
      }
      // c.direccion es la dirección COMPLETA ya compuesta por route.ts:
      // "{viaTipo}, {viaNombre}, {viaNumero}, {cp}, {localidad}, {provincia}"
      // (partes vacías omitidas). Como cp/localidad/provincia ya se
      // conocen por separado, se les quita ese sufijo exacto de
      // c.direccion para recuperar solo "{viaTipo}, {viaNombre},
      // {viaNumero}" y repartirlo — así no hay que adivinar dónde
      // termina la calle, y no se duplica nada en el siguiente envío
      // porque siempre se reconstruye desde el dato guardado, nunca
      // acumulando sobre un valor ya repartido antes.
      let viaTipo = datos.viaTipo;
      let viaNombre = datos.viaNombre;

      let viaNumero = datos.viaNumero;
      if (c.direccion) {
        const sufijo = [c.cp, c.localidad, c.provincia].filter(Boolean).join(", ");
        let calle = c.direccion.trim();
        if (sufijo && calle.endsWith(sufijo)) {
          calle = calle.slice(0, calle.length - sufijo.length).replace(/,\s*$/, "").trim();
        }
        const partes = calle.split(",").map((s) => s.trim()).filter(Boolean);
        const TIPOS_VIA = ["Calle", "Avenida", "Plaza", "Paseo", "Carretera", "Camino", "Urbanización", "Otra"];
        if (partes.length && TIPOS_VIA.includes(partes[0])) {
          viaTipo = partes[0];
          viaNombre = partes[1] || "";
          viaNumero = partes[2] || "";
        } else if (calle) {
          // Dirección antigua sin un tipo de vía reconocible al principio
          // (dato heredado) — se deja como nombre de vía en bruto, sin
          // adivinar el tipo, mejor que perder el dato por completo.
          viaNombre = calle;
        }
      }
      setDatos((prev) => ({
        ...prev,
        nombre: c.nombre || prev.nombre,
        telPrefijo,
        telefono: telefonoLocal,
        email: c.email || prev.email,
        viaTipo,
        viaNombre,
        viaNumero,
        cp: c.cp || prev.cp,
        localidad: c.localidad || prev.localidad,
        provincia: c.provincia || prev.provincia,
      }));
      setClienteEncontrado(true);
    }
  } catch {
    // Best-effort — si falla la búsqueda, el cliente simplemente rellena a mano.
  } finally {
    setBuscandoCliente(false);
  }
}

const esCintas = datos.tipoProducto === "Conversión de cintas";
const esOtro = datos.tipoProducto === "Otro";
const esTicket = datos.tipoDocumento === "Ticket";
const categoria = datos.tipoProducto ? categoriaDeCondiciones(datos.tipoProducto) : null;

function validarPasoActual(): boolean {
  const err: Record<string, string> = {};
  if (paso === 1) {
    if (!datos.tipoDocumento) err.tipoDocumento = "Selecciona si quieres factura o ticket.";
    if (!datos.nombre.trim()) err.nombre = "Introduce tu nombre o empresa.";
    if (!esTicket) {

    if (!datos.dniCif.trim()) err.dniCif = "Introduce tu DNI, NIF, Pasaporte o CIF.";
    if (!datos.viaTipo) err.viaTipo = "Selecciona el tipo de vía.";
    if (!datos.viaNombre.trim()) err.viaNombre = "Introduce el nombre de la vía.";
    if (!datos.cp.trim()) err.cp = "Introduce el código postal.";
    if (!datos.localidad.trim()) err.localidad = "Introduce la localidad.";
    if (!datos.provincia.trim()) err.provincia = "Introduce la provincia.";
  }
}
if (paso === 2) {
  if (!datos.telefono.trim()) err.telefono = "Introduce tu teléfono.";
  if (!datos.noTieneEmail) {
    if (!datos.email.trim() || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(datos.email)) err.email = "Email obligatorio o no válido.";
  }
}
if (paso === 3) {
  if (!datos.tipoProducto) err.tipoProducto = "Selecciona el tipo de producto.";
  if (esOtro && !datos.tipoOtro.trim()) err.tipoOtro = "Describe el tipo de producto.";
  if (!esCintas) {
    if (!datos.marca.trim()) err.marca = "Indica la marca.";
    if (!datos.modelo.trim()) err.modelo = "Indica el modelo.";
  } else if (Object.values(datos.cintas).every((n) => n === 0)) {
    err.cintas = "Indica al menos una cinta.";
  }
}
if (paso === 4 && !esCintas) {
  if (!datos.sintoma.trim()) err.sintoma = "Describe la avería.";
}
if (paso === 5 && !esCintas) {
  if (!datos.enciende) err.enciende = "Selecciona una opción.";
  if (!datos.golpe) err.golpe = "Selecciona una opción.";
  if (!datos.humedad) err.humedad = "Selecciona una opción.";
  if (!datos.reparacionAnterior) err.reparacionAnterior = "Selecciona una opción.";
  if (TIPOS_ORDENADOR.includes(datos.tipoProducto) && !datos.datosImportantes) err.datosImportantes = "Selecciona una opción.";
}
if (paso === 6) {
  if (!datos.aceptaCondiciones) err.aceptaCondiciones = "Debes aceptar las condiciones del servicio.";
}
if (paso === 7) {
  if (datos.fotos.length === 0) err.fotos = "Debes adjuntar al menos una foto del equipo.";
}
if (paso === 8) {
  if (!datos.firmaBase64) err.firma = "Debes firmar el resguardo.";
}

  setErrores(err);
  const etiquetas = etiquetasCamposFaltantes(err);
  if (etiquetas.length > 0) {
    setFaltantes(etiquetas);
    setFaltantesAbierto(true);
  }
  return Object.keys(err).length === 0;
}

function siguiente() {
  if (!validarPasoActual()) return;
  setPaso((p) => Math.min(p + 1, PASOS.length));
}
function anterior() {
  setErrores({});
  setPaso((p) => Math.max(p - 1, 1));
}

async function enviar(codigoOverride?: string) {
  if (enviandoRef.current) return;
  if (!validarPasoActual()) return;
  const codigoAUsar = codigoOverride ?? codigoAcceso;
  enviandoRef.current = true;
  setEnviando(true);
  setErrorEnvio("");
  setCodigoInvalido(false);
  // Tiempo máximo de espera (con margen: lleva fotos y firma): si la red o el servidor no responden, no se queda "Enviando…" indefinidamente.
  const controlador = new AbortController();
  const temporizador = setTimeout(() => controlador.abort(), 90_000);
  try {
    // Red de seguridad además del onBlur del campo — por si el email
    // llega aquí sin pasar por ese blur (autocompletado del navegador,
    // pegado justo antes de enviar, etc.).
    const res = await fetch("/api/formulario-cliente", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ ...datos, email: corregirTypoDominioEmail(datos.email), codigoAcceso: codigoAUsar }),
      signal: controlador.signal,
    });
    // Un cuerpo de petición demasiado grande (fotos sin comprimir) lo
    // puede rechazar la propia plataforma antes de llegar al código de la
    // API, con una respuesta que no es JSON — comprobar el content-type
    // evita el error críptico "Unexpected token... is not valid JSON" y
    // da una pista real de qué pasó.
    const esJson = (res.headers.get("content-type") || "").includes("application/json");
    if (!esJson) {
      throw new Error(
        res.status === 413
          ? "Las fotos adjuntas pesan demasiado. Elimina alguna foto o vuelve a intentarlo con menos fotos."

          : "No se pudo enviar la solicitud (error del servidor). Inténtalo de nuevo en unos minutos."
      );
    }
    const data = await res.json();
    if (!data.ok) {
      // El backend solo devuelve 409 cuando el código de acceso ya no es
      // válido (incorrecto/caducado/usado) — nunca llegó a reservar nada
      // todavía en ese caso, así que reintentar con uno nuevo es seguro.
      if (res.status === 409) setCodigoInvalido(true);
      throw new Error(data.error || "No se pudo registrar la solicitud.");
    }
    if (codigoOverride) setCodigoAcceso(codigoOverride);
    borrarBorrador();
    setResultado({ resguardo: data.resguardo });
  } catch (e) {
    // Solo si falla se vuelve a permitir enviar; tras un envío correcto el bloqueo se mantiene.
    enviandoRef.current = false;
    setErrorEnvio(
      e instanceof Error && e.name === "AbortError"
      ? "Está tardando más de lo normal. Comprueba tu conexión y vuelve a intentarlo (si ya recibió el correo con su resguardo, la solicitud está registrada y no la repita)."
      : e instanceof Error ? e.message : "Error desconocido"
    );
  } finally {
    clearTimeout(temporizador);
    setEnviando(false);
  }
}

