      if (estaSubida(p)) fila.subidos++;

    else if (pendienteDeSubir(p)) fila.pendientes++;
    m.set(k, fila);
  }
  return [...m.entries()].sort((a, b) => b[1].subidos + b[1].pendientes - (a[1].subidos + a[1].pendientes));
}, [deRed]);
