export function NuevaDevolucionDialog({
  open,
  onOpenChange,
  onCreada,
  devolucionExistente,
  desdeTransferencia,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onCreada: () => void;
  /** Si se abre desde una transferencia: se enlaza con ella y se rellenan el cliente y el importe. */
  desdeTransferencia?: { id: number; cliente: string; importe: string; concepto: string } | null;
  /** Si se pasa, el modal edita ese registro (PATCH) en vez de crear uno nuevo — mismo modal que "Nueva devolución", igual que el original. */
  devolucionExistente?: Devolucion | null;
}) {
  const editando = !!devolucionExistente;
  const [nombreCliente, setNombreCliente] = useState("");
  const [email, setEmail] = useState("");
  const [telefono, setTelefono] = useState("");
  const [importe, setImporte] = useState("");
  const [motivo, setMotivo] = useState<string>("");
  const [motivoDetalle, setMotivoDetalle] = useState("");
  const [numeroCuenta, setNumeroCuenta] = useState("");
  const [banco, setBanco] = useState("");
  const [nombreBeneficiario, setNombreBeneficiario] = useState("");
  const [paisSelect, setPaisSelect] = useState("España");
  const [paisOtro, setPaisOtro] = useState("");
  const [comentarios, setComentarios] = useState("");
  const [fotos, setFotos] = useState<{ base64: string; mime: string; nombre: string }[]>([]);
  const [enviando, setEnviando] = useState(false);

  function reiniciar() {
    setNombreCliente(""); setEmail(""); setTelefono(""); setImporte(""); setMotivo(""); setMotivoDetalle("");
    setNumeroCuenta(""); setBanco(""); setNombreBeneficiario(""); setPaisSelect("España"); setPaisOtro("");
    setComentarios(""); setFotos([]);
  }

// Desde una transferencia: cliente e importe ya rellenos y una nota que la identifica.
useEffect(() => {
  if (!open || devolucionExistente || !desdeTransferencia) return;
  setNombreCliente(desdeTransferencia.cliente);
  setImporte(desdeTransferencia.importe);
  setComentarios(`Devolución de la transferencia #${desdeTransferencia.id}${desdeTransferencia.concepto ? ` (${desdeTransferencia.concepto})` : ""}`);
}, [open, devolucionExistente, desdeTransferencia]);

useEffect(() => {
  if (!devolucionExistente) return;
  const d = devolucionExistente;
  setNombreCliente(d.nombre_cliente || "");
  setEmail(d.email || "");
  setTelefono(d.telefono || "");
  setImporte(d.importe ? String(d.importe) : "");
  setNumeroCuenta(d.numero_cuenta || "");
  setBanco(d.banco || "");
  setNombreBeneficiario(d.nombre_beneficiario || "");
  setComentarios("");

  const pais = d.pais || "España";
  if (PAISES.some((p) => p.value === pais)) {
    setPaisSelect(pais);
    setPaisOtro("");
  } else {
    setPaisSelect("Otro");
    setPaisOtro(pais);
  }

  const motivoGuardado = d.motivo || "";
  if ((MOTIVOS as readonly string[]).includes(motivoGuardado)) {
    setMotivo(motivoGuardado);
    setMotivoDetalle(motivoGuardado === "Otro" ? d.motivo_detalle || "" : "");
  } else if (motivoGuardado) {
    setMotivo("Otro");
    setMotivoDetalle(motivoGuardado);
  }
}, [devolucionExistente]);

async function onSeleccionarFotos(e: React.ChangeEvent<HTMLInputElement>) {
  const archivos = Array.from(e.target.files || []);
  e.target.value = "";
  const nuevas = await Promise.all(archivos.map(async (f) => ({ ...(await leerComoBase64(f)), nombre: f.name })));
  setFotos((prev) => [...prev, ...nuevas]);
}

async function guardar() {
  if (!nombreCliente.trim()) return toast.error("El nombre del cliente es obligatorio");
  if (!importe || Number(importe) <= 0) return toast.error("El importe debe ser mayor que 0");
  if (!motivo) return toast.error("Selecciona el motivo de la devolución");
  if (motivo === "Otro" && !motivoDetalle.trim()) return toast.error("Especifica el motivo");

  if (!numeroCuenta.trim()) return toast.error("El número de cuenta es obligatorio");
  if (!nombreBeneficiario.trim()) return toast.error("El nombre del beneficiario es obligatorio");

  const pais = paisSelect === "Otro" ? paisOtro.trim() || "Otro" : paisSelect;
  const payload = {
    nombreCliente, email, telefono, importe: Number(importe), motivo,
    motivoDetalle: motivo === "Otro" ? motivoDetalle.trim() : "",
    numeroCuenta, banco, nombreBeneficiario, pais, comentarios,
    movimientoId: !editando && desdeTransferencia ? desdeTransferencia.id : undefined,
    fotos: fotos.map(({ base64, mime }) => ({ base64, mime })),
  };

  setEnviando(true);
  try {
    const data = editando
      ? await fetch(`/api/devoluciones/${devolucionExistente!.id}`, {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payload),
        }).then((r) => r.json())
      : await fetch("/api/devoluciones", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payload),
        }).then((r) => r.json());
    if (!data.ok) throw new Error(data.error || "Error desconocido");
    toast.success(editando ? `Devolución #${devolucionExistente!.id} actualizada` : `Devolución #${data.id} registrada`);
    reiniciar();
    onOpenChange(false);
    onCreada();
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error desconocido");
  } finally {
    setEnviando(false);
  }
}

return (
  <Dialog open={open} onOpenChange={(o) => { if (!enviando) { if (!o) reiniciar(); onOpenChange(o); } }}>
    <DialogContent className="max-h-[85vh] sm:max-w-4xl overflow-y-auto" showCloseButton={!enviando}>
      <DialogHeader>
        <DialogTitle className="flex items-center gap-2">
          <span className="flex size-8 items-center justify-center rounded-lg bg-violet-500/10 text-violet-600">
            <ArrowLeft2 className="size-4" />
          </span>
          {editando ? `Editar devolución #${devolucionExistente!.id}` : "Nueva devolución"}
        </DialogTitle>

