import NextAuth from "next-auth";
import Google from "next-auth/providers/google";
import Credentials from "next-auth/providers/credentials";
import type { RolUsuario } from "@/types/next-auth";
import { kelatosApiGet, kelatosApiPost } from "@/lib/kelatos-api";
import { esDominioKelatos, EMAILS_ADMIN } from "@/lib/dominio-kelatos";

export { esDominioKelatos };

const REVISAR_EMPLEADO_CADA_MS = 5 * 60 * 1000;

function rolPara(email: string): RolUsuario {
  return EMAILS_ADMIN.has(email.toLowerCase()) ? "admin" : "usuario";
}

/**
 * Empleados de Asistencia (fichajes) — pedido del usuario, 2026-08-28:
 * "prefiero que todos usen Google también en el kiosco". Un técnico de
 * taller que ficha no tiene por qué tener cuenta @kelatos.com, así que se
 * amplía el acceso: cualquier email dado de alta en asistencia.empleados
 * puede iniciar sesión, aunque no sea del dominio — pero solo entra a
 * /asistencia (ver src/proxy.ts), nunca al resto del dashboard.
 */
/** `undefined` = no se pudo consultar (error del API), distinto de `null`
    (consultado: esa cuenta no es empleada) — así un fallo puntual no se
    cachea como "no es empleado". Trae también acceso_completo (migración
    160): así una cuenta marcada así llega al mismo sitio sea cual sea el
    proveedor (Google o Credentials) — no depende de que el campo
    "sobreviva" el paso por el `user` que devuelve authorize(), que no es
    un mecanismo probado en este proyecto para campos propios. */
async function buscarEmpleadoAsistencia(email: string): Promise<{ id: number; accesoCompleto: boolean } | null | undefined> {
  try {
    const data = await kelatosApiGet<{ ok: boolean; empleado: { id: number; acceso_completo?: boolean } | null }>(
      "/v1/asistencia/empleados",
      { email }
    );
    if (!data.empleado) return null;
    return { id: data.empleado.id, accesoCompleto: !!data.empleado.acceso_completo };
  } catch {
    // Si el API interno falla, no se bloquea el login de las cuentas
    // @kelatos.com normales — solo se pierde temporalmente el acceso al
    // kiosco para cuentas ajenas al dominio (best-effort, igual que el
    // resto de llamadas no críticas de esta app).

    return undefined;
  }
}

export const { handlers, auth, signIn, signOut } = NextAuth({
  // Desplegado en Hostinger, no Vercel — sin esto, Auth.js v5 no confía
  // en el host que le manda el proxy y puede generar mal la URL absoluta
  // de redirección en flujos que no pasan por /api/auth/callback (el
  // signOut() de un Server Action, sobre todo), lo que en el navegador
  // se ve como "This page couldn't load" al pulsar "Salir" — el login
  // normal no lo sufría porque ese flujo sí resuelve el host de otra
  // forma. 2026-08-31.
  trustHost: true,
  providers: [
    Google({
      clientId: process.env.GOOGLE_CLIENT_ID,
      clientSecret: process.env.GOOGLE_CLIENT_SECRET,
    }),
    // Alternativa a Google para empleados de Asistencia cuyo email
    // registrado (p.ej. ivan.gonzalez@kelatos.com) no está asociado a una
    // cuenta de Gmail real — pedido del usuario, 2026-08-31. Verifica
    // contra asistencia.empleados.password_hash en el backend; solo da
    // acceso al kiosco (nunca al dominio @kelatos.com por esta vía, ni
    // rol de admin — eso sigue siendo exclusivo de Google).
    Credentials({
      credentials: { email: {}, password: {} },
      async authorize(creds) {
        const email = typeof creds?.email === "string" ? creds.email.trim() : "";
        const password = typeof creds?.password === "string" ? creds.password : "";
        if (!email || !password) return null;
        try {
          // acceso_completo (migración 160) no se lee aquí: jwt() lo consulta
          // por su cuenta vía buscarEmpleadoAsistencia(), igual para Google
          // que para Credentials — un solo sitio que decide, no dos que
          // puedan desincronizarse.
          const data = await kelatosApiPost<{ ok: boolean; empleado?: { id: number; nombre: string; email: string } }>(
            "/v1/asistencia/login",
            { email, password }
          );
          if (!data.ok || !data.empleado) return null;
          return { id: String(data.empleado.id), name: data.empleado.nombre, email: data.empleado.email };
        } catch {
          return null;
        }
      },
    }),
  ],
  callbacks: {
    async signIn({ account, profile }) {

  // El Credentials provider ya validó email+contraseña dentro de
  // authorize() — si llegó hasta aquí, es un empleado activo real.
  if (account?.provider === "credentials") return true;
  const email = profile?.email || "";
  if (esDominioKelatos(email)) return true;
  return ((await buscarEmpleadoAsistencia(email)) ?? null) !== null;
},
async jwt({ token, account }) {
  // "account" solo llega en el login inicial, no en refrescos
  // posteriores del JWT — hay que guardar el dato en el propio token.
  if (account) token.viaCredentials = account.provider === "credentials";
  if (token.email) {
    token.role = rolPara(token.email);
    // Se busca SIEMPRE, no solo para cuentas ajenas al dominio — una
    // cuenta @kelatos.com también puede estar dada de alta como
    // empleado que ficha (p.ej. Daniela), y necesita su propio id de
    // asistencia.empleados para poder fichar ella misma. También trae
    // acceso_completo (migración 160), igual para cualquier proveedor.
    //
    // Pero no en CADA evaluación del token: este callback corre en cada
    // petición autenticada (proxy.ts + cada auth() de una ruta API), y
    // esa consulta traía la lista de empleados del backend una vez por
    // petición — más de la mitad de todo el tráfico a la API medido el
    // 2026-09-21. Se consulta al iniciar sesión y luego como mucho cada
    // 5 minutos (una cuenta recién dada de alta como empleada la ve como
    // tarde en ese plazo; un cambio de acceso_completo tarda lo mismo en
    // notarse). Un fallo del API no se cachea: se conserva el valor
    // anterior y se reintenta en la siguiente petición.
    const ahora = Date.now();
    const vigente =
      !account &&
      token.asistenciaEmpleadoId !== undefined &&
      typeof token.asistenciaComprobadaEn === "number" &&
      ahora - token.asistenciaComprobadaEn < REVISAR_EMPLEADO_CADA_MS;
    if (!vigente) {
      const info = await buscarEmpleadoAsistencia(token.email);
      if (info !== undefined) {

            token.asistenciaEmpleadoId = info ? info.id : null;
            token.accesoCompleto = info ? info.accesoCompleto : false;
            token.asistenciaComprobadaEn = ahora;
          } else if (token.asistenciaEmpleadoId === undefined) {
            token.asistenciaEmpleadoId = null;
            token.accesoCompleto = false;
          }
        }
      }
      return token;
    },
    async session({ session, token }) {
      const email = session.user?.email || "";
      // Login por credenciales nunca cuenta como "del dominio" aunque el
      // email tenga forma @kelatos.com — es la vía pensada solo para
      // empleados sin cuenta de Gmail real, deben quedar confinados al
      // kiosco igual que cualquier cuenta ajena al dominio (ver
      // proxy.ts), SALVO que la cuenta tenga accesoCompleto (petición del
      // usuario, 2026-09-30: soporte@kelatos.com necesita las dos puertas
      // — Google o contraseña — a la misma cuenta con el mismo acceso).
      // Si no tiene alta en asistencia.empleados tampoco entra.
      const permitido = email && (!token.viaCredentials || token.accesoCompleto) && esDominioKelatos(email)
        ? true
        : !!email && token.asistenciaEmpleadoId != null;
      if (!permitido) {
        // No debería ocurrir tras el guard de signIn, pero si ocurriera,
        // no se expone una sesión válida para un email no permitido.
        session.user = undefined as unknown as typeof session.user;
        return session;
      }
      session.user.role = token.role || rolPara(email);
      session.user.asistenciaEmpleadoId = token.asistenciaEmpleadoId ?? null;
      session.user.viaCredentials = !!token.viaCredentials;
      session.user.accesoCompleto = !!token.accesoCompleto;
      return session;
    },
  },
  pages: {
    signIn: "/login",
  },
});

"use client";

import { useEffect, useState } from "react";

type Estado = "pendiente" | "activo" | "rechazado" | "revocado" | null;

/**
 * Pide (o anota) la marca de equipo de este navegador para la cuenta restringida del local. No muestra nada si el equipo está autorizado;
 * si está pendiente, rechazado o revocado, `mostrarAviso` enseña el estado (se usa en la pantalla de «Acceso restringido»).
 * Se hace como mucho una vez por pestaña para no cargar el servidor.
 */
export function SolicitudEquipoLocal({ mostrarAviso = false }: { mostrarAviso?: boolean }) {
  const [estado, setEstado] = useState<Estado>(null);

  useEffect(() => {
    const clave = "kelatos-solicitud-equipo-local";
    try {
      if (!mostrarAviso && window.sessionStorage.getItem(clave)) return;
    } catch { /* sin almacenamiento: se pide igualmente */ }
    fetch("/api/acceso-local/solicitud", { method: "POST" })
      .then((r) => r.json())
      .then((d) => {
        if (d?.ok && d.aplica) setEstado(d.estado as Estado);
        try { window.sessionStorage.setItem(clave, "1"); } catch { /* nada */ }
      })
      .catch(() => {});
  }, [mostrarAviso]);

  if (!mostrarAviso || !estado || estado === "activo") return null;
  const texto =
    estado === "pendiente" ? "Este equipo ha quedado pendiente de autorización. Avisa a un administrador para que lo apruebe y vuelve a abrir el dashboard."
    : estado === "rechazado" ? "Este equipo ha sido rechazado. Habla con un administrador."
    : "La autorización de este equipo se ha retirado. Habla con un administrador.";
  return <p className="mt-3 rounded-md border border-amber-300 bg-amber-50 px-3 py-2 text-sm text-amber-900">{texto}</p>;
}

"use client";

import { useEffect, useState } from "react";
import { TickCircle, Warning2, Refresh2 } from "@/lib/icons";
import { cn } from "@/lib/utils";
import type { ResultadoNifIva } from "@/app/api/facturas-recibidas/validar-iva/route";

/**
 * Aviso (NUNCA bloqueante) al emitir una factura a un cliente: comprueba su NIF/DNI/NIE/CIF antes de emitirla para evitar rectificativas por errores de NIF o de nombre.
 * - NIF español: dígito de control (la letra del DNI/NIE, el control del CIF). Se normaliza a mayúsculas y sin espacios.
 * - NIF-IVA de otro país de la UE (con su prefijo): consulta VIES.
 * - Nombre: avisa si no parece un nombre completo para un particular o si lleva números o símbolos.
 * La comprobación del NIF contra el nombre en la Agencia Tributaria exige un certificado electrónico y no se hace aquí. Si el servicio de validación no responde, solo se informa
 * de que no se pudo comprobar: la factura se puede emitir igualmente.
 */
const UE = new Set(["AT", "BE", "BG", "CY", "CZ", "DE", "DK", "EE", "EL", "FI", "FR", "HR", "HU", "IE", "IT", "LT", "LU", "LV", "MT", "NL", "PL", "PT", "RO", "SE", "SI", "SK", "XI"]);
const compacto = (n: string) => n.toUpperCase().replace(/[\s.\-_/]/g, "");

function avisosNombre(nifCompacto: string, nombre: string): string[] {
  const n = nombre.replace(/\s+/g, " ").trim();
  if (!n) return [];
  const avisos: string[] = [];
  const esParticular = /^(\d{8}[A-Z]|[XYZ]\d{7}[A-Z])$/.test(nifCompacto.replace(/^ES/, ""));
  if (esParticular && n.split(" ").length < 2) avisos.push("Un particular suele necesitar nombre y apellidos: revisa que el nombre esté completo.");
  if (/[\d@#$%^&*=+<>_]/.test(n)) avisos.push("El nombre lleva números o símbolos: revisa que no haya un error de escritura.");
  return avisos;
}

export function AvisoNifCliente({ nif, nombre = "", className }: { nif: string; nombre?: string; className?: string }) {
  const nifC = compacto(nif);
  const prefijo = nifC.slice(0, 2);
  const tipo: "nacional" | "intracomunitaria" = UE.has(prefijo) ? "intracomunitaria" : "nacional";
  const clave = `${tipo}:${nifC}`;

const [respuesta, setRespuesta] = useState<{ clave: string; resultado: ResultadoNifIva | null } | null>(null);

useEffect(() => {
  if (nifC.length < 5) return;
  let vigente = true;
  const t = setTimeout(() => {
    fetch("/api/facturas-recibidas/validar-iva", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ nif: nifC, tipo }) })
      .then((r) => r.json())
      .then((d) => { if (vigente) setRespuesta({ clave, resultado: d.ok ? d.resultado : null }); })
      .catch(() => { if (vigente) setRespuesta({ clave, resultado: null }); });
  }, 600);
  return () => { vigente = false; clearTimeout(t); };
