function numero(v: unknown): number {
  const n = typeof v === "string" ? parseFloat(v) : typeof v === "number" ? v : 0;
  return Number.isFinite(n) ? n : 0;
}

function activo(v: boolean | string | null): boolean {
  return v === true || String(v || "").toUpperCase() === "SI";
}

/** cliente_factura (override "Cliente en la factura", jsonb) pisa el
    cliente registrado del resguardo campo a campo cuando trae un nombre no
    vacío — sin esto, detalle.cliente era SIEMPRE el registrado, ignorando
    cualquier corrección de cliente ya vigente. Eso no era solo cosmético:

    AlquilerModalShell reutiliza este mismo campo como "cliente actual" al
    generar una NUEVA rectificativa, así que cada rectificativa nueva
    pisaba en silencio el override anterior con el cliente del resguardo
    (bug real reportado: tras corregir el cliente dos veces, la foto
    histórica de la primera corrección salió con el cliente del resguardo,
    no con el que realmente tenía esa factura). */
function conOverride(
  base: { nombre: string; dni: string; telefono: string; email: string; direccion: string },
  override: unknown
): { nombre: string; dni: string; telefono: string; email: string; direccion: string } {
  if (!override || typeof override !== "object") return base;
  const o = override as Record<string, unknown>;
  const nombre = typeof o.nombre === "string" ? o.nombre.trim() : "";
  if (!nombre) return base;
  return {
    nombre,
    dni: typeof o.dni === "string" && o.dni.trim() ? o.dni.trim() : base.dni,
    telefono: typeof o.telefono === "string" && o.telefono.trim() ? o.telefono.trim() : base.telefono,
    email: base.email,
    direccion: typeof o.direccion === "string" && o.direccion.trim() ? o.direccion.trim() : base.direccion,
  };
}

export function mapAlquilerFacturaDetalle(row: FilaAlquilerRaw): AlquilerFacturaDetalle {
  return {
    resguardo: row.alquiler_id,
    equipoId: row.equipo_id,
    equipoNombre: "",
    cliente: conOverride(
      {
        nombre: row.cliente_nombre || "",
        dni: row.cliente_dni || "",
        telefono: row.cliente_telefono || "",
        email: row.cliente_email || "",
        direccion: row.cliente_direccion || "",
      },
      row.cliente_factura
    ),
    fechaInicio: row.fecha_inicio,
    fechaFinPrevista: row.fecha_fin_prevista,
    duracion: { meses: row.meses || 0, semanas: row.semanas || 0, dias: row.dias || 0 },
    tarifas: { precioDia: numero(row.precio_dia), precioSemana: numero(row.precio_semana), precioMes: numero(row.precio_mes) },
    numeroFactura: row.numero_factura || "",
    urlFactura: row.url_factura || "",

    totalFactura: totalFacturaPrincipalAlquiler({ cobrado: numero(row.total_cobrado), previsto: numero(row.total_previsto), fianzaBase: numero(row.fianza_cobrada) }),
    formaPago: row.metodo_pago || "",
    estadoFactura: row.estado_factura || "",
    rectificativa: row.numero_factura_rectificativa
      ? { numeroFactura: row.numero_factura_rectificativa, urlFactura: row.url_factura_rectificativa || "", totalFactura: totalRectificativaAlquiler({ guardado: numero(row.total_factura_rectificativa), previsto: numero(row.total_previsto), fianzaBase: numero(row.fianza_cobrada) }) }
      : null,
    motivoRectificativa: row.motivo_rectificativa || "",
    corregida: row.numero_factura_corregida
      ? { numeroFactura: row.numero_factura_corregida, urlFactura: row.url_factura_corregida || "", totalFactura: numero(row.total_factura_corregida) }
      : null,
    inicial: row.numero_factura_inicial
      ? { numeroFactura: row.numero_factura_inicial, urlFactura: row.url_factura_inicial || "", totalFactura: numero(row.total_factura_inicial) }
      : null,
    anterior: row.numero_factura_anterior
      ? { numeroFactura: row.numero_factura_anterior, urlFactura: row.url_factura_anterior || "", totalFactura: numero(row.total_factura_anterior) }
      : null,
    envioActivado: activo(row.envio_activado),
    recogidaActivada: activo(row.recogida_activada),
    fianzaCobrada: numero(row.fianza_cobrada),
    estado: (row.estado || "").toUpperCase(),
    resena: row.resena || "NO",
  };
}

/**
 * Reproduce la lógica de liquidación de devolución de alquiler del
 * original (vistas_equipos.html.html: recalcularDevolucion(),
 * devRecalcularAjuste(), devAjFechaChanged(), _calcTarifario()). Sin esto,
 * el operador tenía que calcular a mano el cargo por retraso, la
 * devolución de fianza y el importe de la nueva factura.
 */

export interface Tarifas {
  precioDia: number;
  precioSemana: number;
  precioMes: number;
}

export interface DuracionTarifario {
  meses: number;
  semanas: number;
  dias: number;
  importe: number;
}

/** Reproduce _calcTarifario(): descompone un número de días en
    meses/semanas/días (30/7/1) y calcula el importe con la tarifa dada. */
export function calcularTarifario(diasAbsolutos: number, tarifas: Tarifas): DuracionTarifario {
  const meses = Math.floor(diasAbsolutos / 30);
  const resto = diasAbsolutos % 30;
  const semanas = Math.floor(resto / 7);
  const dias = resto % 7;
  const importe = meses * tarifas.precioMes + semanas * tarifas.precioSemana + dias * tarifas.precioDia;
  return { meses, semanas, dias, importe };
}

/** Reproduce el cálculo de diasDiff/ajusteImporte de recalcularDevolucion():
    positivo = retraso (se descuenta de la fianza), negativo = adelanto (se
    suma a la fianza a devolver). */
export function calcularAjustePorDias(fechaDevolucion: string, fechaFinPrevista: string | null, tarifas: Tarifas): { diasDiferencia: number; ajusteImporte: number } {
  if (!fechaDevolucion || !fechaFinPrevista) return { diasDiferencia: 0, ajusteImporte: 0 };
  const fDev = fechaLocalDesdeIso(fechaDevolucion);
  const fFin = fechaLocalDesdeIso(fechaFinPrevista);
  if (!fDev || !fFin) return { diasDiferencia: 0, ajusteImporte: 0 };
  const msDia = 1000 * 60 * 60 * 24;
  const diasDiferencia = Math.round((fDev.getTime() - fFin.getTime()) / msDia);
  const { importe } = calcularTarifario(Math.abs(diasDiferencia), tarifas);
  return { diasDiferencia, ajusteImporte: diasDiferencia > 0 ? importe : -importe };
}

function fechaLocalDesdeIso(fecha: string): Date | null {
  const str = fecha.slice(0, 10);
  const [anio, mes, dia] = str.split("-").map(Number);
  if (!anio || !mes || !dia) return null;

  return new Date(anio, mes - 1, dia);
}

export interface LiquidacionPuntual {
  diasDiferencia: number;
  ajusteImporte: number;
  descuentoDanos: number;
  /** Lo que se devuelve al cliente (nunca negativo). */
  fianzaDevolver: number;
  /** Cuando la fianza no cubre retraso + daños, lo que hay que cobrar de más. */
  cobrarExtra: number;
}

/** Reproduce recalcularDevolucion() para la devolución puntual — la fecha
    de devolución está fijada a la fecha fin prevista, así que en la
    práctica diasDiferencia siempre es 0 aquí; se calcula igual por
    fidelidad con el original y por si alguna vez se permite editarla. */
export function calcularLiquidacionPuntual(fechaDevolucion: string, fechaFinPrevista: string | null, fianzaCobrada: number, descuentoDanos: number, tarifas: Tarifas): LiquidacionPuntual {
  const { diasDiferencia, ajusteImporte } = calcularAjustePorDias(fechaDevolucion, fechaFinPrevista, tarifas);
  const fianzaDevolverRaw = fianzaCobrada - ajusteImporte - descuentoDanos;
  return {
    diasDiferencia,
    ajusteImporte,
    descuentoDanos,
    fianzaDevolver: Math.max(0, fianzaDevolverRaw),
    cobrarExtra: fianzaDevolverRaw < 0 ? Math.abs(fianzaDevolverRaw) : 0,
  };
}

export interface DuracionReal {
  meses: number;
  semanas: number;
  dias: number;
}

/** Reproduce devAjFechaChanged(): cuenta los días completos entre el
    inicio del alquiler y la fecha de devolución real, y los descompone
    en meses/semanas/días para recalcular la factura desde cero.
    Diferencia deliberada frente al original (que no tenía mínimo y daba
    0 días/0€ en una devolución el mismo día): decisión explícita del
    usuario — el coste mínimo es 1 día completo aunque el equipo se
    devuelva el mismo día que se alquiló, aunque hayan sido solo minutos.
    Solo se deja en 0 cuando la fecha de devolución es ANTERIOR al inicio
    (dato inválido — confirmarAjuste() ya bloquea el envío en ese caso). */
export function calcularDuracionDesdeFechas(fechaInicio: string, fechaDevolucion: string): DuracionReal {
  const inicio = fechaLocalDesdeIso(fechaInicio);
  const fin = fechaLocalDesdeIso(fechaDevolucion);

  if (!inicio || !fin) return { meses: 0, semanas: 0, dias: 0 };
  const diffDias = Math.round((fin.getTime() - inicio.getTime()) / 86400000);
  const totalDias = diffDias < 0 ? 0 : Math.max(1, diffDias);
  const { meses, semanas, dias } = calcularTarifario(totalDias, { precioDia: 0, precioSemana: 0, precioMes: 0 });
  return { meses, semanas, dias };
}

export interface LiquidacionAjuste {
  subtotal: number;
  iva: number;
  total: number;
}

/** Reproduce devRecalcularAjuste(): subtotal/IVA/total de la NUEVA factura
    con la duración real (sin fianza ni mensajería — ambas ya facturadas
    en la factura inicial). */
export function calcularLiquidacionAjuste(duracion: DuracionReal, tarifas: Tarifas): LiquidacionAjuste {
  const subtotal = duracion.meses * tarifas.precioMes + duracion.semanas * tarifas.precioSemana + duracion.dias * tarifas.precioDia;
  const iva = Math.round(subtotal * 0.21 * 100) / 100;
  const total = Math.round((subtotal + iva) * 100) / 100;
  return { subtotal, iva, total };
}

// ── Tipos del saga de facturación de alquiler ───────────────────────────

export interface LineaFacturaAlquiler {
  descripcion: string;
  cantidad: number;
  precio: number;
  descuento?: number;
}

export interface ClienteFacturaAlquiler {
  nombre: string;
  direccion: string;
  dni: string;
  telefono: string;
}

/** Cuerpo de POST /api/alquileres/:id/facturas — un único requestId por
    "clic lógico"; si el tipo genera dos documentos, el backend deriva los
    dos requestId hijos de forma determinista a partir de este mismo UUID
    (igual que _derivarUuidHijo() en el original), así un reintento con el
    mismo requestId reutiliza los mismos dos números, nunca un tercero. */
export type SolicitudFacturaAlquiler =
  | {
      tipo: "rectificativa_fianza";
      requestId: string;
      cliente: ClienteFacturaAlquiler;
      formaPago: string;
      banco?: string;
      fianza: number;
      equipoNombre: string;
    }
  | {
      /** Reproduce _apiGenerarDevolucionAlquilerModal() del original — el
          tab "Devolución" del modal genérico de Facturas de Clientes
          (#modalFcAcciones), distinto de "Devolver equipo": anula la

        factura completa del alquiler (líneas negativas por meses/
        semanas/días) en vez de solo la fianza. Comparte las MISMAS
        columnas de rectificativa que rectificativa_fianza/ajuste_*
        (igual que en el original — una sola rectificativa "vigente" a
        la vez por alquiler). */
    tipo: "alquiler_rectificativa";
    requestId: string;
    cliente: ClienteFacturaAlquiler;
    formaPago: string;
    banco?: string;
    /** El modal genérico de Facturas de Clientes (TabDevolucionRectificativo,
        compartido con reparaciones) nunca lo manda — el backend lo deriva de
        equipo_id si falta. */
    equipoNombre?: string;
    motivo?: string;
  }
| {
    /** Reproduce _apiGenerarFacturaCorregidaAlquiler() del original —
        "¿Generaste la rectificativa por error?" tras alquiler_rectificativa,
        igual que FaseCorregida en reparaciones. Requiere que ya exista una
        rectificativa vigente (numero_factura_rectificativa); el backend
        reescribe meses/semanas/dias del alquiler a partir de las líneas de
        esta corregida, para que un ajuste de duración posterior parta ya
        de los datos corregidos, no de los originales erróneos. */
    tipo: "alquiler_corregida";
    requestId: string;
    cliente: ClienteFacturaAlquiler;
    formaPago: string;
    banco?: string;
    lineas: LineaFacturaAlquiler[];
    estadoFactura?: string;
    equipoNombre?: string;
  }
| {
    tipo: "ajuste_duracion";
    requestId: string;
    cliente: ClienteFacturaAlquiler;
    formaPago: string;
    banco?: string;
    equipoNombre: string;
    duracionReal: DuracionReal;
    /** Estado de la nueva factura (Cobrada/Pendiente) — si no se manda,
        cae al estado_factura ya guardado en el alquiler. */
    estadoFactura?: string;
  }
| {
    tipo: "alquiler";
    requestId: string;
    cliente: ClienteFacturaAlquiler;
    formaPago: string;
    banco?: string;
    equipoNombre: string;
    estadoFactura: string;

      /** Portes de mensajería, ya calculados por el cliente (12,40€, o 0 si la duración da derecho a envío gratis) — se añaden como línea normal, igual que el original. */
      envioLinea?: number;
      recogidaLinea?: number;
    };

export interface ResultadoFacturaAlquiler {
  numeroFactura?: string;
  url?: string;
  rectificativa?: { numero: string; url: string };
  nueva?: { numero: string; url: string };
  totalNuevo?: number;
  fianzaDevuelta?: number;
}

/**
 * Totales de las facturas de alquiler — un solo sitio para las reglas que
 * usan Facturas de Clientes y el detalle del alquiler.
 *
 * Por qué hace falta: en `alquileres`, `fianza_cobrada` se guarda como BASE
 * sin IVA (165,29 → 200 € con IVA) mientras que la factura sí lleva IVA sobre
 * la fianza. Sumar `total_previsto` (ya con IVA) + `fianza_cobrada` a secas
 * dejaba el total 34,71 € corto (bug real reportado 2026-09-21 con
 * ALQ-0049: la lista decía 189,49 € y la factura real es 224,20 €).
 */

const IVA = 1.21;

function redondear(n: number): number {
  return Math.round(n * 100) / 100;
}

/** Fianza tal como aparece en la factura (base + 21 % de IVA). */
export function fianzaConIva(fianzaBase: number): number {
  return redondear(fianzaBase * IVA);
}

/**
 * Total de la factura principal. `total_cobrado` es el importe real cuando
 * la factura lo dejó registrado (creación del alquiler, ajustes de duración);
 * al devolver el equipo se vuelve a poner a 0, y entonces el total se
 * reconstruye: alquiler previsto (ya con IVA) + fianza con IVA + envío.
 */
export function totalFacturaPrincipalAlquiler(p: { cobrado: number; previsto: number; fianzaBase: number; envio?: number }): number {
  if (p.cobrado > 0) return redondear(p.cobrado);
  return redondear(p.previsto + fianzaConIva(p.fianzaBase) + (p.envio || 0));
}

/**
 * Total (negativo) de una rectificativa de alquiler. La rectificativa de
 * "solo fianza" se guardó durante un tiempo con la fianza SIN IVA
 * (`-fianza_cobrada`, p. ej. -165,29 cuando el documento dice -200,00): se
 * reconoce por ser exactamente `-fianza_cobrada` y se le añade el IVA.
 * Sin importe guardado, se reconstruye como la anulación de la principal.
 */
export function totalRectificativaAlquiler(p: { guardado: number; previsto: number; fianzaBase: number }): number {
  if (p.guardado === 0) return redondear(-(p.previsto + fianzaConIva(p.fianzaBase)));
  if (p.fianzaBase > 0 && Math.abs(p.guardado + p.fianzaBase) < 0.005) return -fianzaConIva(p.fianzaBase);
  return p.guardado;
}

"use client";

/**
 * Capa fina sobre framer-motion, pensada para no engordar el bundle.
 *
 * Dos decisiones deliberadas:
 *
 * 1. Se exporta `m` en vez de `motion`. El componente `motion` arrastra todo
 *    el motor de animación (~34 kB); `m` no trae nada por sí mismo y las
 *    funciones se cargan una sola vez desde el `LazyMotion` de más abajo.
 * 2. Ese `LazyMotion` recibe una función que hace `import()` de
 *    ./animacion-features, de modo que el motor se descarga en un chunk
 *    aparte y solo cuando se monta este proveedor. Pasarle `domAnimation`
 *    importado de forma estática lo metería en el bundle inicial y anularía
 *    la ventaja.
 *
 * `MotionConfig reducedMotion="user"` respeta prefers-reduced-motion sin
 * tener que comprobarlo en cada componente.
 */

import type { ReactNode } from "react";
import { LazyMotion, MotionConfig } from "framer-motion";

/** Carga diferida: el motor viaja en su propio chunk, no en el inicial. */
const cargarFeatures = () => import("./animacion-features").then((mod) => mod.default);

export { m } from "framer-motion";
export { AnimatePresence } from "framer-motion";

/** Duraciones cortas: esto es un panel de trabajo, no una landing. */
export const DURACION = { rapida: 0.15, normal: 0.22 } as const;

/** Entrada estándar de un bloque: aparece subiendo unos píxeles. */
export const entrada = {
  inicial: { opacity: 0, y: 6 },
  visible: { opacity: 1, y: 0 },
};

/**
 * Lista con aparición escalonada. El retardo es pequeño y se corta a los
 * pocos elementos, para que una lista larga no tarde en asentarse.
 */
export const lista = {
  visible: { transition: { staggerChildren: 0.04, delayChildren: 0.02 } },
};

export const elementoLista = {
  inicial: { opacity: 0, y: 4 },
  visible: { opacity: 1, y: 0, transition: { duration: DURACION.rapida } },
};

export function ProveedorAnimacion({ children }: { children: ReactNode }) {
  return (
    <LazyMotion features={cargarFeatures} strict>
      <MotionConfig reducedMotion="user" transition={{ duration: DURACION.normal, ease: "easeOut" }}>
        {children}
      </MotionConfig>
    </LazyMotion>
  );
}

import { NextResponse } from "next/server";
import { auth, esDominioKelatos } from "@/auth";
import { esSuperadmin } from "@/lib/superadmin";
import { kelatosApiGet, kelatosApiPost } from "@/lib/kelatos-api";

/**
 * Helpers compartidos por las rutas /api/asistencia/* — evita repetir la
 * comprobación de sesión (empleado propio vs. manager) en cada route.ts.
 * El employeeId SIEMPRE sale de la sesión, nunca del cliente.
 */

function errorJson(error: unknown) {
  return NextResponse.json({ ok: false, error: error instanceof Error ? error.message : "Error desconocido" }, { status: 502 });
}

export async function kioskGet(segmento: string) {
  const session = await auth();
  const empleadoId = session?.user?.asistenciaEmpleadoId;
  if (!empleadoId) return NextResponse.json({ ok: false, error: "No autenticado" }, { status: 401 });
  try {
    return NextResponse.json(await kelatosApiGet(`/v1/asistencia/kiosk/${empleadoId}/${segmento}`));
  } catch (error) {
    return errorJson(error);
  }
}

export async function kioskPost(segmento: string, body: unknown) {
  const session = await auth();
  const empleadoId = session?.user?.asistenciaEmpleadoId;
  if (!empleadoId) return NextResponse.json({ ok: false, error: "No autenticado" }, { status: 401 });
  try {
    return NextResponse.json(await kelatosApiPost(`/v1/asistencia/kiosk/${empleadoId}/${segmento}`, body));
  } catch (error) {
    return errorJson(error);
  }
}

export async function esManagerSesion(): Promise<boolean> {
  const session = await auth();
  const email = session?.user?.email;
  return !!email && esDominioKelatos(email) && (session?.user?.role === "admin" || esSuperadmin(email));
}

export async function adminGet(path: string, params?: Record<string, string | undefined>) {
  if (!(await esManagerSesion())) return NextResponse.json({ ok: false, error: "No autorizado" }, { status: 403 });
  try {
    return NextResponse.json(await kelatosApiGet(path, params));
  } catch (error) {
    return errorJson(error);
  }
}

export async function adminPost(path: string, extra?: Record<string, unknown>) {
  const session = await auth();

  if (!(await esManagerSesion())) return NextResponse.json({ ok: false, error: "No autorizado" }, { status: 403 });
  try {
    return NextResponse.json(await kelatosApiPost(path, { usuario: session?.user?.email, ...extra }));
  } catch (error) {
    return errorJson(error);
  }
}

