 * ya existentes de Reparaciones (/api/pedidos/cambiar-estado).
 */

/** Plataformas que no emiten factura (compra a un particular): el pedido queda "Sin factura" y no se pide registrarla en el Libro de Compras.
    La plataforma (dónde se pidió) es distinta del proveedor (quien vende). */
export const esPlataformaSinFactura = (plataforma: string) => /wallapop/i.test(plataforma);

/** Enlaces de Drive: un archivo concreto y la carpeta donde se guardan los justificantes de los pedidos. */
export const urlArchivoDrive = (id: string) => `https://drive.google.com/file/d/${id}/view`;
export const urlCarpetaDrive = (id: string) => `https://drive.google.com/drive/folders/${id}`;

export interface CompraFila {
  /** "reparacion" (kelatos_app.pedidos) o "venta" (kelatos_app.items_venta,
      pedido de pieza a un cliente sin reparación) — distingue qué detalle
      abrir al hacer clic en la fila y qué acciones tienen sentido.
      Petición del usuario, 2026-10-12: que los pedidos de Ventas también se
      vean en Compras. */
  origen: "reparacion" | "venta" | "stock";
  pedidoId: string;
  piezaId: string;
  resguardo: string;
  clienteNombre: string;
  equipoModelo: string;
  reparacionEstado: string;
  compradoPor: string;
  numeroPedido: string;
  fechaPedido: string | null;
  fechaEstimada: string | null;
  fechaRecepcion: string | null;
  estado: string;
  /** Lo que dice la página de seguimiento del proveedor/mensajería,
      anotado a mano (sin integración automática con ningún proveedor) —
      "" = sin revisar todavía. Petición del usuario, 2026-10-07: para
      detectar pedidos marcados "Recibido" internamente sin que la

      plataforma confirme la entrega. */
  estadoPlataforma: string;
  recibidoPor: string;
  problemaTipo: string;
  codigoDevolucion: string;
  pedidoRemplazoId: string;
  /** Descripción de la pieza (columna `notas` en kelatos_app.pedidos). */
  descripcion: string;
  enlace: string;
  proveedorId: string;
  proveedorNombre: string;
  proveedorOtro: string;
  /** Justificantes (captura, factura o foto original) guardados en Drive para este pedido. */
  justificantes: { id: string; nombre: string }[];
  /** Plataforma donde se hizo el pedido (Wallapop, AliExpress...); "" si no se anotó. */
  plataforma: string;
  /** Pedido activo cuya fecha estimada ya pasó sin haber llegado (calculado en el servidor). */
  retrasado: boolean;
  /** Precio de compra pagado (null si el pedido no lo tiene registrado — pedidos anteriores a este campo). */
  costo: number | null;
  /** Facturas del Libro de Compras enlazadas a este pedido (migración 119). */
  facturasCount: number;
}

interface FilaCompraSql {
  origen: "reparacion" | "venta" | "stock";
  pedido_id: string;
  pieza_id: string | null;
  resguardo: string | null;
  cliente_nombre: string | null;
  equipo_modelo: string | null;
  reparacion_estado: string | null;
  comprado_por: string | null;
  numero_pedido: string | null;
  fecha_pedido: string | null;
  fecha_estimada: string | null;
  fecha_recepcion: string | null;
  estado: string | null;
  estado_plataforma: string | null;
  recibido_por: string | null;
  problema_tipo: string | null;
  codigo_devolucion: string | null;
  pedido_remplazo_id: string | null;
  notas: string | null;
  enlace: string | null;
  proveedor_id: string | null;
  proveedor_nombre: string | null;
  proveedor_otro: string | null;
  plataforma?: string | null;
  justificantes?: { id: string; nombre: string }[] | null;
  retrasado: boolean | null;
  costo: string | number | null;
  facturas_count?: number | null;
}

export function mapearCompra(row: FilaCompraSql): CompraFila {
  return {
    origen: row.origen === "venta" ? "venta" : row.origen === "stock" ? "stock" : "reparacion",
    pedidoId: row.pedido_id || "",
    piezaId: row.pieza_id || "",
    resguardo: row.resguardo || "",

    clienteNombre: row.cliente_nombre || "",
    equipoModelo: row.equipo_modelo || "",
    reparacionEstado: row.reparacion_estado || "",
    compradoPor: row.comprado_por || "",
    numeroPedido: row.numero_pedido || "",
    fechaPedido: row.fecha_pedido,
    fechaEstimada: row.fecha_estimada,
    fechaRecepcion: row.fecha_recepcion,
    estado: row.estado || "",
    estadoPlataforma: row.estado_plataforma || "",
    recibidoPor: row.recibido_por || "",
    problemaTipo: row.problema_tipo || "",
    codigoDevolucion: row.codigo_devolucion || "",
    pedidoRemplazoId: row.pedido_remplazo_id || "",
    descripcion: row.notas || "",
    enlace: row.enlace || "",
    proveedorId: row.proveedor_id || "",
    proveedorNombre: row.proveedor_nombre || "",
    proveedorOtro: row.proveedor_otro || "",
    plataforma: row.plataforma || "",
    justificantes: Array.isArray(row.justificantes) ? row.justificantes : [],
    // Calculado en el servidor (kelatos_app.pedidos no tiene columna para esto):
    // pedido activo cuya fecha estimada ya pasó sin haber llegado.
    retrasado: row.retrasado === true,
    costo: row.costo === null || row.costo === undefined ? null : Number(row.costo),
    facturasCount: Number(row.facturas_count) || 0,
  };
}

/** "45,50 €" — vacío si el pedido no tiene precio registrado (pedidos anteriores a este campo). */
export function precioLegible(costo: number | null): string {
  return costo === null ? "" : costo.toLocaleString("es-ES", { style: "currency", currency: "EUR" });
}

