function numero(v: unknown): number {
  const n = typeof v === "string" ? parseFloat(v) : typeof v === "number" ? v : 0;
  return Number.isFinite(n) ? n : 0;
}
function fecha(v: unknown): string | null {
  return typeof v === "string" && v ? v : null;
}

export function mapFacturaManualDetalle(row: FilaFacturaManualRaw): FacturaManualDetalle {
  return {
    resguardo: row.id,
    numeroFactura: row.numero_factura || "",
    fechaFactura: fecha(row.fecha_factura),
    cliente: {
      nombre: row.cliente_nombre || "",
      dni: row.cliente_dni || "",
      telefono: row.cliente_telefono || "",
      email: row.cliente_email || "",
      direccion: row.cliente_direccion || "",
      codigo: row.cliente_codigo || "",
    },
    lineasFactura: Array.isArray(row.lineas_factura)
      ? (row.lineas_factura as Array<{ referencia?: string; descripcion?: string; cantidad?: number; precio?: number; descuento?: number }>).map((l) => ({
          referencia: l.referencia || "", descripcion: l.descripcion || "", cantidad: numero(l.cantidad) || 1, precio: numero(l.precio), descuento: numero(l.descuento),
        }))
      : [],
    formaPago: row.forma_pago || "",
    banco: row.banco || "",
    totalFactura: numero(row.total_factura),
    urlFactura: row.url_factura || "",
    estadoFactura: row.estado_factura || "",
    notas: row.notas || "",
    rectificativa: row.num_factura_rectificativa
      ? {
          numeroFactura: row.num_factura_rectificativa,
          urlFactura: row.url_factura_rectificativa || "",
          totalFactura: numero(row.total_factura_rectificativa),
          fechaFactura: fecha(row.fecha_factura_rectificativa),
        }
      : null,
    motivoRectificativa: row.motivo_rectificativa || "",
    corregida: row.numero_factura_corregida

      ? { numeroFactura: row.numero_factura_corregida, urlFactura: row.url_factura_corregida || "", totalFactura: numero(row.total_factura_corregida) }
      : null,
  };
}

/**
 * Tipos compartidos del saga de facturación (preparar → iniciar →
 * generar-pdf → confirmar/fallar en el backend). El requestId lo genera y
 * conserva SIEMPRE el cliente (nunca el servidor en cada llamada) — la
 * numeración fiscal es irreversible y "iniciar" llamado dos veces con
 * requestIds distintos generaría dos números para la misma operación; con
 * el mismo requestId, un reintento tras un fallo de red es seguro gracias
 * a la idempotencia que ya implementa el backend.
 */
export type TipoFactura =
  | "normal"
  | "revision"
  | "mensajeria"
  | "anticipo"
  | "rectificativa"
  | "rectificativa_revision"
  | "corregida"
  | "corregida_revision";

export interface ClienteFactura {
  nombre: string;
  direccion: string;
  dni: string;
  telefono: string;
  codigo?: string;
  email?: string;
}

export interface LineaFactura {
  referencia?: string;
  descripcion: string;
  cantidad: number;
  precio: number;
  descuento?: number;
}

export interface DatosFactura {
  /** Obligatorio en normal/revision/corregida; no aplica a rectificativa. */
  cliente?: ClienteFactura;
  /** Obligatorio en normal/revision; no aplica a rectificativa/corregida. */
  formaPago?: string;
  banco?: string;
  /** Solo cuando formaPago === "transferencia". */
  referencia?: string;
  /** Solo cuando formaPago === "multiforma" — reparto real entre 2 formas de pago (migración 116). */
  formaPagoDesglose?: { forma: string; monto: number; banco?: string; referencia?: string }[];
  lineas: LineaFactura[];
  fianza?: number;
  fianzaDescripcion?: string;
  rectificaDe?: string;
  estadoFactura?: string;
  tipoDocumento?: string;
  /** Solo tipo "normal": permite guardar sin fecha_factura (aún no se cobra). */
  esBorrador?: boolean;
  /** Solo tipo "revision": si true, clienteOverride pisa el cliente_factura_revision ya guardado. */
  clienteOverrideProvisto?: boolean;
  /** Solo tipo "rectificativa"/"rectificativa_revision": motivo obligatorio de la devolución. */
  motivo?: string;
  /** Solo tipo "rectificativa"/"rectificativa_revision": número de la factura que se rectifica. */
  numeroOriginal?: string;

  /** Solo tipo "corregida"/"corregida_revision": número de la factura original que se corrige. */
  numeroFacturaOriginal?: string;
}

export interface ResultadoFactura {
  numeroFactura: string;
  url: string;
  total: number;
  baseImponible: number;
  reparacion: Record<string, unknown>;
  /** Solo presente cuando la llamada incluyó incluirEntrega. */
  diasTotales?: number;
}

export function etiquetaTipo(f: Pick<FacturaCliente, "tipo" | "tipoOriginal" | "esTicketManual" | "esVenta">): string {
  return ETIQUETA_TIPO_FACTURA[tipoVisible(f)];
}

export interface FacturaCliente {
  resguardo: string;
  cliente: string;
  telefono: string;
  email: string;
  dniCif: string;
