  notas?: string;
  datos_extra: Record<string, string>;
}

/** Convierte las filas del CSV (sin cabecera) según el mapeo elegido. */
export function filasParaImportar(cabeceras: string[], filas: string[][], mapeo: DestinoColumna[]): FilaLeadImportar[] {
  return filas.map((celdas) => {
    const lead: FilaLeadImportar = { datos_extra: {} };
    mapeo.forEach((destino, i) => {
      const valor = (celdas[i] ?? "").trim();
      if (!valor || destino === "ignorar") return;

      if (destino === "extra") lead.datos_extra[cabeceras[i] || `columna ${i + 1}`] = valor;
      else lead[destino] = valor;
    });
    return lead;
  });
}

/**
 * Exportación CSV del Libro de Compras (libro de IVA soportado) para el
 * gestor/asesor fiscal — mismo patrón que generarCsvReporte() en
 * reporte-facturas.ts (separador ";", coma decimal, BOM UTF-8 para Excel,
 * fila de totales al final), generado en el navegador desde filas ya
 * cargadas por el cliente.
 */
import { FacturaRecibida, ETIQUETA_CATEGORIA, ETIQUETA_ALMACEN, ETIQUETA_ESTADO_PAGO, ETIQUETA_TIPO_OPERACION, ETIQUETA_ESTADO_IVA } from "./facturas-recibidas";

function numeroCsv(n: number): string {
  return (n || 0).toFixed(2).replace(".", ",");
}

function fechaCsv(iso: string | null): string {
  if (!iso) return "";
  const p = iso.slice(0, 10).split("-");
  return p.length === 3 ? `${p[2]}/${p[1]}/${p[0]}` : "";
}

/** Fecha y hora (Madrid) del registro de la factura, p. ej. 27/10/2026 21:11. */
function fechaRegistroCsv(iso: string | null | undefined): string {
  const d = iso ? new Date(iso) : null;
  return d && !Number.isNaN(d.getTime()) ? d.toLocaleString("es-ES", { timeZone: "Europe/Madrid", dateStyle: "short", timeStyle: "short" }) : "";
}

function celdaCsv(valor: string | number): string {
  const s = String(valor);
  return /[;"\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}

export function generarCsvLibroCompras(
  facturas: FacturaRecibida[],
  opciones: { desde: string; hasta: string; usuario: string }
): string {
  const filas: string[] = [];
  const fila = (...celdas: (string | number)[]) => filas.push(celdas.map(celdaCsv).join(";"));

  fila("LIBRO DE COMPRAS", "Kelatos");
  fila("Período", `${fechaCsv(opciones.desde) || "Todos"} — ${fechaCsv(opciones.hasta) || "todos"}`);
  fila("Generado", new Date().toLocaleString("es-ES"), "Usuario", opciones.usuario);
  filas.push("");

  fila(
    "Fecha expedición", "Fecha de registro", "Nº recepción", "Proveedor", "NIF/CIF", "Nº factura proveedor", "Serie", "Tipo documento",
    "Base imponible", "% IVA", "Cuota IVA soportado", "Cuota IVA deducible", "IVA no deducible", "Total",

    "Categoría", "Almacén", "Estado de pago", "Estado de revisión", "Tipo de operación", "Estado del IVA", "Documento aduanero", "NIF-IVA proveedor", "Moneda", "Importe total en moneda original", "Tipo de cambio (por 1 €)"
  );

  let totBase = 0;
  let totCuotaSoportado = 0;
  let totCuotaDeducible = 0;
  let totTotal = 0;
  for (const f of facturas) {
    fila(
      fechaCsv(f.fechaExpedicion), fechaRegistroCsv(f.creadoEn), f.numeroRecepcion, f.proveedorNombre, f.proveedorDniCif, f.numeroFacturaProveedor, f.serieProveedor,
      f.tipoDocumento || "", numeroCsv(f.baseImponible), f.tipoIva !== null ? numeroCsv(f.tipoIva) : "",
      numeroCsv(f.cuotaIvaSoportado || 0), numeroCsv(f.cuotaIvaDeducible), numeroCsv(f.ivaNoDeducible || 0), numeroCsv(f.importeTotal),
      f.categoria ? ETIQUETA_CATEGORIA[f.categoria] : "", f.almacen ? ETIQUETA_ALMACEN[f.almacen] : "",
      ETIQUETA_ESTADO_PAGO[f.estadoPago], f.estadoRevision === "validada" ? "Validada" : "Pendiente",
      ETIQUETA_TIPO_OPERACION[f.tipoOperacion], ETIQUETA_ESTADO_IVA[f.estadoIva], f.documentoAduanero, f.nifIvaProveedor,
      f.moneda || "EUR", f.moneda && f.moneda !== "EUR" && f.totalMonedaOriginal !== null ? numeroCsv(f.totalMonedaOriginal) : "", f.moneda && f.moneda !== "EUR" && f.tipoCambio ? String(f.tipoCambio).replace(".", ",") : ""
    );
    totBase += f.baseImponible;
    totCuotaSoportado += f.cuotaIvaSoportado || 0;
    totCuotaDeducible += f.cuotaIvaDeducible;
    totTotal += f.importeTotal;
  }

  filas.push("");
  fila(
    "", "", "", "", "", "", "", "TOTALES",
    numeroCsv(totBase), "", numeroCsv(totCuotaSoportado), numeroCsv(totCuotaDeducible), "", numeroCsv(totTotal),
    "", "", "", `${facturas.length} factura${facturas.length !== 1 ? "s" : ""}`, "", "", "", "", "", "", ""
  );

  return `﻿${filas.join("\r\n")}`;
}

