export const TIPOS_CONOCIDOS: string[] = Object.keys(TIPOS).sort((a, b) => TIPOS[a].etiqueta.localeCompare(TIPOS[b].etiqueta, "es"));

/** Tipos que pertenecen a una categoría ("otros" = los que no están en el mapa). */
export function tiposDeCategoria(categoria: CategoriaNotificacion): string[] {

  return Object.keys(TIPOS).filter((t) => TIPOS[t].categoria === categoria);
}

/** Tipos cuya etiqueta legible contiene el texto — para que la búsqueda libre
    también encuentre "Pieza pedida" aunque el código sea estado_pieza_pendiente. */
export function tiposQueCoinciden(texto: string): string[] {
  const q = texto.trim().toLowerCase();
  if (!q) return [];
  return Object.keys(TIPOS).filter((t) => TIPOS[t].etiqueta.toLowerCase().includes(q));
}

export function etiquetaTipo(tipo: string): string {
  return TIPOS[tipo]?.etiqueta || tipo.replace(/_/g, " ");
}

export function categoriaDe(tipo: string): CategoriaNotificacion {
  return TIPOS[tipo]?.categoria || "otros";
}

export const ESTADOS: Record<EstadoNotificacion, { etiqueta: string; clase: string }> = {
  enviado: { etiqueta: "Enviado", clase: "bg-green-500/10 text-green-600" },
  fallido: { etiqueta: "Fallido", clase: "bg-red-500/10 text-red-600" },
  desconocido: { etiqueta: "Sin estado", clase: "bg-muted text-muted-foreground" },
};

export const CANALES: Record<string, string> = { email: "Email", sms: "SMS", interno: "Interno" };

/** Errores técnicos → texto que entiende quien atiende el mostrador. */
export function explicarError(error: string | null): string {
  if (!error) return "";
  if (error === "sin_email_valido") return "El cliente no tiene un email válido: no se pudo enviar nada.";
  if (/NETELIP/i.test(error)) return `Fallo del proveedor de SMS (${error}).`;
  return error;
}

export const MENSAJE_NUMERO_PEDIDO_ENLACE =
  'El Nº de pedido no puede ser un enlace: pon el enlace en el campo Enlace (y en Nº de pedido escribe el número o "No informado")';

export function numeroPedidoEsEnlace(v: string | null | undefined): boolean {
  if (!v) return false;
  return /https?:\/\/|www\.|[a-z0-9-]+\.(com|es|net|org|eu|io|co|de|fr|it|uk|cn|shop|store)\/?/i.test(v);
}

import { kelatosApiGet } from "@/lib/kelatos-api";
import { COLUMNAS_REPARACION_FACTURADA, FacturaCliente, expandirFacturas, expandirFacturaHistorica, expandirAlquiler, expandirManuales, expandirTicketsManuales, expandirVenta } from "@/lib/facturas-cliente";

interface RespuestaReparacionesFacturadas {
  ok: boolean;
  total: number;
  resultados: Parameters<typeof expandirFacturas>[0][];
}

interface RespuestaFacturasHistoricas {
  ok: boolean;
  total: number;
  resultados: Parameters<typeof expandirFacturaHistorica>[0][];
}

interface RespuestaTabla<T> {
  ok: boolean;
  rows: T[];
}

interface FilaClienteLookup {
  codigo: string;
  dni_cif: string | null;
  telefono: string | null;
}

/**
 * Reproduce _lookupCodigo(dni, tel) del original — prioridad DNI, teléfono
 * como respaldo. apiObtenerFacturasClientes() lo aplica SIEMPRE a todas las
 * filas (nunca viene ya en el origen), así que aquí se hace igual, en vez
 * de solo cuando codigoCliente está vacío. Exportada para que
 * /api/reporte-facturas pueda aplicarla también a las ventas (que no pasan
 * por obtenerTodasLasFacturas) sin volver a pedir el listado de clientes.
 */
export async function lookupCodigoCliente(): Promise<(dni: string, telefono: string) => string> {
  const { clientes } = await kelatosApiGet<{ ok: boolean; clientes: FilaClienteLookup[] }>("/v1/lecturas/clientes", { limit: 5000 });
  const porDni = new Map<string, string>();
  const porTelefono = new Map<string, string>();
  for (const c of clientes) {
    const dni = (c.dni_cif || "").trim().toLowerCase();
    const tel = (c.telefono || "").trim();
    if (dni) porDni.set(dni, c.codigo);
    if (tel) porTelefono.set(tel, c.codigo);
  }
  return (dni, telefono) => porDni.get((dni || "").trim().toLowerCase()) || porTelefono.get((telefono || "").trim()) || "";
}

/**
 * Reproduce la base común de apiObtenerFacturasClientes() (pasadas 1-11:
 * reparaciones + alquileres + facturas manuales) — desde la migración 075
 * (ciclo completo de Ver/Devolución/Rectificativo para la Factura real de
 * un pedido) también incluye ventas aquí mismo, no solo en "Reporte de
 * Facturas": petición del usuario, 2026-09-03, poder filtrar/identificar

 * desde "Facturas de Clientes" qué facturas vienen de un pedido de piezas
 * (la columna "Tipo" ya es filtrable de forma genérica, así que basta con
 * que la fila "venta" exista aquí para que aparezca como opción).
 */
export async function obtenerTodasLasFacturas(opciones: { soloEfectivo?: boolean } = {}): Promise<FacturaCliente[]> {
  // soloEfectivo (vista "Efectivo"): del volumen grande —las reparaciones
  // facturadas— solo se baja lo que tiene algún documento en efectivo, y se
  // salta el directorio de clientes y las "Su Referencia" (esa vista no
  // muestra código de cliente ni referencia). Las demás fuentes son pequeñas.
  const soloEfectivo = opciones.soloEfectivo === true;
  const [reparaciones, historicas, alquileres, fechasAlquiler, manuales, ticketsManuales, ventas, lookup, suReferencias] = await Promise.all([
    kelatosApiGet<RespuestaReparacionesFacturadas>("/v1/lecturas/reparaciones-facturadas", {
      columnas: COLUMNAS_REPARACION_FACTURADA.join(","),
      soloEfectivo: soloEfectivo || undefined,
    }),
    kelatosApiGet<RespuestaFacturasHistoricas>("/v1/lecturas/reparaciones-facturas-historicas", { soloEfectivo: soloEfectivo || undefined }),
    kelatosApiGet<RespuestaTabla<Parameters<typeof expandirAlquiler>[0]>>("/v1/alquileres", { limit: 1000 }),
    // kelatos_app.alquileres solo guarda fecha_inicio (una por alquiler,
    // no una por documento) — la fecha real de cada factura de alquiler
    // (principal/rectificativa/corregida/...) vive en
    // factura_operaciones.confirmado_en, indexada por numero_factura. Sin
    // esto, expandirAlquiler usaba fecha_inicio para TODO documento del
    // alquiler, acertando solo por casualidad en el generado el mismo día
    // que empieza el alquiler (bug real, 2026-09-01: ALQ-0043, factura
    // 1-004881 y su rectificativa 3-000238, ambas del 1/9, mostradas como
    // 31/8 en la lista).
    kelatosApiGet<{ ok: boolean; fechas: Record<string, string> }>("/v1/lecturas/alquileres-fechas-factura").then((r) => r.fechas),
    kelatosApiGet<RespuestaTabla<Parameters<typeof expandirManuales>[0][number]>>("/v1/facturas_manuales", { limit: 1000 }),

    kelatosApiGet<RespuestaTabla<Parameters<typeof expandirTicketsManuales>[0][number]>>("/v1/tickets_manuales", { limit: 1000 }),
    kelatosApiGet<RespuestaTabla<Parameters<typeof expandirVenta>[0]>>("/v1/ventas", { limit: 1000 }),
    soloEfectivo ? Promise.resolve((() => "") as (dni: string, telefono: string) => string) : lookupCodigoCliente(),
    // "Su Referencia" (PO del cliente, opcional, nunca en el PDF) — cada
    // fila ya tiene su propio numero_factura/numero_ticket único, así que
    // un único mapa global (por numero) basta para las 11 pasadas de
    // arriba sin tocar cada expandir*() individualmente.
    soloEfectivo
      ? Promise.resolve({} as Record<string, string>)
      : kelatosApiGet<{ ok: boolean; referencias: Record<string, string> }>("/v1/lecturas/documentos-su-referencia").then((r) => r.referencias),
  ]);

  const facturas = [
    ...reparaciones.resultados.flatMap(expandirFacturas),
    ...historicas.resultados.map(expandirFacturaHistorica).filter((f): f is FacturaCliente => f !== null),
    ...alquileres.rows.flatMap((row) => expandirAlquiler(row, fechasAlquiler)),
    ...expandirManuales(manuales.rows),
    ...expandirTicketsManuales(ticketsManuales.rows),
    ...ventas.rows.flatMap(expandirVenta),
  ];

  return facturas.map((f) => ({ ...f, codigoCliente: lookup(f.dniCif, f.telefono), suReferencia: suReferencias[f.numero] || "" }));
}

/**
 * Prueba de esfuerzo (proof-of-work) del formulario público: el navegador
 * busca un valor que, unido al desafío del servidor, dé un SHA-256 con N bits
 * iniciales a cero. Para una persona son fracciones de segundo; para un bot que
 * lance miles de peticiones, cada una cuesta tiempo de CPU. Implementación
 * propia de SHA-256 (crypto.subtle es asíncrono y demasiado lento para esto).
 */

const K = new Uint32Array([
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
  0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
  0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
  0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
]);

const rotr = (x: number, n: number) => (x >>> n) | (x << (32 - n));

export function sha256(msg: Uint8Array): Uint8Array {
  const l = msg.length;
  const bloques = (l + 9 + 63) >> 6;
  const buf = new Uint8Array(bloques * 64);
  buf.set(msg);
  buf[l] = 0x80;
  const dv = new DataView(buf.buffer);
  dv.setUint32(buf.length - 8, Math.floor((l * 8) / 4294967296) >>> 0);
  dv.setUint32(buf.length - 4, (l * 8) >>> 0);
  const H = new Uint32Array([0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19]);
  const w = new Uint32Array(64);
  for (let b = 0; b < bloques; b++) {
    for (let i = 0; i < 16; i++) w[i] = dv.getUint32(b * 64 + i * 4);
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3);
      const s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) | 0;
    }

    let a = H[0], bb = H[1], c = H[2], d = H[3], e = H[4], f = H[5], g = H[6], h = H[7];
    for (let i = 0; i < 64; i++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[i] + w[i]) | 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & bb) ^ (a & c) ^ (bb & c);
      const t2 = (S0 + maj) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = bb; bb = a; a = (t1 + t2) | 0;
    }
    H[0] = (H[0] + a) | 0; H[1] = (H[1] + bb) | 0; H[2] = (H[2] + c) | 0; H[3] = (H[3] + d) | 0;
    H[4] = (H[4] + e) | 0; H[5] = (H[5] + f) | 0; H[6] = (H[6] + g) | 0; H[7] = (H[7] + h) | 0;
  }
  const out = new Uint8Array(32);
  const ov = new DataView(out.buffer);
  for (let i = 0; i < 8; i++) ov.setUint32(i * 4, H[i]);
  return out;
}

export function bitsInicialesACero(hash: Uint8Array): number {
  let n = 0;
  for (const byte of hash) {
    if (byte === 0) {
      n += 8;
      continue;
    }
    n += Math.clz32(byte) - 24;
    break;
  }
  return n;
}

/** Busca la solución sin bloquear la página (cede el hilo cada ~12 ms). */
export async function resolverDesafio(desafio: string, bits: number): Promise<string> {
  const enc = new TextEncoder();
  const prefijo = enc.encode(`${desafio}:`);
  const msg = new Uint8Array(prefijo.length + 12);
  msg.set(prefijo);
  let n = 0;
  for (;;) {
    const hasta = Date.now() + 12;
    do {
      for (let k = 0; k < 256; k++) {
        const solucion = n.toString(36);
        for (let j = 0; j < solucion.length; j++) msg[prefijo.length + j] = solucion.charCodeAt(j);
        if (bitsInicialesACero(sha256(msg.subarray(0, prefijo.length + solucion.length))) >= bits) return solucion;
        n++;
      }
    } while (Date.now() < hasta);
    await new Promise((r) => setTimeout(r, 0));
  }
}

