import { EMPLEADO_CONTENIDO_ID } from "@/lib/contenido-acceso";
import { esSuperadmin } from "@/lib/superadmin";

/** La community manager (empleada de Asistencia 23): en Agentes V2 solo ve «Programar contenido». */
export function esProgramadorContenido(user: { asistenciaEmpleadoId?: number | null } | null | undefined): boolean {
  return !!user && user.asistenciaEmpleadoId === EMPLEADO_CONTENIDO_ID;
}

/** Quién puede entrar a «Programar contenido»: administradores, superadmins y la community manager. */
export function puedeProgramarContenido(user: { role?: string | null; email?: string | null; asistenciaEmpleadoId?: number | null } | null | undefined): boolean {
  if (!user) return false;
  return user.role === "admin" || esSuperadmin(user.email) || esProgramadorContenido(user);
}

/**
 * Qué puede pedir al proxy de Agentes V2 una cuenta que NO es administradora (la community manager): solo lo
 * imprescindible para programar contenido. `metodo` en mayúsculas; `ruta` son los segmentos tras /api/agentes-v2/.
 */
export function rutaPermitidaProgramador(metodo: string, ruta: string[]): boolean {
  const [recurso, sub, id, accion] = ruta;
  if (recurso === "organizations") return metodo === "GET" && ruta.length === 1;
  if (recurso !== "social") return false;
  if (sub === "schedule") {
    if (ruta.length === 2) return metodo === "GET" || metodo === "POST";
    if (ruta.length === 3) return metodo === "PATCH" && /^\d+$/.test(id);
    if (ruta.length === 4) return metodo === "POST" && /^\d+$/.test(id) && (accion === "cancel" || accion === "retry");
    return false;
  }
  // Marca (para precargar los colores) y miniatura de la primera slide de un carrusel ya generado.
  if (sub === "brand") return metodo === "GET" && ruta.length === 2;
  if (sub === "carousels") {
    if (ruta.length === 2) return metodo === "GET" || metodo === "POST";
    if (!/^\d+$/.test(id)) return false;
    // Nunca borrar un carrusel entero, enviarlo a revisión ni publicarlo en Instagram a mano (eso lo hace la programación).
    if (ruta.length === 3) return metodo === "GET" || metodo === "PATCH";
    if (accion === "publish" || accion === "review" || accion === "approve") return false;

    return ["GET", "PATCH", "POST", "PUT", "DELETE"].includes(metodo);
  }
  // Imágenes de la marca: puede verlas y subir nuevas (para las slides), no borrarlas. Descarga de exportaciones, solo lectura.
  if (sub === "assets") return (metodo === "GET" && (ruta.length === 2 || ruta.length === 3)) || (metodo === "POST" && ruta.length === 2);
  if (sub === "exports") return metodo === "GET" && ruta.length === 4 && ruta[3] === "download" && /^\d+$/.test(id);
  return false;
}

/**
 * Fases del progreso de una reparación — port de renderizarTimeline()
 * (Index.html del sistema Apps Script). La lógica de qué fase está
 * completada / en curso se mantiene idéntica; aquí solo se separa del
 * HTML para poder renderizarla con componentes.
 */

import { ReparacionDetalle, esPptoAceptado } from "./reparacion-detalle";

export type EstadoFase = "completada" | "en-curso" | "pendiente" | "no-aplica";

export interface Fase {
  clave: string;
  etiqueta: string;
  estado: EstadoFase;
  /** Fecha asociada, ya formateada, o el texto que ocupa su lugar. */
  detalle: string;
}

/** Estados a partir de los cuales la fase "Presupuesto" ya está superada. */
const TRAS_PRESUPUESTO = [
  "Presupuesto Enviado",
  "Presupuesto Aceptado",
  "Presupuesto Rechazado",
  "Pieza Pendiente",
  "Pieza Entregada",
  "En Reparación",
  "Reparado",
  "No tiene Reparación",
];

/** Ídem para "Respuesta": el cliente ya contestó. */
const TRAS_RESPUESTA = [
  "Presupuesto Aceptado",
  "Presupuesto Rechazado",
  "Pieza Pendiente",
  "Pieza Entregada",
  "En Reparación",
  "Reparado",
  "No tiene Reparación",
];

/** Ídem para "Pieza": ya no se espera ninguna. */
const TRAS_PIEZA = ["Pieza Entregada", "En Reparación", "Reparado", "No tiene Reparación"];

/** Ídem para "Reparación": el técnico ya cerró el equipo. */
const TRAS_REPARACION = ["Reparado", "No tiene Reparación"];

const ENTREGA_CERRADA = ["ENTREGADO", "ENVIO", "RECICLAJE"];

function fase(
  clave: string,
  etiqueta: string,
  completada: boolean,
  enCurso: boolean,
  detalle: string
): Fase {
  return {
    clave,
    etiqueta,
    estado: completada ? "completada" : enCurso ? "en-curso" : "pendiente",
    detalle,
  };
}

export function calcularFases(
  detalle: ReparacionDetalle,
  formatear: (f: string | null) => string
): Fase[] {
  const estado = detalle.estado;
  const primerPresupuesto = detalle.presupuestos[0];
  // El original busca el aceptado y cae al primero: la fecha de respuesta
  // que interesa es la del presupuesto que el cliente contestó.
  const presupuestoRespondido =
    detalle.presupuestos.find((p) => esPptoAceptado(p.estado)) || primerPresupuesto;

  const primerPedido = detalle.pedidos[0];
  // Las conversiones de cintas no pasan por pedido de pieza: se dan por
  // superadas en cuanto el presupuesto está aceptado.
  const esCintas = !!detalle.datosCintas && detalle.datosCintas !== "";

  const faseEntregaCompletada = ENTREGA_CERRADA.includes(detalle.estadoEntrega);

  const fasePieza: Fase = (() => {
    const completada = TRAS_PIEZA.includes(estado) || (esCintas && estado === "Presupuesto Aceptado");
    const enCurso = estado === "Pieza Pendiente";
    if (!completada && !enCurso && !primerPedido) {
      return { clave: "pieza", etiqueta: "Pieza", estado: "no-aplica", detalle: "N/A" };
    }
    return fase(
      "pieza",
      "Pieza",
      completada,
      enCurso,
      primerPedido ? (primerPedido.fechaEstimada ? formatear(primerPedido.fechaEstimada) : "Pendiente") : "N/A"
    );
  })();

  return [
    fase("recepcion", "Recepción", true, false, formatear(detalle.fechaRecepcion)),
    fase(
      "presupuesto",
      "Presupuesto",
      TRAS_PRESUPUESTO.includes(estado),
      estado === "Presupuesto Pendiente",
      primerPresupuesto?.fechaElaboracion ? formatear(primerPresupuesto.fechaElaboracion) : "-"
    ),
    fase(
      "respuesta",
      "Respuesta",
      TRAS_RESPUESTA.includes(estado),
      estado === "Presupuesto Enviado",
      presupuestoRespondido?.fechaRespuesta ? formatear(presupuestoRespondido.fechaRespuesta) : "-"
    ),
    fasePieza,
    fase(
      "reparacion",
      "Reparación",
      TRAS_REPARACION.includes(estado),
      estado === "En Reparación",
      detalle.fechaReparacion ? formatear(detalle.fechaReparacion) : "-"
    ),
    fase(
      "entrega",
      "Entrega",
      faseEntregaCompletada,
      false,
      detalle.fechaEntrega ? formatear(detalle.fechaEntrega) : "-"
    ),
  ];
}

/**
 * Primera línea del síntoma vs. el resto. El formulario de recepción
 * guarda el síntoma y las respuestas del cuestionario (¿Enciende?,
 * ¿Golpe?, Nº Serie…) en un mismo campo separadas por saltos de línea;
 * mostrarSintomaDetalle() las separaba para no dejar un párrafo ilegible.
 */

export function separarSintoma(sintoma: string): { principal: string; adicionales: string[]; extras: string[] } {
  // Las líneas del cuestionario del formulario (¿Enciende?, ¿Golpe?, Nº Serie, ¿Deja cargador?…) son datos de apoyo y van pequeñas;
  // TODO lo demás lo ha escrito el cliente o recepción (varias líneas de problemas, notas añadidas después…) y debe verse igual de claro que el síntoma.
  const esCuestionario = (l: string) => /^(¿[^?]{1,60}\?|N[º°o]\.?\s*(de\s*)?serie\s*:|contraseña\s*\/\s*pin\s*:)/i.test(l);
  const lineas = String(sintoma || "").split(String.fromCharCode(10)).map((l) => l.trim()).filter(Boolean);
  const libres = lineas.filter((l) => !esCuestionario(l));
  return {
    principal: libres[0] || "No especificado",
    adicionales: libres.slice(1),
    extras: lineas.filter(esCuestionario),
  };
}

