    nifIva: row.nif_iva || "",
    direccionFiscal: row.direccion_fiscal || "",
    pais: row.pais || "",
    telefono: row.telefono || "",
    email: row.email || "",
    codigoInterno: row.codigo_interno || "",
    notas: row.notas || "",
    marcas: normalizarMarcas(row.marcas),
    activo: row.activo !== false,
    automatico: /^creado autom[aá]ticamente/i.test(row.notas || ""),
  };
}

