export function estiloEntidad(entidad: string): EstiloEntidad {
  return ESTILO_ENTIDAD[entidad] || ESTILO_ENTIDAD["Reparación"];
}

/** Convierte "presupuesto_enviado" en "Presupuesto enviado" — la propia
    descripción del evento ya es la frase completa; el tipo solo hace de
    subtítulo, así que basta con hacerlo legible, no traducirlo palabra a
    palabra. */
export function humanizarTipo(tipo: string): string {
  const limpio = (tipo || "").replace(/_/g, " ").trim();
  if (!limpio) return "—";
  return limpio.charAt(0).toUpperCase() + limpio.slice(1);
}

const COLORES_AVATAR = [
  "bg-rose-500/15 text-rose-700 dark:text-rose-400",
  "bg-blue-500/15 text-blue-700 dark:text-blue-400",
  "bg-emerald-500/15 text-emerald-700 dark:text-emerald-400",
  "bg-amber-500/15 text-amber-700 dark:text-amber-400",

  "bg-violet-500/15 text-violet-700 dark:text-violet-400",
  "bg-teal-500/15 text-teal-700 dark:text-teal-400",
  "bg-orange-500/15 text-orange-700 dark:text-orange-400",
  "bg-sky-500/15 text-sky-700 dark:text-sky-400",
];

/** Color estable por usuario (mismo nombre → mismo color siempre, sin necesitar backend). */
export function colorAvatar(nombre: string): string {
  let hash = 0;
  for (let i = 0; i < nombre.length; i++) hash = (hash * 31 + nombre.charCodeAt(i)) >>> 0;
  return COLORES_AVATAR[hash % COLORES_AVATAR.length];
}

export function iniciales(nombre: string): string {
  const partes = nombre.trim().split(/\s+/).filter(Boolean);
  if (!partes.length) return "?";
  if (partes.length === 1) return partes[0].slice(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
}

/**
 * "Registro de Acciones" (Index.html) — log general de eventos de todos
 * los módulos (kelatos_app.historial), no solo reparaciones. Reutiliza
 * GET /v1/lecturas/historial, la misma ruta que ya usa historial de
 * reparaciones, pero sin el filtro de tipos por categoría.
 */

export interface EventoRegistro {
  eventoId: string;
  resguardo: string;
  fechaHora: string | null;
  empleadoId: string;
  tipo: string;
  descripcion: string;
  entidad: string;
}

// El original deriva "Entidad" a partir del prefijo del tipo — no es una
// columna propia de kelatos_app.historial. Se reproduce ese criterio aquí;
// cualquier tipo no reconocido cae en "Reparación" (categoría por defecto,
// ya que la mayoría de tipos son eventos de reparación).
const PREFIJOS_ENTIDAD: [string, string][] = [
  ["cliente", "Cliente"],
  ["equipo_", "Equipo"],
  ["alquiler", "Alquiler"],
  ["venta", "Venta"],
  ["item_", "Venta"],
  ["presupuesto", "Presupuesto"],
  ["factura", "Factura"],
  ["pedido", "Pedido"],
];

function derivarEntidad(tipo: string): string {
  const t = tipo.toLowerCase();
  for (const [prefijo, entidad] of PREFIJOS_ENTIDAD) {
    if (t.startsWith(prefijo)) return entidad;
  }
  return "Reparación";
}

