export function mapearStockPieza(row: FilaStockPiezaSql): StockPieza {
  const precioCliente = numero(row.precio_cliente);
  const manoObra = numero(row.mano_obra);
  const stockDisponible = numero(row.stock_disponible);
  const stockMinimo = numero(row.stock_minimo);
  return {
    referencia: row.referencia,
    nombre: row.nombre || "",
    nombreInternoProveedor: row.nombre_interno_proveedor || "",
    nombresInternoProveedorAlt: Array.isArray(row.nombres_interno_proveedor_alt) ? row.nombres_interno_proveedor_alt : [],
    codigosInternoProveedorAlt: alinearCodigos(row.nombres_interno_proveedor_alt, row.codigos_interno_proveedor_alt),
    codigoProveedor: row.codigo_proveedor || "",
    idPedidoProveedor: row.id_pedido_proveedor || "",
    descripcion: row.descripcion || "",
    costeInterno: numero(row.coste_interno),
    precioCliente,
    manoObra,
    totalCliente: (precioCliente + manoObra) * 1.21,
    stockDisponible,
    stockReservado: numero(row.stock_reservado),
    stockMinimo,
    proveedor: row.proveedor || "",
    categoria: row.categoria || "",
    activo: row.activo !== false,
    stockBajo: stockMinimo > 0 && stockDisponible < stockMinimo,
  };
}

/**
 * "Su Referencia" — campo opcional de texto libre (PO/referencia propia
 * del cliente) que se puede escribir al generar cualquier factura o
 * ticket. Nunca viaja al PDF; solo alimenta la columna "Su Ref." de
 * Facturas de Clientes (kelatos_app.documentos_su_referencia, migración
 * 069). Se guarda en una llamada aparte DESPUÉS de que el documento ya
 * tenga numero_factura/numero_ticket asignado — nunca bloquea ni puede
 * hacer fallar la generación del documento en sí, por eso el error se
 * traga aquí (best-effort) en vez de propagarse al flujo de generación.
 */
export async function guardarSuReferencia(numero: string, suReferencia: string): Promise<void> {
  if (!numero || !suReferencia.trim()) return;
  try {
    await fetch("/api/documentos/su-referencia", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ numero, suReferencia: suReferencia.trim() }),
    });
  } catch {
    // best-effort — un fallo aquí no debe deshacer ni bloquear la factura/ticket ya generado
  }
}

