/**
 * Verificación del token firmado del formulario público de entrega de
 * "Pedidos de piezas" (Ventas) — mismo diseño que token-recogida.ts
 * (reparaciones), payload "ventaId.entrega_venta.expiryMillis" en
 * base64url + "." + HMAC-SHA256 hex del payload en texto plano, firmado
 * con el mismo secreto compartido KELATOS_RECOGIDA_SIGNING_SECRET. El
 * literal "entrega_venta" en el payload (distinto de "recogida") impide
 * que un enlace de recogida de reparación se reutilice para confirmar la
 * entrega de una venta, o viceversa.
 */

import crypto from "node:crypto";

export function generarTokenEntregaVenta(ventaId: string, diasValidez = 30): string {
  const secreto = process.env.KELATOS_RECOGIDA_SIGNING_SECRET;
  if (!secreto) throw new Error("KELATOS_RECOGIDA_SIGNING_SECRET no está configurado");

  const expiry = Date.now() + diasValidez * 24 * 60 * 60 * 1000;
  const payload = `${ventaId}.entrega_venta.${expiry}`;
  const firmaHex = crypto.createHmac("sha256", secreto).update(payload).digest("hex");
  return Buffer.from(payload, "utf8").toString("base64url") + "." + firmaHex;
}

export function validarTokenEntregaVenta(ventaId: string, token: string): { valido: boolean; error?: string } {
  const secreto = process.env.KELATOS_RECOGIDA_SIGNING_SECRET;
  if (!secreto) return { valido: false, error: "Firma de enlaces no configurada" };

  const partes = String(token || "").split(".");
  if (partes.length !== 2) return { valido: false, error: "Token con formato inválido" };

  let payloadStr: string;
  try {
    payloadStr = Buffer.from(partes[0], "base64url").toString("utf8");
  } catch {
    return { valido: false, error: "Token con formato inválido" };
  }

  const firmaEsperada = crypto.createHmac("sha256", secreto).update(payloadStr).digest("hex");
  if (firmaEsperada !== partes[1]) return { valido: false, error: "Firma de token inválida" };

  const campos = payloadStr.split(".");
  if (campos[0] !== String(ventaId) || campos[1] !== "entrega_venta") {
    return { valido: false, error: "Token no corresponde a este pedido" };
  }
  if (Date.now() > Number(campos[2])) return { valido: false, error: "Token expirado" };

  return { valido: true };
}

/**
 * Verificación del token firmado de FormularioRecogida — replica
 * EXACTAMENTE _validarTokenRecogidaFirmado (backend/Code.js): payload
 * "resguardo.recogida.expiryMillis" en base64url + "." + HMAC-SHA256 hex
 * del payload en texto plano, firmado con KELATOS_RECOGIDA_SIGNING_SECRET
 * (mismo nombre de Script Property en Apps Script — secreto compartido,
 * generado nuevo para esta migración, nunca activado aquí en Apps Script
 * por mí, solo copiado por el usuario).
 */

import crypto from "node:crypto";

// Replica _generarTokenRecogidaFirmado (backend/Code.js) — mismo formato
// de payload y firma que validarTokenRecogida verifica. Generado y
// verificado íntegramente dentro de Next.js: no depende de Apps Script.
export function generarTokenRecogida(resguardo: string, diasValidez = 30): string {
  const secreto = process.env.KELATOS_RECOGIDA_SIGNING_SECRET;
  if (!secreto) throw new Error("KELATOS_RECOGIDA_SIGNING_SECRET no está configurado");

  const expiry = Date.now() + diasValidez * 24 * 60 * 60 * 1000;
  const payload = `${resguardo}.recogida.${expiry}`;
  const firmaHex = crypto.createHmac("sha256", secreto).update(payload).digest("hex");
  return Buffer.from(payload, "utf8").toString("base64url") + "." + firmaHex;
}

export function validarTokenRecogida(resguardo: string, token: string): { valido: boolean; error?: string } {
  const secreto = process.env.KELATOS_RECOGIDA_SIGNING_SECRET;
  if (!secreto) return { valido: false, error: "Firma de enlaces no configurada" };

  const partes = String(token || "").split(".");
  if (partes.length !== 2) return { valido: false, error: "Token con formato inválido" };

  let payloadStr: string;
  try {
    payloadStr = Buffer.from(partes[0], "base64url").toString("utf8");
  } catch {
    return { valido: false, error: "Token con formato inválido" };
  }

  const firmaEsperada = crypto.createHmac("sha256", secreto).update(payloadStr).digest("hex");
  if (firmaEsperada !== partes[1]) return { valido: false, error: "Firma de token inválida" };

  const campos = payloadStr.split(".");
  if (campos[0] !== String(resguardo) || campos[1] !== "recogida") {

    return { valido: false, error: "Token no corresponde a este resguardo" };
  }
  if (Date.now() > Number(campos[2])) return { valido: false, error: "Token expirado" };

  return { valido: true };
}

/**
 * Vista "TPV" (Facturación): parte diario de lo facturado por cada método
 * de pago (tarjeta, tarjeta virtual, bizum, transferencia, efectivo),
 * para que el personal de tienda lo cuadre contra lo que calcula el
 * sistema a partir de facturas/tickets. Aquí no se lista un libro de
 * movimientos: se agrega directamente un total por día+método a
 * comparar. "efectivo" se añadió el 2026-10-12 (fusión con lo que antes
 * era "Tarjetas") para que el desglose de un día muestre TODOS los tipos
 * de pago juntos — no sustituye ni toca la vista "Efectivo"
 * (lib/efectivo.ts), que sigue siendo el libro de movimientos/retiradas
 * de caja; esto es solo una fila más de reconciliación aquí. Petición del
 * usuario, 2026-10-09/12.
 */
import { esDevolucionNegativa, FacturaCliente, ETIQUETA_TIPO_FACTURA, estadoFacturaDerivado, montoConIva } from "@/lib/facturas-cliente";
import { BANCOS } from "@/lib/bancos";

export const METODOS_TPV = [
  { value: "tarjeta", label: "Tarjeta bancaria" },
  { value: "tarjeta_virtual", label: "Tarjeta virtual" },
  { value: "bizum", label: "Bizum" },
  { value: "paypal", label: "PayPal" },
  { value: "transferencia", label: "Transferencia bancaria" },
  { value: "efectivo", label: "Efectivo" },
] as const;

export type MetodoTpv = (typeof METODOS_TPV)[number]["value"];

const METODOS_TPV_VALORES: readonly string[] = METODOS_TPV.map((m) => m.value);

export function etiquetaMetodoTpv(metodo: string): string {
  return METODOS_TPV.find((m) => m.value === metodo)?.label || metodo;
}

export interface TpvImporteApi {
  id: number | string;
  fecha: string;
  metodo: string;
  importe_declarado: number;
  notas: string;
  usuario: string;
  creado_en: string;
  actualizado_en: string;
  actualizado_por: string | null;
}

export interface TpvFotoApi {
