/** Segundos de Unix de «mañana a las 9:00» (hora de Madrid) — la opción habitual de «Posponer». */
export function mananaALas9(): number {
  const ahora = new Date();
  const partes = new Intl.DateTimeFormat("en-CA", { timeZone: "Europe/Madrid", year: "numeric", month: "2-digit", day: "2-digit" }).format(new Date(ahora.getTime() + 24 * 3600 * 1000));
  const probe = new Date(`${partes}T09:00:00Z`);
  const offsetMin = (new Date(probe.toLocaleString("en-US", { timeZone: "Europe/Madrid" })).getTime() - new Date(probe.toLocaleString("en-US", { timeZone: "UTC" })).getTime()) / 60000;
  return Math.floor((probe.getTime() - offsetMin * 60000) / 1000);
}

export function horaWa(ts: number): string {
  if (!ts) return "";
  const d = new Date(ts * 1000);
  const opts: Intl.DateTimeFormatOptions = { timeZone: "Europe/Madrid" };
  const hoy = new Date();
  const mismoDia = d.toLocaleDateString("es-ES", opts) === hoy.toLocaleDateString("es-ES", opts);
  return mismoDia
    ? d.toLocaleTimeString("es-ES", { ...opts, hour: "2-digit", minute: "2-digit", hour12: false })
    : d.toLocaleDateString("es-ES", { ...opts, day: "2-digit", month: "short" });
}

export function horaCompletaWa(ts: number): string {
  if (!ts) return "";
  return new Date(ts * 1000).toLocaleString("es-ES", { timeZone: "Europe/Madrid", day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit" });
}

export function inicialesWa(nombre: string): string {
  const p = nombre.trim().split(/\s+/).filter(Boolean);
  return ((p[0]?.[0] || "?") + (p.length > 1 ? p[p.length - 1][0] : "")).toUpperCase();
}

import { auth, esDominioKelatos } from "@/auth";
import { NextResponse } from "next/server";
import { esSuperadmin, puedeVerTransferencias, puedeVerEfectivoSoloLectura, aterrizaEnFichaje, COOKIE_IR_DASHBOARD } from "@/lib/superadmin";
import { puedeVerEquiposEntregados } from "@/lib/equipos-entregados";
import { esProgramadorContenido } from "@/lib/programador-contenido";
import { comprobarAccesoLocal } from "@/lib/acceso-local";
import { esUsuarioRedes, esRutaRedesSociales } from "@/lib/redes-sociales-acceso";

/**
 * Protege todas las rutas salvo /login y /api/auth/* — equivalente a la
 * comprobación de Session.getActiveUser() al principio de doGet() en
 * Code.js. La restricción de dominio en sí (@kelatos.com) ya se aplica
 * en el callback signIn de src/auth.ts; aquí solo se exige que exista
 * una sesión válida.
 */
export default auth(async (req) => {
  const isAuthed = !!req.auth?.user;
  if (!isAuthed) {
    const loginUrl = new URL("/login", req.nextUrl.origin);
    return NextResponse.redirect(loginUrl);
  }
  // Acceso restringido al local: solo afecta a UNA cuenta configurada en el backend (hoy soporte@kelatos.com); administradores y
  // superadmins quedan siempre exentos. Ver src/lib/acceso-local.ts (modo «observar» por defecto: no bloquea, solo anota la IP).
  const bloqueoLocal = await comprobarAccesoLocal(
    req, req.auth?.user?.email, req.auth?.user?.role === "admin" || esSuperadmin(req.auth?.user?.email)
  );
  if (bloqueoLocal) return bloqueoLocal;
  // Configuración (lista de usuarios) es solo para el Administrador.
  if (req.nextUrl.pathname.startsWith("/configuracion") && req.auth?.user?.role !== "admin") {
    return NextResponse.redirect(new URL("/", req.nextUrl.origin));
  }
  // Contabilidad (Importaciones / DUA…) — solo administradores; el menú ya la
  // oculta al resto (navegacion.tsx) y aquí se cierra también la ruta directa.
  // Excepción estrecha: cuentas con puedeVerEfectivoSoloLectura pueden entrar
  // SOLO a /contabilidad/efectivo (página) y /api/contabilidad/efectivo* (la
  // propia ruta ya exige además GET para esas cuentas) — ninguna otra
  // sección de Contabilidad. Petición del usuario, 2026-10-05.
  if (

  (["/importaciones", "/api/importaciones", "/reporte-resenas", "/api/resenas", "/contabilidad", "/api/contabilidad"].some((r) => req.nextUrl.pathname.startsWith(r))) &&
  req.auth?.user?.role !== "admin" &&
  !esSuperadmin(req.auth?.user?.email) &&
  !(
    puedeVerEfectivoSoloLectura(req.auth?.user?.email) &&
    (req.nextUrl.pathname.startsWith("/contabilidad/efectivo") || req.nextUrl.pathname.startsWith("/api/contabilidad/efectivo"))
  )
) {
  return NextResponse.redirect(new URL("/", req.nextUrl.origin));
}
// Equipos entregados (Reparaciones) — solo administradores, superadmins y la cuenta de empleados (soporte).
if (
  (req.nextUrl.pathname.startsWith("/equipos-entregados") || req.nextUrl.pathname.startsWith("/api/equipos-entregados")) &&
  !puedeVerEquiposEntregados(req.auth?.user)
) {
  return req.nextUrl.pathname.startsWith("/api/")
    ? NextResponse.json({ ok: false, error: "No autorizado" }, { status: 403 })
    : NextResponse.redirect(new URL("/", req.nextUrl.origin));
}
// Dashboard de Transferencias — vista aparte. Superadmins entran por
// serlo; puedeVerTransferencias además admite cuentas con acceso SOLO a
// este módulo, sin el resto de poderes de superadmin.
if (req.nextUrl.pathname.startsWith("/transferencias") && !puedeVerTransferencias(req.auth?.user?.email)) {
  return NextResponse.redirect(new URL("/", req.nextUrl.origin));
}
// Dashboard de Webs Kelatos — vista aparte, solo administradores
// (mismo criterio que nav-user.tsx/webs-kelatos/layout.tsx — defensa en
// profundidad, igual patrón que Transferencias).
if (
  req.nextUrl.pathname.startsWith("/webs-kelatos") &&
  req.auth?.user?.role !== "admin" &&
  !esSuperadmin(req.auth?.user?.email)
) {
  return NextResponse.redirect(new URL("/", req.nextUrl.origin));
}
// Dashboard de Agentes IA — vista aparte, solo administradores (mismo
// criterio que Webs Kelatos — defensa en profundidad, ver también
// agentes/layout.tsx).
// Excepción: la community manager (empleada 23) entra SOLO a /agentes-v2/programar (Programar contenido); su
// layout reducido y el proxy /api/agentes-v2 (allowlist) acotan lo demás.

const enProgramarContenido = ["/agentes-v2/programar", "/agentes-v2/carruseles"].some((r) => req.nextUrl.pathname === r || req.nextUrl.pathname.startsWith(`${r}/`));
const programadorPermitido = esProgramadorContenido(req.auth?.user) && enProgramarContenido;
// Carlo, Cielo, Gean y Jeannie entran SOLO a /agentes/redes (analítica de Instagram); ninguna otra pantalla de Agentes.
const redesPermitido = esUsuarioRedes(req.auth?.user) && esRutaRedesSociales(req.nextUrl.pathname);
if (
  req.nextUrl.pathname.startsWith("/agentes") &&
  req.auth?.user?.role !== "admin" &&
  !esSuperadmin(req.auth?.user?.email) &&
  !programadorPermitido &&
  !redesPermitido
) {
  return NextResponse.redirect(new URL("/", req.nextUrl.origin));
}
// Agentes operativos (auditoría de seguridad, SEO de vídeo, oportunidades de PR): solo superadmins (viven en Gestión MAILS).
// /agentes/redes (analítica de Instagram de siempre) y /agentes-v2 conservan su acceso.
if (/^\/agentes(\/|$)/.test(req.nextUrl.pathname) && !req.nextUrl.pathname.startsWith("/agentes/redes") && !esSuperadmin(req.auth?.user?.email)) {
  return NextResponse.redirect(new URL("/", req.nextUrl.origin));
}
// Gestión MAILS — vista aparte, solo administradores (mismo criterio que
// Agentes; los buzones guardan credenciales de correo), salvo cuentas
// accesoCompleto (petición del usuario, 2026-09-30: soporte@kelatos.com
// ve Gestión MAILS, pero con una vista restringida — ver
// GestionMailsSidebar/Centro de mails — que esta comprobación no decide,
// solo deja pasar la ruta). Las rutas de API repiten la comprobación
// (src/lib/mails-auth.ts), que también necesita la excepción.
if (
  (req.nextUrl.pathname.startsWith("/mails") || req.nextUrl.pathname.startsWith("/api/mails") || req.nextUrl.pathname.startsWith("/whatsapp") || req.nextUrl.pathname.startsWith("/api/whatsapp")) &&
  req.auth?.user?.role !== "admin" &&
  !esSuperadmin(req.auth?.user?.email) &&
  !req.auth?.user?.accesoCompleto
) {
  return NextResponse.redirect(new URL("/", req.nextUrl.origin));
}
// Tareas — oculto para cuentas accesoCompleto (petición del usuario,

// 2026-09-30: soporte@kelatos.com no debe tener este módulo). El menú ya
// lo oculta (nav-user.tsx); aquí se cierra también la ruta directa, mismo
// patrón de defensa en profundidad que el resto de módulos.
if (
  (req.nextUrl.pathname.startsWith("/tareas") || req.nextUrl.pathname.startsWith("/api/tareas")) &&
  req.auth?.user?.accesoCompleto
) {
  return NextResponse.redirect(new URL("/", req.nextUrl.origin));
}
// Dentro de Gestión MAILS, una cuenta accesoCompleto solo ve "Centro de
// mails" (/mails/bandeja) — Buzones/Leads/Direcciones inválidas/Tipos de
// correo quedan fuera, tanto la página como su API (ninguna la usa
// Centro de mails). Petición del usuario, 2026-09-30.
if (
  req.auth?.user?.accesoCompleto &&
  ["/mails/buzones", "/mails/leads", "/mails/direcciones", "/mails/tipos", "/api/mails/leads", "/api/mails/direcciones", "/api/mails/tipos"].some(
    (r) => req.nextUrl.pathname.startsWith(r)
  )
) {
  return req.nextUrl.pathname.startsWith("/api/")
    ? NextResponse.json({ ok: false, error: "No autorizado" }, { status: 403 })
    : NextResponse.redirect(new URL("/mails/bandeja", req.nextUrl.origin));
}
// Dashboard de Asistencia (fichajes) — un empleado que ficha puede no
// tener cuenta @kelatos.com (login ampliado en src/auth.ts); esa cuenta
// solo puede entrar a /asistencia/kiosk (y a sus propias llamadas API
// en /api/asistencia/kiosk/*), nunca al resto del dashboard. Sin el
// "/api/asistencia" en esta comprobación, cada fetch() del kiosco
// (fichar, mis-fichajes, rgpd...) rebotaba en 307 en vez de responder
// JSON — bug real encontrado verificando con una sesión simulada,
// 2026-08-28. El panel /asistencia/admin sigue restringido a admins.
const enAsistencia = req.nextUrl.pathname.startsWith("/asistencia") || req.nextUrl.pathname.startsWith("/api/asistencia");
const enAsistenciaAdmin = req.nextUrl.pathname.startsWith("/asistencia/admin") || req.nextUrl.pathname.startsWith("/api/asistencia/admin");
// viaCredentials: el login por email+contraseña nunca cuenta como "del
// dominio" aunque el email tenga forma @kelatos.com (p.ej.

  // ivan.gonzalez@kelatos.com sin cuenta de Gmail real) — es la vía
  // pensada solo para el kiosco, así que confina igual que una cuenta
  // ajena al dominio. 2026-08-31. Excepción: accesoCompleto (petición del
  // usuario, 2026-09-30) — una cuenta así entra igual de completo por
  // Google o por contraseña, las dos puertas llevan al mismo sitio.
  // Iván, Romer y Ricardo entran por el fichaje, como antes; el botón «Ir al dashboard» del fichaje pone la cookie que les deja ver la portada.
  if (
    req.nextUrl.pathname === "/" &&
    req.auth?.user?.asistenciaEmpleadoId != null &&
    aterrizaEnFichaje(req.auth?.user?.email) &&
    !req.cookies.get(COOKIE_IR_DASHBOARD)
  ) {
    return NextResponse.redirect(new URL("/asistencia/kiosk", req.nextUrl.origin));
  }
  const esSoloAsistencia = req.auth?.user?.asistenciaEmpleadoId != null &&
    !req.auth?.user?.accesoCompleto &&
    (req.auth?.user?.viaCredentials || !esDominioKelatos(req.auth?.user?.email || ""));
  if (
    esSoloAsistencia &&
    !enAsistencia &&
    !(esProgramadorContenido(req.auth?.user) && (enProgramarContenido || req.nextUrl.pathname.startsWith("/api/agentes-v2/") || req.nextUrl.pathname.startsWith("/redes-sociales"))) &&
    !(esUsuarioRedes(req.auth?.user) && (esRutaRedesSociales(req.nextUrl.pathname) || req.nextUrl.pathname.startsWith("/api/agentes-v2/")))
  ) {
    return NextResponse.redirect(new URL("/asistencia/kiosk", req.nextUrl.origin));
  }
  if (enAsistenciaAdmin && req.auth?.user?.role !== "admin" && !esSuperadmin(req.auth?.user?.email)) {
    return NextResponse.redirect(new URL("/asistencia/kiosk", req.nextUrl.origin));
  }
});

